import React from 'react';
import { 
  Leaf, 
  Milk, 
  Croissant, 
  Flame, 
  IceCream, 
  Package, 
  Coffee, 
  Sparkles, 
  ShoppingBag 
} from 'lucide-react';

export const CATEGORY_STYLES: Record<string, { color: string; icon: React.ReactNode }> = {
  'Greens & Fruits': { color: '#22c55e', icon: <Leaf className="w-4 h-4" /> },
  'Dairy & Eggs': { color: '#3b82f6', icon: <Milk className="w-4 h-4" /> },
  'Bakery & Breads': { color: '#f59e0b', icon: <Croissant className="w-4 h-4" /> },
  'Meat & Seafood': { color: '#ef4444', icon: <Flame className="w-4 h-4" /> },
  'Frost & Frozen': { color: '#06b6d4', icon: <IceCream className="w-4 h-4" /> },
  'Pantry & Grains': { color: '#8b5cf6', icon: <Package className="w-4 h-4" /> },
  'Beverages': { color: '#ec4899', icon: <Coffee className="w-4 h-4" /> },
  'Household': { color: '#6366f1', icon: <Sparkles className="w-4 h-4" /> },
  'Other': { color: '#71717a', icon: <ShoppingBag className="w-4 h-4" /> },
};

export const INITIAL_PROMPT = `You are a grocery expert. Categorize the given grocery item. 
Available categories: ${Object.keys(CATEGORY_STYLES).join(', ')}.
Return only valid JSON with fields: category, emoji (a single matching emoji), and color (hex code matching the category).`;

import { GoogleGenAI, Type } from "@google/genai";
import { INITIAL_PROMPT } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function categorizeItem(itemName: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Categorize this grocery item: "${itemName}"`,
      config: {
        systemInstruction: INITIAL_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: { type: Type.STRING },
            emoji: { type: Type.STRING },
            color: { type: Type.STRING }
          },
          required: ["category", "emoji", "color"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini categorization failed:", error);
    return {
      category: "Other",
      emoji: "🛒",
      color: "#71717a"
    };
  }
}

export async function searchItemContext(query: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Search for product information for: "${query}". If it looks like a barcode, identify the product name.`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    // Simple extraction of the main name from the response
    return response.text;
  } catch (error) {
    return query;
  }
}

/**
 * Service for Go-UPC integration
 * Docs: https://go-upc.com/docs
 */
export async function lookupBarcode(barcode: string) {
  // Placeholder for the Go-UPC API integration
  // You would typically use process.env.GO_UPC_API_KEY
  const apiKey = "YOUR_GO_UPC_API_KEY_HERE"; 

  if (apiKey === "YOUR_GO_UPC_API_KEY_HERE") {
    console.warn("Go-UPC API Key not set. Using fallback logic.");
    return null;
  }

  try {
    const response = await fetch(`https://go-upc.com/api/v1/code/${barcode}`, {
      headers: {
        "Authorization": `Bearer ${apiKey}`
      }
    });

    if (!response.ok) return null;
    return await response.json();
  } catch (error) {
    console.error("Barcode lookup failed:", error);
    return null;
  }
}

import React, { useState, useRef } from 'react';
import { Search, Barcode, Plus, Loader2 } from 'lucide-react';

interface SearchInputProps {
  onAdd: (query: string) => void;
  isLoading: boolean;
}

const SearchInput: React.FC<SearchInputProps> = ({ onAdd, isLoading }) => {
  const [query, setQuery] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim() && !isLoading) {
      onAdd(query.trim());
      setQuery('');
    }
  };

  return (
    <form 
      onSubmit={handleSubmit}
      className="relative w-full max-w-2xl mx-auto group"
    >
      <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
        <Search className="w-5 h-5 text-zinc-500 group-focus-within:text-purple-500 transition-colors" />
      </div>

      <input
        ref={inputRef}
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search product or enter barcode..."
        className="w-full h-14 pl-12 pr-24 bg-zinc-900/50 border border-zinc-800 rounded-2xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500/50 outline-none transition-all text-zinc-100 placeholder:text-zinc-600 glass"
      />

      <div className="absolute inset-y-2 right-2 flex items-center gap-2">
        <button
          type="button"
          onClick={() => inputRef.current?.focus()}
          className="p-2 text-zinc-500 hover:text-zinc-300 transition-colors"
          title="Barcode Lookup"
        >
          <Barcode className="w-5 h-5" />
        </button>
        <button
          type="submit"
          disabled={!query.trim() || isLoading}
          className="h-10 px-4 bg-zinc-100 hover:bg-white text-zinc-950 rounded-xl font-medium flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95"
        >
          {isLoading ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <>
              <Plus className="w-4 h-4" />
              <span>Add</span>
            </>
          )}
        </button>
      </div>
    </form>
  );
};

export default SearchInput;

import React from 'react';
import { GroceryItem, CategoryGroup } from '../types';
import { CATEGORY_STYLES } from '../constants';
