import React, { useState, useEffect, useCallback } from 'react';
import { ShoppingCart, Sparkles, Zap, Github, Terminal } from 'lucide-react';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import { GroceryItem } from './types';
import { categorizeItem, searchItemContext } from './services/geminiService';
import { lookupBarcode } from './services/upcService';

const App: React.FC = () => {
  const [items, setItems] = useState<GroceryItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('grocai_list');
    if (saved) {
      try {
        setItems(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load list", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('grocai_list', JSON.stringify(items));
  }, [items]);

  const handleAddItem = async (query: string) => {
    setIsLoading(true);
    try {
      let finalName = query;
      let barcode = "";

      // Check if it's a barcode (numeric and length)
      const isBarcode = /^\d{8,14}$/.test(query);

      if (isBarcode) {
        barcode = query;
        // Try Go-UPC first
        const upcResult = await lookupBarcode(query);
        if (upcResult && upcResult.name) {
          finalName = upcResult.name;
        } else {
          // Fallback to Gemini search
          const context = await searchItemContext(query);
          finalName = context || `Product ${query}`;
        }
      }

      // Categorize with Gemini
      const categoryData = await categorizeItem(finalName);

      const newItem: GroceryItem = {
        id: crypto.randomUUID(),
        name: finalName,
        category: categoryData.category,
        emoji: categoryData.emoji,
        color: categoryData.color,
        barcode: barcode || undefined,
        addedAt: Date.now(),
        completed: false
      };

      setItems(prev => [newItem, ...prev]);
    } catch (error) {
      console.error("Add item failed", error);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleItem = (id: string) => {
    setItems(prev => prev.map(item => 
      item.id === id ? { ...item, completed: !item.completed } : item
    ));
  };

  const deleteItem = (id: string) => {
    setItems(prev => prev.filter(item => item.id !== id));
  };

  const clearCompleted = () => {
    setItems(prev => prev.filter(item => !item.completed));
  };

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 selection:bg-purple-500/30">
      {/* Background decor */}
      <div className="fixed top-0 left-1/2 -translate-x-1/2 w-full max-w-6xl h-[500px] bg-purple-500/5 blur-[120px] rounded-full pointer-events-none -z-10" />

      {/* Navigation */}
      <nav className="sticky top-0 z-50 glass border-b border-zinc-800/50">
        <div className="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-zinc-100 rounded-xl flex items-center justify-center">
              <ShoppingCart className="w-5 h-5 text-zinc-950" />
            </div>
            <span className="text-xl font-bold tracking-tight">Groc<span className="text-purple-500">AI</span></span>
          </div>
          <div className="flex items-center gap-4">
            <a href="#" className="text-zinc-400 hover:text-white transition-colors text-sm font-medium">Docs</a>
            <div className="h-4 w-px bg-zinc-800" />
            <a href="#" className="p-2 text-zinc-400 hover:text-white transition-colors">
              <Github className="w-5 h-5" />
            </a>
          </div>
        </div>
      </nav>

      <main className="max-w-5xl mx-auto px-6 py-12 md:py-20">
        {/* Hero Section */}
        <div className="text-center mb-16 space-y-4">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-purple-500/10 border border-purple-500/20 text-purple-400 text-xs font-bold uppercase tracking-wider mb-2">
            <Sparkles className="w-3 h-3" />
            <span>AI-Powered Categorization</span>
          </div>
          <h1 className="text-4xl md:text-6xl font-extrabold tracking-tighter text-white">
            Smart Shopping for <br />
            <span className="bg-gradient-to-r from-purple-400 to-indigo-400 bg-clip-text text-transparent">Modern Living.</span>
          </h1>
          <p className="text-zinc-500 max-w-xl mx-auto text-lg">
            Look up barcodes, categorize groceries automatically, and organize your list with surgical precision.
          </p>
        </div>

        {/* Input area */}
        <div className="sticky top-20 z-40 pb-6 backdrop-blur-sm">
          <SearchInput onAdd={handleAddItem} isLoading={isLoading} />
        </div>

        {/* List Actions */}
        <div className="flex items-center justify-between mb-8 border-b border-zinc-800 pb-4">
          <div className="flex items-center gap-4 text-sm text-zinc-500">
            <div className="flex items-center gap-1.5">
              <Terminal className="w-3.5 h-3.5" />
              <span>{items.length} Items</span>
            </div>
            <div className="flex items-center gap-1.5">
              <Zap className="w-3.5 h-3.5" />
              <span>{items.filter(i => i.completed).length} Done</span>
            </div>
          </div>

          <button 
            onClick={clearCompleted}
            disabled={!items.some(i => i.completed)}
            className="text-xs font-semibold text-zinc-500 hover:text-white transition-colors disabled:opacity-0"
          >
            Clear Completed
          </button>
        </div>

        {/* Grocery List */}
        <GroceryList items={items} onToggle={toggleItem} onDelete={deleteItem} />
      </main>

      {/* Footer */}
      <footer className="mt-40 border-t border-zinc-800/50 py-12 px-6 bg-zinc-950/50">
        <div className="max-w-5xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex items-center gap-2 text-zinc-400">
            <ShoppingCart className="w-4 h-4" />
            <span className="text-sm">© 2024 GrocAI Inc.</span>
          </div>
          <div className="flex gap-8 text-sm text-zinc-500">
            <a href="#" className="hover:text-white transition-colors">Privacy</a>
            <a href="#" className="hover:text-white transition-colors">Terms</a>
            <a href="#" className="hover:text-white transition-colors">Contact</a>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

export interface GroceryItem {
  id: string;
  name: string;
  category: string;
  emoji: string;
  color: string;
  price?: number;
  barcode?: string;
  brand?: string;
  imageUrl?: string;
  addedAt: number;
  completed: boolean;
}

export interface CategoryGroup {
  name: string;
  color: string;
  items: GroceryItem[];
}

export enum GroceryCategory {
  PRODUCE = 'Greens & Fruits',
  DAIRY = 'Dairy & Eggs',
  BAKERY = 'Bakery & Breads',
  MEAT = 'Meat & Seafood',
  FROZEN = 'Frost & Frozen',
  PANTRY = 'Pantry & Grains',
  BEVERAGES = 'Beverages',
  HOUSEHOLD = 'Household',
  OTHER = 'Other'
}

/**
 * Service for Go-UPC integration
 * Docs: https://go-upc.com/docs
 */

export interface GoUPCResponse {
  code: string;
  codeType: string;
  product?: {
    name: string;
    description?: string;
    brand?: string;
    imageUrl?: string;
    upc?: string;
  };
}

export async function lookupBarcode(barcode: string): Promise<GoUPCResponse | null> {
  // Using a placeholder - in a real app, this should be in an env var
  const apiKey = process.env.GO_UPC_API_KEY || "YOUR_GO_UPC_API_KEY_HERE"; 

  if (apiKey === "YOUR_GO_UPC_API_KEY_HERE") {
    console.warn("Go-UPC API Key not set. Lookups will return null.");
    return null;
  }

  try {
    const response = await fetch(`https://go-upc.com/api/v1/code/${barcode}`, {
      headers: {
        "Authorization": `Bearer ${apiKey}`,
        "Content-Type": "application/json"
      }
    });

    if (!response.ok) {
      if (response.status === 404) return null;
      throw new Error(`Go-UPC API responded with status: ${response.status}`);
    }

    const data: GoUPCResponse = await response.json();
    return data;
  } catch (error) {
    console.error("Barcode lookup failed:", error);
    return null;
  }
}

/**
 * Placeholder for future Open Food Facts integration (Great fallback source)
 */
export async function lookupOpenFoodFacts(barcode: string) {
  try {
    const response = await fetch(`https://world.openfoodfacts.org/api/v0/product/${barcode}.json`);
    const data = await response.json();
    if (data.status === 1) {
      return {
        name: data.product.product_name,
        brand: data.product.brands,
        imageUrl: data.product.image_front_small_url
      };
    }
    return null;
  } catch (e) {
    return null;
  }
}

