  const handleAddItem = async (query: string) => {
    setIsLoading(true);
    try {
      let finalName = query;
      let barcode = "";
      let brand = "";
      let imageUrl = "";

      // Check if it's a barcode (numeric and length 8-14)
      const isBarcode = /^\d{8,14}$/.test(query);

      if (isBarcode) {
        barcode = query;
        // 1. Try Go-UPC
