interface SearchInputProps {
  onAdd: (query: string) => void;
  isLoading: boolean;
}

const SearchInput: React.FC<SearchInputProps> = ({ onAdd, isLoading }) => {
  const [query, setQuery] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  // Auto-focus the input on mount so the hardware scanner is ready immediately
  useEffect(() => {
    inputRef.current?.focus();

    // Maintain focus even if user clicks away, to ensure scanner always hits the input
    const handleGlobalClick = () => {
      inputRef.current?.focus();
    };
    window.addEventListener('click', handleGlobalClick);
    return () => window.removeEventListener('click', handleGlobalClick);
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim() && !isLoading) {
      onAdd(query.trim());
      setQuery('');
    }
  };

  return (
    <form 
      onSubmit={handleSubmit}
      className="relative w-full max-w-2xl mx-auto group"
    >
      <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
        <Search className="w-5 h-5 text-zinc-500 group-focus-within:text-purple-500 transition-colors" />
      </div>

      <input
        ref={inputRef}
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Scan barcode or type item..."
        /* inputMode="none" prevents the virtual keyboard from appearing on mobile devices */
        inputMode="none"
