import React, { useState, useRef, useEffect } from 'react';
import { Search, Plus, Loader2, Layers, MousePointer2 } from 'lucide-react';

interface SearchInputProps {
  onAdd: (query: string) => void;
  isLoading: boolean;
}

type EntryMode = 'single' | 'bulk';

const SearchInput: React.FC<SearchInputProps> = ({ onAdd, isLoading }) => {
  const [query, setQuery] = useState('');
  const [mode, setMode] = useState<EntryMode>('single');
  const inputRef = useRef<HTMLInputElement>(null);
  const textAreaRef = useRef<HTMLTextAreaElement>(null);

  // Focus management for hardware scanner
  useEffect(() => {
    const focusTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
    focusTarget?.focus();

    const handleGlobalClick = () => {
      const currentTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
      currentTarget?.focus();
    };

    window.addEventListener('click', handleGlobalClick);
    return () => window.removeEventListener('click', handleGlobalClick);
  }, [mode]);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (query.trim() && !isLoading) {
      onAdd(query.trim());
      setQuery('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      if (mode === 'single') {
        e.preventDefault();
        handleSubmit();
      }
      // In bulk mode, we allow default behavior (new line)
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto space-y-3">
      {/* Mode Switcher */}
      <div className="flex justify-center">
        <div className="inline-flex p-1 bg-zinc-900/80 border border-zinc-800 rounded-xl glass">
          <button
            onClick={() => setMode('single')}
            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${
              mode === 'single' 
                ? 'bg-zinc-100 text-zinc-950 shadow-sm' 
                : 'text-zinc-500 hover:text-zinc-300'
            }`}
          >
            <MousePointer2 className="w-3.5 h-3.5" />
            SINGLE
          </button>
          <button
            onClick={() => setMode('bulk')}
            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${
              mode === 'bulk' 
                ? 'bg-zinc-100 text-zinc-950 shadow-sm' 
                : 'text-zinc-500 hover:text-zinc-300'
            }`}
          >
            <Layers className="w-3.5 h-3.5" />
            BULK
          </button>
        </div>
      </div>

      <div className="relative group">
        <div className="absolute top-5 left-4 pointer-events-none">
          <Search className="w-5 h-5 text-zinc-500 group-focus-within:text-purple-500 transition-colors" />
        </div>

        {mode === 'single' ? (
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Scan single barcode..."
            inputMode="none"
            className="w-full h-16 pl-12 pr-6 bg-zinc-900/50 border border-zinc-800 rounded-2xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500/50 outline-none transition-all text-zinc-100 placeholder:text-zinc-600 glass text-lg font-medium"
          />
        ) : (
          <textarea
            ref={textAreaRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Scan multiple barcodes (one per line)..."
            inputMode="none"
            rows={4}
            className="w-full pl-12 pr-32 py-4 bg-zinc-900/50 border border-zinc-800 rounded-2xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500/50 outline-none transition-all text-zinc-100 placeholder:text-zinc-600 glass text-lg font-medium resize-none"
          />
        )}

        {/* Search button only visible in Bulk mode */}
        {mode === 'bulk' && (
          <div className="absolute top-2 right-2">
            <button
              onClick={() => handleSubmit()}
              disabled={!query.trim() || isLoading}
              className="h-12 px-6 bg-zinc-100 hover:bg-white text-zinc-950 rounded-xl font-bold flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95 shadow-lg shadow-white/5"
            >
              {isLoading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <>
                  <Plus className="w-5 h-5" />
                  <span>Add All</span>
                </>
              )}
            </button>
          </div>
        )}

        {/* Status Indicator */}
        <div className="absolute -bottom-6 left-4 flex items-center gap-1.5 opacity-40">
          <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
          <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-500">
            {mode === 'single' ? 'Auto-Add Active' : 'Bulk Queueing'}
          </span>
        </div>
      </div>
    </div>
  );
};

