import React, { useState, useRef, useEffect } from 'react';
import { Search, Plus, Loader2, Layers, MousePointer2, CornerDownLeft, X, Keyboard } from 'lucide-react';

interface SearchInputProps {
  onAdd: (query: string) => void;
  isLoading: boolean;
}

type EntryMode = 'single' | 'bulk';

const SearchInput: React.FC<SearchInputProps> = ({ onAdd, isLoading }) => {
  const [query, setQuery] = useState('');
  const [mode, setMode] = useState<EntryMode>('single');
  const [isKeyboardEnabled, setIsKeyboardEnabled] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const textAreaRef = useRef<HTMLTextAreaElement>(null);

  // Focus management for hardware scanner
  useEffect(() => {
    const focusTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
    focusTarget?.focus();

    const handleGlobalClick = (e: MouseEvent) => {
      // Don't steal focus if clicking on buttons or interactive elements
      if ((e.target as HTMLElement).closest('button, select, input, textarea')) return;

      const currentTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
      currentTarget?.focus();
    };

    window.addEventListener('click', handleGlobalClick);
    return () => window.removeEventListener('click', handleGlobalClick);
  }, [mode]);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (query.trim() && !isLoading) {
      onAdd(query.trim());
      setQuery('');
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      if (mode === 'single') {
        e.preventDefault();
        handleSubmit();
      }
    }
  };

  const clearInput = () => {
    setQuery('');
    const focusTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
    focusTarget?.focus();
  };

  const toggleKeyboard = () => {
    setIsKeyboardEnabled(!isKeyboardEnabled);
    // Refocus after mode change to trigger/hide keyboard
    setTimeout(() => {
      const focusTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
      focusTarget?.focus();
    }, 50);
  };

  return (
    <div className="w-full max-w-2xl mx-auto space-y-4">
      {/* Mode Switcher */}
      <div className="flex justify-center">
        <div className="inline-flex p-1 bg-zinc-900/80 border border-zinc-800 rounded-xl glass">
          <button
            onClick={() => setMode('single')}
            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${
              mode === 'single' 
                ? 'bg-zinc-100 text-zinc-950 shadow-sm' 
                : 'text-zinc-500 hover:text-zinc-300'
            }`}
          >
            <MousePointer2 className="w-3.5 h-3.5" />
            SINGLE
          </button>
          <button
            onClick={() => setMode('bulk')}
            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${
              mode === 'bulk' 
                ? 'bg-zinc-100 text-zinc-950 shadow-sm' 
                : 'text-zinc-500 hover:text-zinc-300'
            }`}
          >
            <Layers className="w-3.5 h-3.5" />
            BULK
          </button>
        </div>
      </div>

      <div className="relative group">
        <div className="absolute top-5 left-4 pointer-events-none">
          <Search className="w-5 h-5 text-zinc-500 group-focus-within:text-purple-500 transition-colors" />
        </div>

        {mode === 'single' ? (
          <div className="relative">
            <input
              ref={inputRef}
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Scan single barcode..."
              inputMode={isKeyboardEnabled ? "text" : "none"}
              className="w-full h-16 pl-12 pr-14 bg-zinc-900/50 border border-zinc-800 rounded-2xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500/50 outline-none transition-all text-zinc-100 placeholder:text-zinc-600 glass text-lg font-medium"
            />
            {query && (
              <button 
                onClick={clearInput}
                className="absolute right-4 top-1/2 -translate-y-1/2 p-2 text-zinc-500 hover:text-white transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            )}
          </div>
        ) : (
          <div className="relative">
            <textarea
              ref={textAreaRef}
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Scan multiple barcodes (one per line)..."
              inputMode={isKeyboardEnabled ? "text" : "none"}
              rows={5}
              className="w-full pl-12 pr-14 py-4 bg-zinc-900/50 border border-zinc-800 rounded-2xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500/50 outline-none transition-all text-zinc-100 placeholder:text-zinc-600 glass text-lg font-medium resize-none"
            />
            {query && (
              <button 
                onClick={clearInput}
                className="absolute right-4 top-4 p-2 text-zinc-500 hover:text-white transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            )}
          </div>
        )}

        {/* Status Indicator & Keyboard Toggle */}
        <div className="absolute -bottom-8 left-0 right-0 flex items-center justify-between px-2">
          <div className="flex items-center gap-1.5 opacity-40">
            <div className={`w-1.5 h-1.5 rounded-full ${isKeyboardEnabled ? 'bg-purple-500' : 'bg-green-500'} animate-pulse`} />
            <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-500">
              {mode === 'single' ? 'Auto-Add Active' : 'Bulk Queueing'} 
              {isKeyboardEnabled ? ' • Keybd On' : ''}
            </span>
          </div>

          <button
            onClick={toggleKeyboard}
            className={`flex items-center gap-2 px-3 py-1 rounded-lg border transition-all text-[10px] font-bold uppercase tracking-widest ${
              isKeyboardEnabled 
                ? 'bg-purple-500/20 border-purple-500/50 text-purple-400' 
                : 'bg-zinc-900 border-zinc-800 text-zinc-500 hover:text-zinc-300'
            }`}
          >
            <Keyboard className="w-3.5 h-3.5" />
            Keyboard {isKeyboardEnabled ? 'ON' : 'OFF'}
          </button>
        </div>
      </div>

      {/* Bulk Mode Action Row */}
      {mode === 'bulk' && (
        <div className="flex justify-end pt-2 animate-in fade-in slide-in-from-top-2 duration-300">
          <div className="flex items-center gap-3">
            <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-[0.2em]">
              {query.split('\n').filter(l => l.trim()).length} lines ready
            </span>
            <button
              onClick={() => handleSubmit()}
              disabled={!query.trim() || isLoading}
              className="w-12 h-12 flex items-center justify-center bg-zinc-100 hover:bg-white text-zinc-950 rounded-full shadow-xl shadow-white/5 transition-all active:scale-90 disabled:opacity-20 disabled:grayscale group/btn"
              title="Process all items"
            >
              {isLoading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <CornerDownLeft className="w-5 h-5 group-hover/btn:translate-x-0.5 transition-transform" />
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

