import React, { useState } from 'react';
import { GroceryItem } from '../types';
import { CATEGORY_STYLES } from '../constants';
import { 
  CheckCircle2, 
  Circle, 
  Trash2, 
  GripVertical, 
  ShoppingBag, 
  Pencil, 
  Check, 
  X 
} from 'lucide-react';

interface GroceryListProps {
  items: GroceryItem[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<GroceryItem>) => void;
}

const GroceryList: React.FC<GroceryListProps> = ({ items, onToggle, onDelete, onUpdate }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editCategory, setEditCategory] = useState('');

  const groups: Record<string, GroceryItem[]> = items.reduce((acc, item) => {
    if (!acc[item.category]) acc[item.category] = [];
    acc[item.category].push(item);
    return acc;
  }, {} as Record<string, GroceryItem[]>);

  const sortedCategories = Object.keys(groups).sort();

  const startEditing = (item: GroceryItem) => {
    if (item.completed) return;
    setEditingId(item.id);
    setEditName(item.name);
    setEditCategory(item.category);
  };

  const cancelEditing = () => {
    setEditingId(null);
  };

  const saveEditing = () => {
    if (editingId) {
      onUpdate(editingId, { 
        name: editName, 
        category: editCategory,
        // Update color and emoji if category changed
        color: CATEGORY_STYLES[editCategory]?.color || CATEGORY_STYLES['Other'].color,
      });
      setEditingId(null);
    }
  };

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-zinc-500">
        <div className="w-16 h-16 bg-zinc-900 rounded-full flex items-center justify-center mb-4 ring-1 ring-zinc-800">
          <ShoppingBag className="w-8 h-8 opacity-20" />
        </div>
        <p className="text-lg font-medium">Your list is empty</p>
        <p className="text-sm">Search for items or scan barcodes to get started</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 mt-12 pb-24">
      {sortedCategories.map((cat) => (
        <div key={cat} className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="flex items-center gap-2 mb-4">
            <div 
              className="w-8 h-8 rounded-lg flex items-center justify-center text-white"
              style={{ backgroundColor: CATEGORY_STYLES[cat]?.color || '#71717a' }}
            >
              {CATEGORY_STYLES[cat]?.icon || CATEGORY_STYLES['Other'].icon}
            </div>
            <h3 className="font-semibold text-zinc-200 tracking-tight">{cat}</h3>
            <span className="ml-auto text-xs font-medium text-zinc-500 bg-zinc-900 px-2 py-1 rounded-full border border-zinc-800">
              {groups[cat].length}
            </span>
          </div>

          <div className="grid grid-cols-1 gap-2">
            {groups[cat].map((item) => {
              const isEditing = editingId === item.id;

              return (
                <div 
                  key={item.id}
                  className={`group flex items-center gap-3 p-3 bg-zinc-900/40 hover:bg-zinc-800/40 rounded-xl border border-zinc-800/50 transition-all ${item.completed ? 'opacity-40 grayscale-[0.5]' : ''} ${isEditing ? 'ring-2 ring-purple-500/50 bg-zinc-800/60' : ''}`}
                >
                  {!isEditing && (
                    <button 
                      onClick={() => onToggle(item.id)}
                      className="shrink-0 text-zinc-500 hover:text-purple-500 transition-colors pl-1"
                    >
                      {item.completed ? (
                        <CheckCircle2 className="w-5 h-5 text-purple-500" />
                      ) : (
                        <Circle className="w-5 h-5" />
                      )}
                    </button>
                  )}

                  {/* Product Image or Emoji */}
                  <div className="w-12 h-12 shrink-0 rounded-lg bg-zinc-800/50 flex items-center justify-center overflow-hidden border border-zinc-700/30">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                    ) : (
                      <span className="text-2xl">{item.emoji}</span>
                    )}
                  </div>

                  <div className="flex-1 min-w-0">
                    {isEditing ? (
                      <div className="space-y-2 pr-2">
                        <input
                          autoFocus
                          value={editName}
                          onChange={(e) => setEditName(e.target.value)}
                          className="w-full bg-zinc-950 border border-zinc-700 rounded-lg px-2 py-1 text-sm text-white focus:ring-1 focus:ring-purple-500 outline-none"
                        />
                        <select
                          value={editCategory}
                          onChange={(e) => setEditCategory(e.target.value)}
                          className="w-full bg-zinc-950 border border-zinc-700 rounded-lg px-2 py-1 text-[10px] text-zinc-300 font-bold uppercase tracking-wider outline-none"
                        >
                          {Object.keys(CATEGORY_STYLES).map(c => (
                            <option key={c} value={c}>{c}</option>
                          ))}
                        </select>
                      </div>
                    ) : (
                      <>
                        <p className={`font-medium truncate ${item.completed ? 'line-through text-zinc-600' : 'text-zinc-200'}`}>
                          {item.name}
                        </p>
                        <div className="flex items-center gap-2">
                          {item.brand && (
                            <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest bg-zinc-800 px-1.5 py-0.5 rounded">
                              {item.brand}
                            </span>
                          )}
                          {item.barcode && (
                            <span className="text-[10px] text-zinc-600 font-mono tracking-wider">
                              #{item.barcode}
                            </span>
                          )}
                        </div>
                      </>
                    )}
                  </div>

                  <div className="flex items-center gap-1">
                    {isEditing ? (
                      <>
                        <button 
                          onClick={saveEditing}
                          className="p-2 text-green-400 hover:bg-green-400/10 rounded-lg transition-all"
                        >
                          <Check className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={cancelEditing}
                          className="p-2 text-zinc-400 hover:bg-zinc-700 rounded-lg transition-all"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </>
                    ) : (
                      <>
                        {!item.completed && (
                          <button 
                            onClick={() => startEditing(item)}
                            className="opacity-0 group-hover:opacity-100 p-2 text-zinc-600 hover:text-purple-400 hover:bg-purple-400/10 rounded-lg transition-all"
                          >
                            <Pencil className="w-4 h-4" />
                          </button>
                        )}
                        <button 
                          onClick={() => onDelete(item.id)}
                          className="opacity-0 group-hover:opacity-100 p-2 text-zinc-600 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                        <div className="p-1 text-zinc-800 group-hover:text-zinc-700">
                          <GripVertical className="w-4 h-4" />
                        </div>
                      </>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
};

