import React, { useState, useEffect } from 'react';
import { ShoppingCart, Sparkles, Zap, Github, Terminal } from 'lucide-react';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import { GroceryItem } from './types';
import { categorizeItem, searchItemContext } from './services/geminiService';
import { lookupBarcode } from './services/upcService';

const App: React.FC = () => {
  const [items, setItems] = useState<GroceryItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('grocai_list');
    if (saved) {
      try {
        setItems(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load list", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('grocai_list', JSON.stringify(items));
  }, [items]);

  const processSingleLine = async (line: string): Promise<GroceryItem | null> => {
    const trimmedLine = line.trim();
    if (!trimmedLine) return null;

    let finalName = trimmedLine;
    let barcode = "";
    let brand = "";
    let imageUrl = "";

    // Check if it's a barcode (numeric and length 8-14)
    const isBarcode = /^\d{8,14}$/.test(trimmedLine);

    if (isBarcode) {
      barcode = trimmedLine;
      const upcResult = await lookupBarcode(trimmedLine);

      if (upcResult?.product) {
        finalName = upcResult.product.name;
        brand = upcResult.product.brand || "";
        imageUrl = upcResult.product.imageUrl || "";
      } else {
        const context = await searchItemContext(trimmedLine);
        finalName = context || `Product ${trimmedLine}`;
      }
    }

    const categoryData = await categorizeItem(finalName);

    return {
      id: crypto.randomUUID(),
      name: finalName,
      category: categoryData.category,
      emoji: categoryData.emoji,
      color: categoryData.color,
      barcode: barcode || undefined,
      brand: brand || undefined,
      imageUrl: imageUrl || undefined,
      addedAt: Date.now(),
      completed: false
    };
  };

  const handleAddItem = async (query: string) => {
    setIsLoading(true);
    try {
      // Split by newline to support bulk input
      const lines = query.split('\n').filter(l => l.trim().length > 0);

      // Process lines in parallel for faster bulk addition
      const newItemsPromises = lines.map(line => processSingleLine(line));
      const results = await Promise.all(newItemsPromises);

      const validNewItems = results.filter((item): item is GroceryItem => item !== null);

      if (validNewItems.length > 0) {
        setItems(prev => [...validNewItems, ...prev]);
      }
    } catch (error) {
      console.error("Add item(s) failed", error);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleItem = (id: string) => {
    setItems(prev => prev.map(item => 
      item.id === id ? { ...item, completed: !item.completed } : item
    ));
  };

  const updateItem = (id: string, updates: Partial<GroceryItem>) => {
    setItems(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const deleteItem = (id: string) => {
    setItems(prev => prev.filter(item => item.id !== id));
  };

  const clearCompleted = () => {
    setItems(prev => prev.filter(item => !item.completed));
  };

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 selection:bg-purple-500/30">
      {/* Background decor */}
      <div className="fixed top-0 left-1/2 -translate-x-1/2 w-full max-w-6xl h-[500px] bg-purple-500/5 blur-[120px] rounded-full pointer-events-none -z-10" />

      {/* Navigation */}
      <nav className="sticky top-0 z-50 glass border-b border-zinc-800/50">
        <div className="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-zinc-100 rounded-xl flex items-center justify-center">
              <ShoppingCart className="w-5 h-5 text-zinc-950" />
            </div>
            <span className="text-xl font-bold tracking-tight">Groc<span className="text-purple-500">AI</span></span>
          </div>
          <div className="flex items-center gap-4">
            <a href="#" className="text-zinc-400 hover:text-white transition-colors text-sm font-medium">Docs</a>
            <div className="h-4 w-px bg-zinc-800" />
            <a href="#" className="p-2 text-zinc-400 hover:text-white transition-colors">
              <Github className="w-5 h-5" />
            </a>
          </div>
        </div>
      </nav>

      <main className="max-w-5xl mx-auto px-6 py-12 md:py-20">
        {/* Hero Section */}
        <div className="text-center mb-16 space-y-4">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-purple-500/10 border border-purple-500/20 text-purple-400 text-xs font-bold uppercase tracking-wider mb-2">
            <Sparkles className="w-3 h-3" />
            <span>AI-Powered Categorization</span>
          </div>
          <h1 className="text-4xl md:text-6xl font-extrabold tracking-tighter text-white">
            Smart Shopping for <br />
            <span className="bg-gradient-to-r from-purple-400 to-indigo-400 bg-clip-text text-transparent">Modern Living.</span>
          </h1>
          <p className="text-zinc-500 max-w-xl mx-auto text-lg">
            Scan single items for instant results or switch to Bulk for rapid-fire stock intake.
          </p>
        </div>

        {/* Input area */}
        <div className="sticky top-20 z-40 pb-6 backdrop-blur-sm">
          <SearchInput onAdd={handleAddItem} isLoading={isLoading} />
        </div>

        {/* List Actions */}
