import React, { useState, useEffect, useCallback } from 'react';
import { ShoppingCart, Sparkles, Zap, Github, Terminal, Undo2, Redo2 } from 'lucide-react';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import { GroceryItem } from './types';
import { categorizeItem, searchItemContext } from './services/geminiService';
import { lookupBarcode } from './services/upcService';

const App: React.FC = () => {
  const [items, setItems] = useState<GroceryItem[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // History state for Undo/Redo
  const [past, setPast] = useState<GroceryItem[][]>([]);
  const [future, setFuture] = useState<GroceryItem[][]>([]);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('grocai_list');
    if (saved) {
      try {
        setItems(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load list", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('grocai_list', JSON.stringify(items));
  }, [items]);

  // Helper to update state with history
  const updateItemsWithHistory = useCallback((newItems: GroceryItem[] | ((prev: GroceryItem[]) => GroceryItem[])) => {
    setItems(prev => {
      const nextState = typeof newItems === 'function' ? newItems(prev) : newItems;
      // Only push to history if state actually changed
      if (JSON.stringify(prev) !== JSON.stringify(nextState)) {
        setPast(p => [...p, prev]);
        setFuture([]); // Clear redo stack on new action
      }
      return nextState;
    });
  }, [items]); // items included to ensure stringify uses current

  const undo = useCallback(() => {
    if (past.length === 0) return;
    const previous = past[past.length - 1];
    const newPast = past.slice(0, past.length - 1);

    setFuture(prevFuture => [items, ...prevFuture]);
    setPast(newPast);
    setItems(previous);
  }, [past, items]);

  const redo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    const newFuture = future.slice(1);

    setPast(prevPast => [...prevPast, items]);
    setFuture(newFuture);
    setItems(next);
  }, [future, items]);

  // Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        if (e.shiftKey) {
          redo();
        } else {
          undo();
        }
      } else if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
        redo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  const processSingleLine = async (line: string): Promise<GroceryItem | null> => {
    const trimmedLine = line.trim();
    if (!trimmedLine) return null;

    let finalName = trimmedLine;
    let barcode = "";
    let brand = "";
    let imageUrl = "";

    const isBarcode = /^\d{8,14}$/.test(trimmedLine);

    if (isBarcode) {
      barcode = trimmedLine;
      const upcResult = await lookupBarcode(trimmedLine);

      if (upcResult?.product) {
        finalName = upcResult.product.name;
        brand = upcResult.product.brand || "";
        imageUrl = upcResult.product.imageUrl || "";
      } else {
        const context = await searchItemContext(trimmedLine);
        finalName = context || `Product ${trimmedLine}`;
      }
    }

    const categoryData = await categorizeItem(finalName);

    return {
      id: crypto.randomUUID(),
      name: finalName,
      category: categoryData.category,
      emoji: categoryData.emoji,
      color: categoryData.color,
      barcode: barcode || undefined,
      brand: brand || undefined,
      imageUrl: imageUrl || undefined,
      addedAt: Date.now(),
      completed: false
    };
  };

  const handleAddItem = async (query: string) => {
    setIsLoading(true);
    try {
      const lines = query.split('\n').filter(l => l.trim().length > 0);
      const newItemsPromises = lines.map(line => processSingleLine(line));
      const results = await Promise.all(newItemsPromises);
      const validNewItems = results.filter((item): item is GroceryItem => item !== null);

      if (validNewItems.length > 0) {
        updateItemsWithHistory(prev => [...validNewItems, ...prev]);
      }
    } catch (error) {
      console.error("Add item(s) failed", error);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleItem = (id: string) => {
    updateItemsWithHistory(prev => prev.map(item => 
      item.id === id ? { ...item, completed: !item.completed } : item
    ));
  };

  const updateItem = (id: string, updates: Partial<GroceryItem>) => {
    updateItemsWithHistory(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const deleteItem = (id: string) => {
    updateItemsWithHistory(prev => prev.filter(item => item.id !== id));
  };

  const clearCompleted = () => {
    updateItemsWithHistory(prev => prev.filter(item => !item.completed));
  };

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 selection:bg-purple-500/30">
      <div className="fixed top-0 left-1/2 -translate-x-1/2 w-full max-w-6xl h-[500px] bg-purple-500/5 blur-[120px] rounded-full pointer-events-none -z-10" />

      <nav className="sticky top-0 z-50 glass border-b border-zinc-800/50">
        <div className="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-zinc-100 rounded-xl flex items-center justify-center">
              <ShoppingCart className="w-5 h-5 text-zinc-950" />
            </div>
            <span className="text-xl font-bold tracking-tight">Groc<span className="text-purple-500">AI</span></span>
          </div>
          <div className="flex items-center gap-4">
            <div className="flex items-center bg-zinc-900/50 border border-zinc-800 rounded-lg p-0.5">
              <button 
                onClick={undo}
                disabled={past.length === 0}
                className="p-1.5 text-zinc-500 hover:text-white disabled:opacity-20 transition-colors"
                title="Undo (Ctrl+Z)"
              >
                <Undo2 className="w-4 h-4" />
              </button>
              <button 
                onClick={redo}
                disabled={future.length === 0}
                className="p-1.5 text-zinc-500 hover:text-white disabled:opacity-20 transition-colors"
                title="Redo (Ctrl+Y)"
              >
                <Redo2 className="w-4 h-4" />
              </button>
            </div>
            <div className="h-4 w-px bg-zinc-800" />
            <a href="#" className="p-2 text-zinc-400 hover:text-white transition-colors">
              <Github className="w-5 h-5" />
            </a>
          </div>
        </div>
      </nav>

      <main className="max-w-5xl mx-auto px-6 py-12 md:py-20">
        <div className="text-center mb-16 space-y-4">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-purple-500/10 border border-purple-500/20 text-purple-400 text-xs font-bold uppercase tracking-wider mb-2">
            <Sparkles className="w-3 h-3" />
            <span>AI-Powered Categorization</span>
          </div>
          <h1 className="text-4xl md:text-6xl font-extrabold tracking-tighter text-white">
            Smart Shopping for <br />
            <span className="bg-gradient-to-r from-purple-400 to-indigo-400 bg-clip-text text-transparent">Modern Living.</span>
          </h1>
          <p className="text-zinc-500 max-w-xl mx-auto text-lg">
            Scan single items for instant results or switch to Bulk for rapid-fire stock intake.
          </p>
        </div>

        <div className="sticky top-20 z-40 pb-6 backdrop-blur-sm">
          <SearchInput onAdd={handleAddItem} isLoading={isLoading} />
        </div>

        <div className="flex items-center justify-between mt-16 mb-8 border-b border-zinc-800 pb-4">
          <div className="flex items-center gap-4 text-sm text-zinc-500">
            <div className="flex items-center gap-1.5">
              <Terminal className="w-3.5 h-3.5" />
              <span>{items.length} Items</span>
            </div>
            <div className="flex items-center gap-1.5">
              <Zap className="w-3.5 h-3.5" />
              <span>{items.filter(i => i.completed).length} Done</span>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {/* History indicator for visual feedback */}
             {(past.length > 0 || future.length > 0) && (
               <div className="hidden sm:flex items-center gap-2 px-2 py-0.5 rounded bg-zinc-900 border border-zinc-800 text-[10px] text-zinc-600 font-mono">
                  <span>P:{past.length}</span>
                  <span>F:{future.length}</span>
               </div>
             )}
             <button 
              onClick={clearCompleted}
              disabled={!items.some(i => i.completed)}
              className="text-xs font-semibold text-zinc-500 hover:text-white transition-colors disabled:opacity-0"
            >
              Clear Completed
            </button>
          </div>
        </div>

        <GroceryList 
          items={items} 
          onToggle={toggleItem} 
          onDelete={deleteItem} 
          onUpdate={updateItem}
        />
      </main>

      <footer className="mt-40 border-t border-zinc-800/50 py-12 px-6 bg-zinc-950/50">
        <div className="max-w-5xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
          <div className="flex items-center gap-2 text-zinc-400">
            <ShoppingCart className="w-4 h-4" />
            <span className="text-sm">© 2024 GrocAI Inc.</span>
          </div>
          <div className="flex gap-8 text-sm text-zinc-500">
            <a href="#" className="hover:text-white transition-colors">Privacy</a>
            <a href="#" className="hover:text-white transition-colors">Terms</a>
            <a href="#" className="hover:text-white transition-colors">Contact</a>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { 
  Leaf, 
  Milk, 
  Croissant, 
  Flame, 
  IceCream, 
  Package, 
  Coffee, 
  Sparkles, 
  ShoppingBag 
} from 'lucide-react';

export const CATEGORY_STYLES: Record<string, { color: string; icon: React.ReactNode }> = {
  'Greens & Fruits': { color: '#22c55e', icon: <Leaf className="w-4 h-4" /> },
  'Dairy & Eggs': { color: '#3b82f6', icon: <Milk className="w-4 h-4" /> },
  'Bakery & Breads': { color: '#f59e0b', icon: <Croissant className="w-4 h-4" /> },
  'Meat & Seafood': { color: '#ef4444', icon: <Flame className="w-4 h-4" /> },
  'Frost & Frozen': { color: '#06b6d4', icon: <IceCream className="w-4 h-4" /> },
  'Pantry & Grains': { color: '#8b5cf6', icon: <Package className="w-4 h-4" /> },
  'Beverages': { color: '#ec4899', icon: <Coffee className="w-4 h-4" /> },
  'Household': { color: '#6366f1', icon: <Sparkles className="w-4 h-4" /> },
  'Other': { color: '#71717a', icon: <ShoppingBag className="w-4 h-4" /> },
};

const CATEGORY_MAP_STRING = Object.entries(CATEGORY_STYLES)
  .map(([name, style]) => `- ${name}: ${style.color}`)
  .join('\n');

export const INITIAL_PROMPT = `You are a professional grocery categorization expert. Your task is to categorize a grocery item into one of the predefined categories and provide a matching color and emoji.

Mandatory Rules:
1. Category: Must be exactly one of the following strings: ${Object.keys(CATEGORY_STYLES).join(', ')}.
2. Color: Must be the specific hex code associated with the chosen category:
${CATEGORY_MAP_STRING}
3. Emoji: Must be a single, relevant emoji character.
4. Response: Return strictly valid JSON.

Item to categorize: `;

import { GoogleGenAI, Type } from "@google/genai";
import { INITIAL_PROMPT, CATEGORY_STYLES } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function categorizeItem(itemName: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: itemName,
      config: {
        systemInstruction: INITIAL_PROMPT,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: { 
              type: Type.STRING,
              description: "The exact category name from the allowed list."
            },
            emoji: { 
              type: Type.STRING, 
              description: "A single emoji character that represents the item." 
            },
            color: { 
              type: Type.STRING, 
              description: "The hex color code that corresponds exactly to the selected category." 
            }
          },
          required: ["category", "emoji", "color"]
        }
      }
    });

    const result = JSON.parse(response.text);

    // Safety check: ensure the category actually exists in our local styles
    if (!CATEGORY_STYLES[result.category]) {
      result.category = "Other";
      result.color = CATEGORY_STYLES["Other"].color;
    }

    return result;
  } catch (error) {
    console.error("Gemini categorization failed:", error);
    return {
      category: "Other",
      emoji: "🛒",
      color: "#71717a"
    };
  }
}

export async function searchItemContext(query: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Search for product information for: "${query}". If it looks like a barcode, identify the product name. Return only the common name of the product.`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    return response.text;
  } catch (error) {
    return query;
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { Search, Loader2, Layers, MousePointer2, CornerDownLeft, X, Keyboard, CheckCircle2 } from 'lucide-react';

interface SearchInputProps {
  onAdd: (query: string) => void;
  isLoading: boolean;
}

type EntryMode = 'single' | 'bulk';

const SearchInput: React.FC<SearchInputProps> = ({ onAdd, isLoading }) => {
  const [query, setQuery] = useState('');
  const [mode, setMode] = useState<EntryMode>('single');
  const [isKeyboardEnabled, setIsKeyboardEnabled] = useState(false);
  const [lastAdded, setLastAdded] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const textAreaRef = useRef<HTMLTextAreaElement>(null);

  // Focus management for hardware scanner
  useEffect(() => {
    const focusTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
    focusTarget?.focus();

    const handleGlobalClick = (e: MouseEvent) => {
      if ((e.target as HTMLElement).closest('button, select, input, textarea')) return;
      const currentTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
      currentTarget?.focus();
    };

    window.addEventListener('click', handleGlobalClick);
    return () => window.removeEventListener('click', handleGlobalClick);
  }, [mode]);

  // Flash success state when loading finishes
  useEffect(() => {
    if (!isLoading && lastAdded) {
      const timer = setTimeout(() => setLastAdded(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [isLoading, lastAdded]);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (query.trim() && !isLoading) {
      const currentQuery = query.trim();
      setLastAdded(true);
      onAdd(currentQuery);
      setQuery(''); // Clear immediately for snappy scanner performance
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      if (mode === 'single') {
        e.preventDefault();
        handleSubmit();
      }
    }
  };

  const clearInput = () => {
    setQuery('');
    const focusTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
    focusTarget?.focus();
  };

  const toggleKeyboard = () => {
    setIsKeyboardEnabled(!isKeyboardEnabled);
    setTimeout(() => {
      const focusTarget = mode === 'single' ? inputRef.current : textAreaRef.current;
      focusTarget?.focus();
    }, 50);
  };

  return (
    <div className="w-full max-w-2xl mx-auto space-y-4">
      {/* Mode Switcher */}
      <div className="flex justify-center">
        <div className="inline-flex p-1 bg-zinc-900/80 border border-zinc-800 rounded-xl glass">
          <button
            onClick={() => setMode('single')}
            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${
              mode === 'single' 
                ? 'bg-zinc-100 text-zinc-950 shadow-sm' 
                : 'text-zinc-500 hover:text-zinc-300'
            }`}
          >
            <MousePointer2 className="w-3.5 h-3.5" />
            SINGLE
          </button>
          <button
            onClick={() => setMode('bulk')}
            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${
              mode === 'bulk' 
                ? 'bg-zinc-100 text-zinc-950 shadow-sm' 
                : 'text-zinc-500 hover:text-zinc-300'
            }`}
          >
            <Layers className="w-3.5 h-3.5" />
            BULK
          </button>
        </div>
      </div>

      <div className="relative group">
        <div className="absolute top-5 left-4 pointer-events-none z-10">
          {isLoading && mode === 'single' ? (
            <Loader2 className="w-5 h-5 text-purple-500 animate-spin" />
          ) : lastAdded && mode === 'single' ? (
            <CheckCircle2 className="w-5 h-5 text-green-500 animate-in zoom-in duration-300" />
          ) : (
            <Search className="w-5 h-5 text-zinc-500 group-focus-within:text-purple-500 transition-colors" />
          )}
        </div>

        {mode === 'single' ? (
          <div className="relative">
            <input
              ref={inputRef}
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={handleKeyDown}
              disabled={isLoading && mode === 'single'}
              placeholder={isLoading ? "Processing item..." : "Scan single barcode..."}
              inputMode={isKeyboardEnabled ? "text" : "none"}
              className={`w-full h-16 pl-12 pr-14 bg-zinc-900/50 border rounded-2xl outline-none transition-all text-zinc-100 placeholder:text-zinc-600 glass text-lg font-medium ${
                isLoading ? 'border-purple-500/50 ring-2 ring-purple-500/10' : 'border-zinc-800 focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500/50'
              }`}
            />
            {query && !isLoading && (
              <button 
                onClick={clearInput}
                className="absolute right-4 top-1/2 -translate-y-1/2 p-2 text-zinc-500 hover:text-white transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            )}
            {isLoading && (
               <div className="absolute right-6 top-1/2 -translate-y-1/2 flex items-center gap-2">
                 <span className="text-[10px] font-bold text-purple-500 uppercase tracking-widest animate-pulse">Lookup</span>
               </div>
            )}
          </div>
        ) : (
          <div className="relative">
            <textarea
              ref={textAreaRef}
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Scan multiple barcodes (one per line)..."
              inputMode={isKeyboardEnabled ? "text" : "none"}
              rows={5}
              className="w-full pl-12 pr-14 py-4 bg-zinc-900/50 border border-zinc-800 rounded-2xl focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500/50 outline-none transition-all text-zinc-100 placeholder:text-zinc-600 glass text-lg font-medium resize-none"
            />
            {query && (
              <button 
                onClick={clearInput}
                className="absolute right-4 top-4 p-2 text-zinc-500 hover:text-white transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            )}
          </div>
        )}

        {/* Status Indicator & Keyboard Toggle */}
        <div className="absolute -bottom-8 left-0 right-0 flex items-center justify-between px-2">
          <div className="flex items-center gap-1.5 opacity-40">
            <div className={`w-1.5 h-1.5 rounded-full ${isLoading ? 'bg-purple-500' : 'bg-green-500'} animate-pulse`} />
            <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-500">
              {isLoading ? 'Processing' : mode === 'single' ? 'Auto-Add Active' : 'Bulk Queueing'} 
              {isKeyboardEnabled ? ' • Keybd On' : ''}
            </span>
          </div>

          <button
            onClick={toggleKeyboard}
            className={`flex items-center gap-2 px-3 py-1 rounded-lg border transition-all text-[10px] font-bold uppercase tracking-widest ${
              isKeyboardEnabled 
                ? 'bg-purple-500/20 border-purple-500/50 text-purple-400' 
                : 'bg-zinc-900 border-zinc-800 text-zinc-500 hover:text-zinc-300'
            }`}
          >
            <Keyboard className="w-3.5 h-3.5" />
            Keyboard {isKeyboardEnabled ? 'ON' : 'OFF'}
          </button>
        </div>
      </div>

      {/* Bulk Mode Action Row */}
      {mode === 'bulk' && (
        <div className="flex justify-end pt-2 animate-in fade-in slide-in-from-top-2 duration-300">
          <div className="flex items-center gap-3">
            <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-[0.2em]">
              {query.split('\n').filter(l => l.trim()).length} lines ready
            </span>
            <button
              onClick={() => handleSubmit()}
              disabled={!query.trim() || isLoading}
              className="w-12 h-12 flex items-center justify-center bg-zinc-100 hover:bg-white text-zinc-950 rounded-full shadow-xl shadow-white/5 transition-all active:scale-90 disabled:opacity-20 disabled:grayscale group/btn"
              title="Process all items"
            >
              {isLoading ? (
                <Loader2 className="w-5 h-5 animate-spin" />
              ) : (
                <CornerDownLeft className="w-5 h-5 group-hover/btn:translate-x-0.5 transition-transform" />
              )}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default SearchInput;

