export interface CategoryGroup {
  name: string;
  color: string;
  items: GroceryItem[];
}

export enum GroceryCategory {
  PRODUCE = 'Greens & Fruits',
  DAIRY = 'Dairy & Eggs',
  BAKERY = 'Bakery & Breads',
  MEAT = 'Meat & Seafood',
  FROZEN = 'Frost & Frozen',
  PANTRY = 'Pantry & Grains',
  BEVERAGES = 'Beverages',
  HOUSEHOLD = 'Household',
  OTHER = 'Other'
}

import React, { useState } from 'react';
import { 
  Plus, 
  List, 
  Trash2, 
  MoreVertical, 
  Pencil, 
  Check, 
  X,
  Menu,
  ChevronLeft,
  LayoutGrid
} from 'lucide-react';
import { ShoppingList } from '../types';

interface SidebarProps {
  lists: ShoppingList[];
  activeListId: string;
  onSelectList: (id: string) => void;
  onCreateList: (name: string) => void;
  onDeleteList: (id: string) => void;
  onRenameList: (id: string, newName: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
  lists, 
  activeListId, 
  onSelectList, 
  onCreateList, 
  onDeleteList, 
  onRenameList 
}) => {
  const [isOpen, setIsOpen] = useState(true);
  const [isCreating, setIsCreating] = useState(false);
  const [newListName, setNewListName] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (newListName.trim()) {
      onCreateList(newListName.trim());
      setNewListName('');
      setIsCreating(false);
    }
  };

  const handleStartRename = (list: ShoppingList) => {
    setEditingId(list.id);
    setEditName(list.name);
  };

  const handleSaveRename = () => {
    if (editingId && editName.trim()) {
      onRenameList(editingId, editName.trim());
      setEditingId(null);
    }
  };

  return (
    <>
      {/* Mobile Toggle */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="lg:hidden fixed bottom-6 right-6 z-[60] w-14 h-14 bg-purple-600 text-white rounded-full shadow-2xl flex items-center justify-center active:scale-95 transition-transform"
      >
        {isOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
      </button>

      <div className={`fixed inset-y-0 left-0 z-50 w-72 bg-[#09090b] border-r border-zinc-800 transition-transform duration-300 lg:translate-x-0 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex flex-col h-full">
          {/* Header */}
          <div className="p-6 border-b border-zinc-800 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <LayoutGrid className="w-5 h-5 text-purple-500" />
              <span className="font-bold text-lg tracking-tight">Your Lists</span>
            </div>
            <button 
              onClick={() => setIsOpen(false)} 
              className="lg:hidden p-2 text-zinc-500 hover:text-white"
            >
              <ChevronLeft className="w-5 h-5" />
            </button>
          </div>

          {/* List Content */}
          <div className="flex-1 overflow-y-auto p-4 space-y-2">
            {lists.map((list) => (
              <div 
                key={list.id}
                className={`group relative flex items-center gap-3 p-3 rounded-xl transition-all cursor-pointer ${activeListId === list.id ? 'bg-purple-500/10 text-purple-400 ring-1 ring-purple-500/30' : 'text-zinc-400 hover:bg-zinc-900 hover:text-zinc-200'}`}
                onClick={() => onSelectList(list.id)}
              >
                <List className={`w-4 h-4 shrink-0 ${activeListId === list.id ? 'text-purple-400' : 'text-zinc-600'}`} />

                {editingId === list.id ? (
                  <div className="flex-1 flex items-center gap-1" onClick={e => e.stopPropagation()}>
                    <input 
                      autoFocus
                      value={editName}
                      onChange={e => setEditName(e.target.value)}
                      onKeyDown={e => e.key === 'Enter' && handleSaveRename()}
                      className="w-full bg-zinc-950 border border-zinc-700 rounded px-1.5 py-0.5 text-sm text-white focus:ring-1 focus:ring-purple-500 outline-none"
                    />
                    <button onClick={handleSaveRename} className="p-1 text-green-500"><Check className="w-3.5 h-3.5" /></button>
                  </div>
                ) : (
                  <span className="flex-1 text-sm font-medium truncate">{list.name}</span>
                )}

                <div className="hidden group-hover:flex items-center gap-1">
                  {editingId !== list.id && (
                    <>
                      <button 
                        onClick={(e) => { e.stopPropagation(); handleStartRename(list); }}
                        className="p-1.5 text-zinc-500 hover:text-white rounded-md hover:bg-zinc-800 transition-colors"
                      >
                        <Pencil className="w-3.5 h-3.5" />
                      </button>
                      <button 
                        onClick={(e) => { e.stopPropagation(); onDeleteList(list.id); }}
                        className="p-1.5 text-zinc-500 hover:text-red-400 rounded-md hover:bg-red-400/10 transition-colors"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </>
                  )}
                </div>
              </div>
            ))}

            {isCreating ? (
              <form onSubmit={handleCreate} className="p-2 bg-zinc-900/50 rounded-xl border border-dashed border-zinc-700 mt-4 animate-in fade-in zoom-in-95 duration-200">
                <input 
                  autoFocus
                  placeholder="List name..."
                  value={newListName}
                  onChange={e => setNewListName(e.target.value)}
                  className="w-full bg-transparent text-sm text-white px-2 py-1 outline-none"
                />
                <div className="flex justify-end gap-1 mt-2">
                  <button type="button" onClick={() => setIsCreating(false)} className="p-1.5 text-zinc-500 hover:text-white"><X className="w-4 h-4" /></button>
                  <button type="submit" className="p-1.5 text-purple-500 hover:text-purple-400"><Check className="w-4 h-4" /></button>
                </div>
              </form>
            ) : (
              <button 
                onClick={() => setIsCreating(true)}
                className="w-full flex items-center gap-3 p-3 text-zinc-500 hover:text-zinc-200 hover:bg-zinc-900 rounded-xl transition-all border border-dashed border-zinc-800 mt-4"
              >
                <Plus className="w-4 h-4" />
                <span className="text-sm font-medium">Create new list</span>
              </button>
            )}
          </div>

          {/* Footer Info */}
          <div className="p-6 border-t border-zinc-800 text-[10px] text-zinc-600 font-bold uppercase tracking-widest">
            {lists.length} active lists
          </div>
        </div>
      </div>

      {/* Backdrop for mobile */}
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden"
          onClick={() => setIsOpen(false)}
        />
      )}
    </>
  );
};

export default Sidebar;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { ShoppingCart, Sparkles, Zap, Github, Terminal, Undo2, Redo2, Layers } from 'lucide-react';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import Sidebar from './components/Sidebar';
import { GroceryItem, ShoppingList } from './types';
import { categorizeItem, searchItemContext } from './services/geminiService';
import { lookupBarcode } from './services/upcService';

const App: React.FC = () => {
  // Global state now manages multiple lists
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [activeListId, setActiveListId] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  // History state for Undo/Redo (tracks the entire lists array)
  const [past, setPast] = useState<ShoppingList[][]>([]);
  const [future, setFuture] = useState<ShoppingList[][]>([]);

  // Derived active list
  const activeList = useMemo(() => 
    lists.find(l => l.id === activeListId) || lists[0], 
    [lists, activeListId]
  );

  // Persistence
  useEffect(() => {
    const savedLists = localStorage.getItem('grocai_lists_v2');
    const savedActiveId = localStorage.getItem('grocai_active_list_id');

    if (savedLists) {
      try {
        const parsed = JSON.parse(savedLists);
        setLists(parsed);
        if (savedActiveId && parsed.find((l: ShoppingList) => l.id === savedActiveId)) {
          setActiveListId(savedActiveId);
        } else if (parsed.length > 0) {
          setActiveListId(parsed[0].id);
        }
      } catch (e) {
        console.error("Failed to load lists", e);
      }
    } else {
      // Default initial list
      const defaultId = crypto.randomUUID();
      const defaultList: ShoppingList = {
        id: defaultId,
        name: 'Weekly Groceries',
        items: [],
        createdAt: Date.now()
      };
      setLists([defaultList]);
      setActiveListId(defaultId);
    }
  }, []);

  useEffect(() => {
    if (lists.length > 0) {
      localStorage.setItem('grocai_lists_v2', JSON.stringify(lists));
      localStorage.setItem('grocai_active_list_id', activeListId);
    }
  }, [lists, activeListId]);

  // Helper to update state with history
  const updateListsWithHistory = useCallback((newLists: ShoppingList[] | ((prev: ShoppingList[]) => ShoppingList[])) => {
    setLists(prev => {
      const nextState = typeof newLists === 'function' ? newLists(prev) : newLists;
      if (JSON.stringify(prev) !== JSON.stringify(nextState)) {
        setPast(p => [...p, prev]);
        setFuture([]); 
      }
      return nextState;
    });
  }, []);

  const undo = useCallback(() => {
    if (past.length === 0) return;
    const previous = past[past.length - 1];
    const newPast = past.slice(0, past.length - 1);

    setFuture(prevFuture => [lists, ...prevFuture]);
    setPast(newPast);
    setLists(previous);
  }, [past, lists]);

  const redo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    const newFuture = future.slice(1);

    setPast(prevPast => [...prevPast, lists]);
    setFuture(newFuture);
    setLists(next);
  }, [future, lists]);

  // Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        if (e.shiftKey) redo(); else undo();
      } else if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
        redo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  const processSingleLine = async (line: string): Promise<GroceryItem | null> => {
    const trimmedLine = line.trim();
    if (!trimmedLine) return null;

    let finalName = trimmedLine;
    let barcode = "";
    let brand = "";
    let imageUrl = "";

    const isBarcode = /^\d{8,14}$/.test(trimmedLine);

    if (isBarcode) {
      barcode = trimmedLine;
      const upcResult = await lookupBarcode(trimmedLine);
      if (upcResult?.product) {
        finalName = upcResult.product.name;
        brand = upcResult.product.brand || "";
        imageUrl = upcResult.product.imageUrl || "";
      } else {
        const context = await searchItemContext(trimmedLine);
        finalName = context || `Product ${trimmedLine}`;
      }
    }

    const categoryData = await categorizeItem(finalName);

    return {
      id: crypto.randomUUID(),
      name: finalName,
      category: categoryData.category,
      emoji: categoryData.emoji,
      color: categoryData.color,
      barcode: barcode || undefined,
      brand: brand || undefined,
      imageUrl: imageUrl || undefined,
      addedAt: Date.now(),
      completed: false
    };
  };

  const handleAddItem = async (query: string) => {
    if (!activeListId) return;
    setIsLoading(true);
    try {
      const lines = query.split('\n').filter(l => l.trim().length > 0);
      const newItemsPromises = lines.map(line => processSingleLine(line));
      const results = await Promise.all(newItemsPromises);
      const validNewItems = results.filter((item): item is GroceryItem => item !== null);

      if (validNewItems.length > 0) {
        updateListsWithHistory(prev => prev.map(l => 
          l.id === activeListId 
            ? { ...l, items: [...validNewItems, ...l.items] } 
            : l
        ));
      }
    } catch (error) {
      console.error("Add item(s) failed", error);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleItem = (itemId: string) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.map(i => i.id === itemId ? { ...i, completed: !i.completed } : i) } 
        : l
    ));
  };

  const updateItem = (itemId: string, updates: Partial<GroceryItem>) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.map(i => i.id === itemId ? { ...i, ...updates } : i) } 
        : l
    ));
  };

  const deleteItem = (itemId: string) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.filter(i => i.id !== itemId) } 
        : l
    ));
  };

  const clearCompleted = () => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.filter(i => !i.completed) } 
        : l
    ));
  };

  // List Management Actions
  const handleCreateList = (name: string) => {
    const newList: ShoppingList = {
      id: crypto.randomUUID(),
      name,
      items: [],
      createdAt: Date.now()
    };
    updateListsWithHistory(prev => [...prev, newList]);
    setActiveListId(newList.id);
  };

  const handleDeleteList = (id: string) => {
    if (lists.length <= 1) return; // Keep at least one list
    updateListsWithHistory(prev => {
      const filtered = prev.filter(l => l.id !== id);
      if (activeListId === id) setActiveListId(filtered[0].id);
      return filtered;
    });
  };

  const handleRenameList = (id: string, newName: string) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === id ? { ...l, name: newName } : l
    ));
  };

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 selection:bg-purple-500/30 flex">
      <Sidebar 
        lists={lists} 
        activeListId={activeListId} 
        onSelectList={setActiveListId}
        onCreateList={handleCreateList}
        onDeleteList={handleDeleteList}
        onRenameList={handleRenameList}
      />

      <div className="flex-1 lg:ml-72 flex flex-col">
        {/* Background decor */}
        <div className="fixed top-0 left-1/2 -translate-x-1/2 w-full max-w-6xl h-[500px] bg-purple-500/5 blur-[120px] rounded-full pointer-events-none -z-10" />

        <nav className="sticky top-0 z-40 glass border-b border-zinc-800/50">
          <div className="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-9 h-9 bg-zinc-100 rounded-xl flex items-center justify-center">
                <ShoppingCart className="w-5 h-5 text-zinc-950" />
              </div>
              <div className="flex flex-col">
                <span className="text-sm font-bold tracking-tight leading-none">Groc<span className="text-purple-500">AI</span></span>
                <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest mt-0.5 truncate max-w-[120px]">
                  {activeList?.name || 'Loading...'}
                </span>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className="flex items-center bg-zinc-900/50 border border-zinc-800 rounded-lg p-0.5">
                <button 
                  onClick={undo}
                  disabled={past.length === 0}
                  className="p-1.5 text-zinc-500 hover:text-white disabled:opacity-20 transition-colors"
                  title="Undo (Ctrl+Z)"
                >
                  <Undo2 className="w-4 h-4" />
                </button>
                <button 
                  onClick={redo}
                  disabled={future.length === 0}
                  className="p-1.5 text-zinc-500 hover:text-white disabled:opacity-20 transition-colors"
                  title="Redo (Ctrl+Y)"
                >
                  <Redo2 className="w-4 h-4" />
                </button>
              </div>
              <div className="h-4 w-px bg-zinc-800" />
              <a href="#" className="p-2 text-zinc-400 hover:text-white transition-colors">
                <Github className="w-5 h-5" />
              </a>
            </div>
          </div>
        </nav>

        <main className="max-w-4xl mx-auto w-full px-6 py-12 md:py-16">
          {/* Header */}
          <div className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div className="space-y-2">
              <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-purple-500/10 border border-purple-500/20 text-purple-400 text-[10px] font-bold uppercase tracking-wider">
                <Sparkles className="w-3 h-3" />
                <span>Editing {activeList?.name}</span>
              </div>
              <h1 className="text-3xl md:text-5xl font-extrabold tracking-tighter text-white">
                {activeList?.name}
              </h1>
            </div>

            <div className="flex items-center gap-4 text-sm text-zinc-500">
              <div className="flex items-center gap-1.5 bg-zinc-900/50 px-3 py-1.5 rounded-full border border-zinc-800">
                <Terminal className="w-3.5 h-3.5" />
                <span>{activeList?.items.length || 0} Items</span>
              </div>
              <div className="flex items-center gap-1.5 bg-zinc-900/50 px-3 py-1.5 rounded-full border border-zinc-800">
                <Zap className="w-3.5 h-3.5" />
                <span>{activeList?.items.filter(i => i.completed).length || 0} Done</span>
              </div>
            </div>
          </div>

          {/* Input Area */}
          <div className="sticky top-20 z-30 pb-10">
            <div className="absolute inset-x-0 -top-4 h-24 bg-gradient-to-b from-[#09090b] via-[#09090b] to-transparent pointer-events-none -z-10" />
            <SearchInput onAdd={handleAddItem} isLoading={isLoading} />
          </div>

          {/* Action Row */}
          <div className="flex items-center justify-between mt-8 mb-6 border-b border-zinc-800/50 pb-4">
             <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-zinc-600">
                <Layers className="w-3 h-3" />
                <span>Category Sorted View</span>
             </div>
             <button 
                onClick={clearCompleted}
                disabled={!activeList?.items.some(i => i.completed)}
                className="text-xs font-bold text-zinc-500 hover:text-white transition-colors disabled:opacity-0 uppercase tracking-wider"
              >
                Clear Completed
              </button>
          </div>

          {/* Items List */}
          <GroceryList 
            items={activeList?.items || []} 
            onToggle={toggleItem} 
            onDelete={deleteItem} 
            onUpdate={updateItem}
          />
        </main>

        <footer className="mt-auto border-t border-zinc-800/50 py-8 px-6 bg-zinc-950/20">
          <div className="max-w-5xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6 text-zinc-500">
            <div className="flex items-center gap-2">
              <ShoppingCart className="w-4 h-4 opacity-50" />
              <span className="text-xs">© 2024 GrocAI • AI Intelligence Integrated</span>
            </div>
            <div className="flex gap-6 text-[10px] font-bold uppercase tracking-widest">
              <a href="#" className="hover:text-white transition-colors">Documentation</a>
              <a href="#" className="hover:text-white transition-colors">Privacy</a>
              <a href="#" className="hover:text-white transition-colors">Support</a>
            </div>
          </div>
        </footer>
      </div>
    </div>
  );
};

export default App;

