  );

  const grandTotal = useMemo(() => {
    return activeList?.items.reduce((sum, item) => sum + (item.price || 0) * item.quantity, 0) || 0;
  }, [activeList]);

  // Request location on mount
  useEffect(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setLocationStr(`${pos.coords.latitude}, ${pos.coords.longitude}`);
      }, (err) => console.log("Geolocation denied", err));
    }
  }, []);

  // Fetch insights when the list changes
  useEffect(() => {
    const itemsToAnalyze = activeList?.items.map(i => i.name).sort().join(',') || '';
    if (itemsToAnalyze && itemsToAnalyze !== lastAnalyzedItemsRef.current) {
      const fetchInsights = async () => {
        setIsHintsLoading(true);
        const res = await getShoppingInsights(activeList?.items.map(i => i.name) || [], locationStr);
        if (res?.hints) setHints(res.hints);
        setIsHintsLoading(false);
        lastAnalyzedItemsRef.current = itemsToAnalyze;
      };

      const timer = setTimeout(fetchInsights, 2000); // Debounce
      return () => clearTimeout(timer);
    } else if (!itemsToAnalyze) {
      setHints([]);
    }
  }, [activeList?.items, locationStr]);

  useEffect(() => {
    const savedLists = localStorage.getItem('grocai_lists_v3');
    const savedActiveId = localStorage.getItem('grocai_active_list_id_v3');

    if (savedLists) {
      try {
        const parsed = JSON.parse(savedLists);
        setLists(parsed);
        if (savedActiveId && parsed.find((l: ShoppingList) => l.id === savedActiveId)) {
          setActiveListId(savedActiveId);
        } else if (parsed.length > 0) {
          setActiveListId(parsed[0].id);
        }
      } catch (e) {
        console.error("Failed to load lists", e);
      }
    } else {
      const defaultId = crypto.randomUUID();
      const defaultList: ShoppingList = {
        id: defaultId,
        name: 'My Groceries',
        items: [],
        createdAt: Date.now()
      };
      setLists([defaultList]);
      setActiveListId(defaultId);
    }
  }, []);

  useEffect(() => {
    if (lists.length > 0) {
      localStorage.setItem('grocai_lists_v3', JSON.stringify(lists));
      localStorage.setItem('grocai_active_list_id_v3', activeListId);
    }
  }, [lists, activeListId]);

  const updateListsWithHistory = useCallback((newLists: ShoppingList[] | ((prev: ShoppingList[]) => ShoppingList[])) => {
    setLists(prev => {
      const nextState = typeof newLists === 'function' ? newLists(prev) : newLists;
      if (JSON.stringify(prev) !== JSON.stringify(nextState)) {
        setPast(p => [...p, prev].slice(-20));
        setFuture([]); 
      }
      return nextState;
    });
  }, []);

  const undo = useCallback(() => {
    if (past.length === 0) return;
    const previous = past[past.length - 1];
    setFuture(f => [lists, ...f]);
    setPast(p => p.slice(0, -1));
    setLists(previous);
  }, [past, lists]);

  const redo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    setPast(p => [...p, lists]);
    setFuture(f => f.slice(1));
    setLists(next);
  }, [future, lists]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        if (e.shiftKey) redo(); else undo();
      } else if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
        redo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  const processSingleItem = async (query: string): Promise<GroceryItem | null> => {
    const trimmed = query.trim();
    if (!trimmed) return null;

    let name = trimmed;
    let barcode = "";
    let brand = "";
    let imageUrl = "";

    const isBarcode = /^\d{8,14}$/.test(trimmed);

    if (isBarcode) {
      barcode = trimmed;
      const upcResult = await lookupBarcode(trimmed);
      if (upcResult?.product) {
        name = upcResult.product.name;
        brand = upcResult.product.brand || "";
        imageUrl = upcResult.product.imageUrl || "";
      } else {
        const context = await searchItemContext(trimmed);
        name = context || `Product ${trimmed}`;
      }
    }

    const categoryData = await categorizeItem(name);

    return {
      id: crypto.randomUUID(),
      name,
      category: categoryData.category,
      emoji: categoryData.emoji,
      color: categoryData.color,
      quantity: 1,
      barcode: barcode || undefined,
      brand: brand || undefined,
      imageUrl: imageUrl || undefined,
      addedAt: Date.now(),
      completed: false
    };
  };

  const handleAddItem = async (query: string) => {
    if (!activeListId) return;
    setIsLoading(true);
    try {
      const newItem = await processSingleItem(query);
      if (newItem) {
        updateListsWithHistory(prev => prev.map(l => 
          l.id === activeListId ? { ...l, items: [newItem, ...l.items] } : l
        ));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleItem = (itemId: string) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.map(i => i.id === itemId ? { ...i, completed: !i.completed } : i) } 
        : l
    ));
  };

  const updateItem = (itemId: string, updates: Partial<GroceryItem>) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.map(i => i.id === itemId ? { ...i, ...updates } : i) } 
        : l
    ));
  };

  const deleteItem = (itemId: string) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.filter(i => i.id !== itemId) } 
        : l
    ));
  };

  const clearCompleted = () => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.filter(i => !i.completed) } 
        : l
    ));
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
    }).format(val);
  };

  const handleCreateNewList = () => {
    const id = crypto.randomUUID();
    const newList: ShoppingList = {
      id,
      name: 'New List',
      items: [],
      createdAt: Date.now()
    };
    updateListsWithHistory(prev => [...prev, newList]);
    setActiveListId(id);
    setIsMenuOpen(false);
    setEditingListNameId(id);
    setTempListName('New List');
  };

  const handleDeleteList = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (lists.length <= 1) return;
    updateListsWithHistory(prev => {
      const filtered = prev.filter(l => l.id !== id);
      if (activeListId === id) setActiveListId(filtered[0].id);
      return filtered;
    });
  };

  const startRename = (list: ShoppingList, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingListNameId(list.id);
    setTempListName(list.name);
  };

  const saveRename = () => {
    if (editingListNameId && tempListName.trim()) {
      updateListsWithHistory(prev => prev.map(l => 
        l.id === editingListNameId ? { ...l, name: tempListName.trim() } : l
      ));
    }
    setEditingListNameId(null);
  };

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 selection:bg-purple-500/30 flex flex-col">
      <div className="fixed top-0 left-1/2 -translate-x-1/2 w-full max-w-6xl h-[600px] bg-purple-500/5 blur-[120px] rounded-full pointer-events-none -z-10" />

      {/* Modern Header */}
      <nav className="sticky top-0 z-50 border-b border-zinc-800/50 glass">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-lg shadow-white/5">
                <ShoppingCart className="w-5 h-5 text-zinc-950" />
              </div>
              <span className="text-lg font-bold tracking-tight hidden sm:inline">Groc<span className="text-purple-500">AI</span></span>
            </div>

            <div className="h-6 w-px bg-zinc-800" />

            <div className="relative">
              <button 
                onClick={() => setIsMenuOpen(!isMenuOpen)}
                className="flex items-center gap-2 group hover:bg-zinc-800/50 px-3 py-1.5 rounded-lg transition-colors border border-transparent hover:border-zinc-700/50"
              >
                <div className="flex flex-col items-start leading-tight">
                  <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Active List</span>
                  <span className="text-sm font-semibold text-zinc-200 group-hover:text-white transition-colors max-w-[120px] truncate">
                    {activeList?.name}
                  </span>
                </div>
                <ChevronDown className={`w-4 h-4 text-zinc-500 transition-transform duration-300 ${isMenuOpen ? 'rotate-180' : ''}`} />
              </button>

              {isMenuOpen && (
                <>
                  <div className="fixed inset-0 z-40" onClick={() => setIsMenuOpen(false)} />
                  <div className="absolute top-full left-0 mt-2 w-64 bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl z-50 p-2 animate-in fade-in zoom-in-95 duration-200">
                    <div className="space-y-1 max-h-[300px] overflow-y-auto custom-scrollbar pr-1">
                      {lists.map(list => (
                        <div 
                          key={list.id}
                          onClick={() => { setActiveListId(list.id); setIsMenuOpen(false); }}
                          className={`group flex items-center justify-between p-3 rounded-xl cursor-pointer transition-all ${
                            activeListId === list.id ? 'bg-purple-500/10 text-purple-400 ring-1 ring-purple-500/20' : 'hover:bg-zinc-800 text-zinc-400 hover:text-white'
                          }`}
                        >
                          <div className="flex items-center gap-3 min-w-0">
                            <div className={`w-1.5 h-1.5 rounded-full ${activeListId === list.id ? 'bg-purple-500' : 'bg-zinc-700 opacity-0 group-hover:opacity-100'}`} />
                            {editingListNameId === list.id ? (
                              <input 
                                autoFocus
                                value={tempListName}
                                onClick={e => e.stopPropagation()}
                                onChange={e => setTempListName(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && saveRename()}
                                className="bg-zinc-950 border border-zinc-700 rounded px-2 py-0.5 text-xs text-white outline-none w-32"
                              />
                            ) : (
                              <span className="text-xs font-bold truncate">{list.name}</span>
                            )}
                          </div>
                          <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
                            {editingListNameId === list.id ? (
                              <button onClick={(e) => { e.stopPropagation(); saveRename(); }} className="p-1 hover:text-green-400 transition-colors"><Check className="w-3.5 h-3.5" /></button>
                            ) : (
                              <button onClick={(e) => startRename(list, e)} className="p-1 hover:text-purple-400 transition-colors"><Edit3 className="w-3.5 h-3.5" /></button>
                            )}
                            <button onClick={(e) => handleDeleteList(list.id, e)} className="p-1 hover:text-red-400 transition-colors"><Trash2 className="w-3.5 h-3.5" /></button>
                          </div>
                        </div>
                      ))}
                    </div>
                    <div className="mt-2 pt-2 border-t border-zinc-800">
                      <button 
                        onClick={handleCreateNewList}
                        className="w-full flex items-center gap-2 p-2.5 rounded-xl text-zinc-500 hover:text-white hover:bg-zinc-800 transition-all group"
                      >
                        <ListPlus className="w-4 h-4 group-hover:scale-110 transition-transform" />
                        <span className="text-xs font-bold uppercase tracking-wider">New Shopping List</span>
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="flex items-center bg-zinc-900/50 border border-zinc-800 rounded-xl p-0.5">
              <button 
                onClick={undo}
                disabled={past.length === 0}
                className="p-2 text-zinc-500 hover:text-white disabled:opacity-20 transition-all hover:bg-zinc-800 rounded-lg"
                title="Undo (Ctrl+Z)"
              >
                <Undo2 className="w-4 h-4" />
              </button>
              <button 
                onClick={redo}
                disabled={future.length === 0}
                className="p-2 text-zinc-500 hover:text-white disabled:opacity-20 transition-all hover:bg-zinc-800 rounded-lg"
                title="Redo (Ctrl+Y)"
              >
                <Redo2 className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </nav>

      {/* Smart AI Assistant Banner */}
      {(hints.length > 0 || isHintsLoading) && (
        <div className="max-w-4xl mx-auto w-full px-6 pt-8 animate-in slide-in-from-top-4 duration-500">
          <div className="relative overflow-hidden group">
            <div className="absolute inset-0 bg-gradient-to-r from-purple-500/10 via-blue-500/10 to-purple-500/10 group-hover:scale-105 transition-transform duration-1000" />
            <div className="relative p-6 bg-zinc-900/80 border border-purple-500/20 rounded-3xl backdrop-blur-md shadow-2xl shadow-purple-500/5">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-2xl bg-purple-500/20 flex items-center justify-center text-purple-400">
                    <Sparkles className="w-5 h-5 animate-pulse" />
                  </div>
                  <div>
                    <h4 className="text-sm font-extrabold text-white tracking-tight uppercase">Smart AI Assistant</h4>
                    <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-[0.2em]">Real-time Shopping Insights</p>
                  </div>
                </div>
                <button 
                  onClick={() => setHints([])}
                  className="p-2 text-zinc-600 hover:text-white transition-colors"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="mt-6 space-y-3">
                {isHintsLoading ? (
                  <div className="flex items-center gap-3 px-4 py-3 bg-zinc-950/40 rounded-2xl border border-zinc-800">
                    <Loader2 className="w-4 h-4 text-purple-500 animate-spin" />
                    <span className="text-xs font-bold text-zinc-500 uppercase tracking-widest">Searching local store prices...</span>
                  </div>
                ) : (
                  hints.map((hint, idx) => (
                    <div key={idx} className="flex items-start gap-3 px-4 py-3 bg-zinc-950/40 rounded-2xl border border-zinc-800/50 hover:border-purple-500/30 transition-all">
                      <Lightbulb className="w-4 h-4 text-yellow-500 mt-0.5" />
                      <p className="text-xs font-medium text-zinc-300 leading-relaxed">{hint}</p>
                    </div>
                  ))
                )}

                {locationStr && !isHintsLoading && (
                  <div className="flex items-center gap-2 px-3 py-1.5 mt-2 rounded-lg bg-zinc-800/30 w-fit">
                    <Navigation className="w-3 h-3 text-zinc-600" />
                    <span className="text-[9px] font-bold text-zinc-600 uppercase tracking-widest">Pricing optimized for local area</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-4xl mx-auto w-full px-6 py-12 md:py-16">
        {/* Active List Heading */}
        <div className="mb-12 flex flex-col sm:flex-row sm:items-end justify-between gap-6">
          <div className="space-y-3">
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-purple-500/10 border border-purple-500/20 text-purple-400 text-[10px] font-bold uppercase tracking-widest">
              <Zap className="w-3 h-3" />
              <span>Smart List Management</span>
            </div>
            <h1 className="text-4xl md:text-6xl font-extrabold tracking-tighter text-white">
              {activeList?.name}
            </h1>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-1.5 px-4 py-2 rounded-2xl bg-zinc-900/50 border border-zinc-800 shadow-xl shadow-black/20">
              <Terminal className="w-4 h-4 text-zinc-500" />
              <span className="text-xs font-bold text-zinc-400 uppercase tracking-widest">
                {activeList?.items.length || 0} Items
              </span>
            </div>
            <div className="flex items-center gap-1.5 px-4 py-2 rounded-2xl bg-zinc-900/50 border border-zinc-800 shadow-xl shadow-black/20">
              <Check className="w-4 h-4 text-purple-500" />
              <span className="text-xs font-bold text-zinc-400 uppercase tracking-widest">
                {activeList?.items.filter(i => i.completed).length || 0} Done
              </span>
            </div>
            {grandTotal > 0 && (
               <div className="flex items-center gap-1.5 px-4 py-2 rounded-2xl bg-purple-500/10 border border-purple-500/30 shadow-xl shadow-purple-500/5">
                 <DollarSign className="w-4 h-4 text-purple-400" />
                 <span className="text-xs font-bold text-purple-300 uppercase tracking-widest">
                   Total: {formatCurrency(grandTotal)}
                 </span>
               </div>
            )}
          </div>
        </div>

        {/* Improved Search Area */}
        <div className="sticky top-20 z-40 pb-12 pointer-events-none">
          <div className="absolute inset-x-0 -top-8 h-32 bg-gradient-to-b from-[#09090b] via-[#09090b] to-transparent -z-10" />
          <div className="pointer-events-auto">
            <SearchInput onAdd={handleAddItem} isLoading={isLoading} />
          </div>
        </div>

        {/* Controls Bar */}
        <div className="flex items-center justify-between mb-8 border-b border-zinc-800/80 pb-5">
          <div className="flex gap-4">
            <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-zinc-600 flex items-center gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-green-500/50 animate-pulse" />
              Categorized View
            </div>
          </div>
          <button 
            onClick={clearCompleted}
            disabled={!activeList?.items.some(i => i.completed)}
            className="text-[10px] font-extrabold uppercase tracking-[0.2em] text-zinc-500 hover:text-white transition-all disabled:opacity-0 active:scale-95"
          >
            Purge Completed
          </button>
        </div>

        {/* List Content */}
        <GroceryList 
          items={activeList?.items || []} 
          onToggle={toggleItem} 
          onDelete={deleteItem} 
          onUpdate={updateItem}
        />
      </main>

      {/* Modern Footer */}
      <footer className="mt-auto border-t border-zinc-800/50 py-12 px-6 bg-zinc-950/20">
        <div className="max-w-4xl mx-auto flex flex-col md:flex-row justify-between items-center gap-8 text-zinc-600">
          <div className="flex items-center gap-2">
            <ShoppingCart className="w-4 h-4 opacity-30" />
            <span className="text-[10px] font-bold uppercase tracking-widest">GrocAI • Experimental V2</span>
          </div>
          <div className="flex gap-10 text-[10px] font-extrabold uppercase tracking-[0.25em]">
            <a href="#" className="hover:text-purple-400 transition-colors">Vercel</a>
            <a href="#" className="hover:text-purple-400 transition-colors">GitHub</a>
            <a href="#" className="hover:text-purple-400 transition-colors">Supabase</a>
          </div>
        </div>
      </footer>
    </div>
  );
};

