import { GoogleGenAI, Type } from "@google/genai";
import { INITIAL_PROMPT, CATEGORY_STYLES } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function categorizeAndPriceItem(itemName: string) {
  try {
    const prompt = `Kategoriser og find en omtrentlig butikspris for: "${itemName}". 
    Brug Google Søgning til at finde virkelige omtrentlige priser i danske butikker (i DKK). 
    Hvis det er et specifikt mærke eller stregkode, vær præcis. 
    Hvis det er en generel vare som "bananer", find gennemsnitsprisen per kg eller enhed.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: INITIAL_PROMPT + " Inkluder desuden et 'approxPrice' felt (tal) hvis du kan finde et pålideligt estimat via søgning. Hvis ikke, udelad det.",
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: { 
              type: Type.STRING,
              description: "Det præcise kategorinavn fra den tilladte liste."
            },
            emoji: { 
              type: Type.STRING, 
              description: "En enkelt emoji der repræsenterer varen." 
            },
            color: { 
              type: Type.STRING, 
              description: "Hex-farvekoden der svarer præcis til den valgte kategori." 
            },
            approxPrice: {
              type: Type.NUMBER,
              description: "Omtrentlig pris fundet via søgning."
            }
          },
          required: ["category", "emoji", "color"]
        }
      }
    });

    const result = JSON.parse(response.text);

    if (!CATEGORY_STYLES[result.category]) {
      result.category = "Andet";
      result.color = CATEGORY_STYLES["Andet"].color;
    }

    return result;
  } catch (error) {
    console.error("Gemini categorization and pricing failed:", error);
    return {
      category: "Andet",
      emoji: "🛒",
      color: "#71717a"
    };
  }
}

export async function getShoppingInsights(items: string[], location?: string) {
  if (items.length === 0) return null;

  try {
    const prompt = `Analyser denne indkøbsliste: [${items.join(", ")}]. 
    Nuværende brugerplacering: ${location || "Danmark"}.

    Opgaver:
    1. Undersøg gennemsnitspriser for disse varer fra de 3 nærmeste store danske detailhandlere (f.eks. Netto, Rema 1000, Føtex, Salling) ved hjælp af Google Søgning.
    2. Giv 1-2 "Smarte Tips" til at spare penge eller optimere indkøb (f.eks. "Køb af korn i løs vægt i butik X sparer 25 kr."). Skriv tips på dansk.
    3. Hvis der ikke er nogen betydelige besparelser eller tips, returner et tomt svar.

    Returner strengt gyldig JSON med disse nøgler: 
    - "hints": string[] (max 2)
    - "estimatedTotal": number (valgfri)`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            hints: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            estimatedTotal: { type: Type.NUMBER }
          },
          required: ["hints"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Failed to fetch insights:", error);
    return null;
  }
}

export async function searchItemContext(query: string) {
  try {
    const response = await ai.models.generateContent({
