import React, { useState } from 'react';
import { GroceryItem } from '../types';
import { CATEGORY_STYLES } from '../constants';
import { 
  CheckCircle2, 
  Circle, 
  Trash2, 
  GripVertical, 
  ShoppingBag, 
  Pencil, 
  Check, 
  X,
  Plus,
  Minus,
  DollarSign,
  HelpCircle
} from 'lucide-react';

interface GroceryListProps {
  items: GroceryItem[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<GroceryItem>) => void;
}

const GroceryList: React.FC<GroceryListProps> = ({ items, onToggle, onDelete, onUpdate }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editCategory, setEditCategory] = useState('');
  const [editPrice, setEditPrice] = useState<string>('');

  const groups: Record<string, GroceryItem[]> = items.reduce((acc, item) => {
    if (!acc[item.category]) acc[item.category] = [];
    acc[item.category].push(item);
    return acc;
  }, {} as Record<string, GroceryItem[]>);

  const sortedCategories = Object.keys(groups).sort();

  const handleQuantity = (item: GroceryItem, delta: number) => {
    const nextQty = Math.max(1, item.quantity + delta);
    onUpdate(item.id, { quantity: nextQty });
  };

  const startEditing = (item: GroceryItem) => {
    if (item.completed) return;
    setEditingId(item.id);
    setEditName(item.name);
    setEditCategory(item.category);
    setEditPrice(item.price?.toString() || '');
  };

  const saveEditing = () => {
    if (editingId) {
      const rawPrice = parseFloat(editPrice);
      const parsedPrice = isNaN(rawPrice) ? undefined : Math.max(0, rawPrice);

      onUpdate(editingId, { 
        name: editName, 
        category: editCategory,
        color: CATEGORY_STYLES[editCategory]?.color || CATEGORY_STYLES['Andet'].color,
        price: parsedPrice
      });
      setEditingId(null);
    }
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('da-DK', {
      style: 'currency',
      currency: 'DKK',
    }).format(val);
  };

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-zinc-500">
        <div className="w-16 h-16 bg-zinc-900 rounded-full flex items-center justify-center mb-4 ring-1 ring-zinc-800">
          <ShoppingBag className="w-8 h-8 opacity-20" />
        </div>
        <p className="text-lg font-medium">Din liste er tom</p>
        <p className="text-sm">Tilføj varer manuelt eller skift til Stregkode-tilstand</p>
      </div>
    );
  }

  return (
    <div className="space-y-12 mt-12">
      {sortedCategories.map((cat) => {
        const categoryItems = groups[cat];

        return (
          <div key={cat} className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center justify-between mb-6 group/header">
              <div className="flex items-center gap-4">
                <div 
                  className="w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-black/40"
                  style={{ backgroundColor: CATEGORY_STYLES[cat]?.color || '#71717a' }}
                >
                  {CATEGORY_STYLES[cat]?.icon || CATEGORY_STYLES['Andet'].icon}
                </div>
                <div>
                  <h3 className="font-bold text-xl text-zinc-100 tracking-tight leading-none">{cat}</h3>
                  <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest mt-1.5 flex items-center gap-1.5">
                    {categoryItems.length} {categoryItems.length === 1 ? 'vare' : 'varer'}
                    <span className="w-1 h-1 rounded-full bg-zinc-800" />
                    Kategori
                  </p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 gap-3">
              {categoryItems.map((item) => {
                const isEditing = editingId === item.id;
                const itemTotal = (item.price || 0) * item.quantity;

                return (
                  <div 
                    key={item.id}
                    className={`group flex items-center gap-4 p-4 bg-zinc-900/40 hover:bg-zinc-800/40 rounded-2xl border border-zinc-800/50 transition-all ${item.completed ? 'opacity-40 grayscale-[0.5]' : ''} ${isEditing ? 'ring-2 ring-purple-500/50 bg-zinc-800/60' : ''}`}
                  >
                    {!isEditing && (
                      <button 
                        onClick={() => onToggle(item.id)}
                        className="shrink-0 text-zinc-600 hover:text-purple-500 transition-colors"
                      >
                        {item.completed ? (
                          <CheckCircle2 className="w-6 h-6 text-purple-500" />
                        ) : (
                          <Circle className="w-6 h-6" />
                        )}
                      </button>
                    )}

                    <div className="w-12 h-12 shrink-0 rounded-xl bg-zinc-800/50 flex items-center justify-center overflow-hidden border border-zinc-700/30">
                      {item.imageUrl ? (
                        <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                      ) : (
                        <span className="text-2xl">{item.emoji}</span>
                      )}
                    </div>

                    <div className="flex-1 min-w-0">
                      {isEditing ? (
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                          <div className="space-y-2">
                            <input
                              autoFocus
                              value={editName}
                              onChange={(e) => setEditName(e.target.value)}
                              className="w-full bg-zinc-950 border border-zinc-700 rounded-lg px-3 py-1.5 text-sm text-white focus:ring-1 focus:ring-purple-500 outline-none"
                              placeholder="Varenavn"
                            />
                            <select
                              value={editCategory}
                              onChange={(e) => setEditCategory(e.target.value)}
                              className="w-full bg-zinc-950 border border-zinc-700 rounded-lg px-2 py-1.5 text-[10px] text-zinc-300 font-bold uppercase tracking-wider outline-none"
                            >
                              {Object.keys(CATEGORY_STYLES).map(c => (
                                <option key={c} value={c}>{c}</option>
                              ))}
                            </select>
                          </div>
                          <div className="relative">
                             <div className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500 text-xs font-bold">
                               kr.
                             </div>
                             <input
                               type="number"
                               min="0"
                               step="0.01"
                               value={editPrice}
                               onChange={(e) => setEditPrice(e.target.value)}
                               className="w-full bg-zinc-950 border border-zinc-700 rounded-lg pl-10 pr-3 py-1.5 text-sm text-white focus:ring-1 focus:ring-purple-500 outline-none h-full"
                               placeholder="0,00"
                             />
                          </div>
                        </div>
                      ) : (
                        <div className="flex flex-col">
                          <p className={`font-semibold text-zinc-100 ${item.completed ? 'line-through text-zinc-600' : ''}`}>
                            <span className="text-purple-400/80 mr-1.5">{item.quantity}x</span>
                            {item.name}
                          </p>
                          <div className="flex items-center gap-2 mt-0.5">
                            {item.price !== undefined ? (
                              <span className="text-[10px] font-bold text-zinc-400">
                                {formatCurrency(item.price)} pr. stk
                              </span>
                            ) : (
                              <div className="flex items-center gap-1">
                                <HelpCircle className="w-3 h-3 text-zinc-600" />
                                <span className="text-[9px] font-bold text-zinc-600 uppercase tracking-widest">Pris Ukendt</span>
                              </div>
                            )}
                            {item.brand && (
                              <span className="text-[9px] text-zinc-500 font-bold uppercase tracking-widest bg-zinc-800/80 px-1.5 py-0.5 rounded-md border border-zinc-700/50">
                                {item.brand}
                              </span>
                            )}
                          </div>
                        </div>
                      )}
                    </div>

                    {!isEditing && !item.completed && (
                      <div className="flex items-center gap-4">
                        {itemTotal > 0 && (
                          <div className="text-right hidden sm:block">
                            <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">I Alt</p>
                            <p className="text-xs font-bold text-zinc-300">{formatCurrency(itemTotal)}</p>
                          </div>
                        )}
                        <div className="flex items-center bg-zinc-900/80 border border-zinc-800 rounded-lg p-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => handleQuantity(item, -1)}
                            className="p-1.5 text-zinc-500 hover:text-white hover:bg-zinc-800 rounded-md transition-colors"
                          >
                            <Minus className="w-3.5 h-3.5" />
                          </button>
                          <button 
                            onClick={() => handleQuantity(item, 1)}
                            className="p-1.5 text-zinc-500 hover:text-white hover:bg-zinc-800 rounded-md transition-colors"
                          >
                            <Plus className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </div>
                    )}

                    <div className="flex items-center gap-1 shrink-0">
                      {isEditing ? (
                        <div className="flex flex-col gap-1">
                          <button 
                            onClick={saveEditing}
                            className="p-2 text-green-400 hover:bg-green-400/10 rounded-xl transition-all"
                          >
                            <Check className="w-4 h-4" />
                          </button>
                          <button 
                            onClick={() => setEditingId(null)}
                            className="p-2 text-zinc-400 hover:bg-zinc-800 rounded-xl transition-all"
                          >
                            <X className="w-4 h-4" />
                          </button>
                        </div>
                      ) : (
                        <>
                          {!item.completed && (
                            <button 
                              onClick={() => startEditing(item)}
                              className="opacity-0 group-hover:opacity-100 p-2 text-zinc-500 hover:text-purple-400 hover:bg-purple-400/10 rounded-xl transition-all"
                            >
                              <Pencil className="w-4 h-4" />
                            </button>
                          )}
                          <button 
                            onClick={() => onDelete(item.id)}
                            className="opacity-0 group-hover:opacity-100 p-2 text-zinc-500 hover:text-red-400 hover:bg-red-400/10 rounded-xl transition-all"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                          <div className="p-1 text-zinc-800 group-hover:text-zinc-700">
                            <GripVertical className="w-4 h-4" />
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default GroceryList;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { 
  ShoppingCart, 
  Sparkles, 
  Zap, 
  Github, 
  Terminal, 
  Undo2, 
  Redo2, 
  ChevronDown, 
  ListPlus, 
  Trash2, 
  Edit3, 
  Check, 
  DollarSign, 
  Lightbulb,
  X,
  Loader2,
  Navigation,
  Activity,
  ChevronRight,
  Info
} from 'lucide-react';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import { GroceryItem, ShoppingList } from './types';
import { categorizeAndPriceItem, searchItemContext, getShoppingInsights } from './services/geminiService';
import { lookupBarcode } from './services/upcService';

interface ProcessingItem {
  id: string;
  query: string;
  status: 'categorizing' | 'pricing' | 'finalizing';
}

const App: React.FC = () => {
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [activeListId, setActiveListId] = useState<string>('');
  const [processingItems, setProcessingItems] = useState<ProcessingItem[]>([]);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isHintsOpen, setIsHintsOpen] = useState(false);
  const [editingListNameId, setEditingListNameId] = useState<string | null>(null);
  const [tempListName, setTempListName] = useState('');

  const [hints, setHints] = useState<string[]>([]);
  const [isHintsLoading, setIsHintsLoading] = useState(false);
  const [locationStr, setLocationStr] = useState<string | undefined>();
  const lastAnalyzedItemsRef = useRef<string>('');

  const [past, setPast] = useState<ShoppingList[][]>([]);
  const [future, setFuture] = useState<ShoppingList[][]>([]);

  const activeList = useMemo(() => 
    lists.find(l => l.id === activeListId) || lists[0], 
    [lists, activeListId]
  );

  const grandTotal = useMemo(() => {
    return activeList?.items.reduce((sum, item) => sum + (item.price || 0) * item.quantity, 0) || 0;
  }, [activeList]);

  useEffect(() => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setLocationStr(`${pos.coords.latitude}, ${pos.coords.longitude}`);
      }, (err) => console.log("Geolocation denied", err));
    }
  }, []);

  useEffect(() => {
    const itemsToAnalyze = activeList?.items.map(i => i.name).sort().join(',') || '';
    if (itemsToAnalyze && itemsToAnalyze !== lastAnalyzedItemsRef.current) {
      const fetchInsights = async () => {
        setIsHintsLoading(true);
        const res = await getShoppingInsights(activeList?.items.map(i => i.name) || [], locationStr);
        if (res?.hints) setHints(res.hints);
        setIsHintsLoading(false);
        lastAnalyzedItemsRef.current = itemsToAnalyze;
      };

      const timer = setTimeout(fetchInsights, 2000);
      return () => clearTimeout(timer);
    } else if (!itemsToAnalyze) {
      setHints([]);
    }
  }, [activeList?.items, locationStr]);

  useEffect(() => {
    const savedLists = localStorage.getItem('grocai_lists_v3');
    const savedActiveId = localStorage.getItem('grocai_active_list_id_v3');

    if (savedLists) {
      try {
        const parsed = JSON.parse(savedLists);
        setLists(parsed);
        if (savedActiveId && parsed.find((l: ShoppingList) => l.id === savedActiveId)) {
          setActiveListId(savedActiveId);
        } else if (parsed.length > 0) {
          setActiveListId(parsed[0].id);
        }
      } catch (e) {
        console.error("Failed to load lists", e);
      }
    } else {
      const defaultId = crypto.randomUUID();
      const defaultList: ShoppingList = {
        id: defaultId,
        name: 'Min Indkøbsliste',
        items: [],
        createdAt: Date.now()
      };
      setLists([defaultList]);
      setActiveListId(defaultId);
    }
  }, []);

  useEffect(() => {
    if (lists.length > 0) {
      localStorage.setItem('grocai_lists_v3', JSON.stringify(lists));
      localStorage.setItem('grocai_active_list_id_v3', activeListId);
    }
  }, [lists, activeListId]);

  const updateListsWithHistory = useCallback((newLists: ShoppingList[] | ((prev: ShoppingList[]) => ShoppingList[])) => {
    setLists(prev => {
      const nextState = typeof newLists === 'function' ? newLists(prev) : newLists;
      if (JSON.stringify(prev) !== JSON.stringify(nextState)) {
        setPast(p => [...p, prev].slice(-20));
        setFuture([]); 
      }
      return nextState;
    });
  }, []);

  const undo = useCallback(() => {
    if (past.length === 0) return;
    const previous = past[past.length - 1];
    setFuture(f => [lists, ...f]);
    setPast(p => p.slice(0, -1));
    setLists(previous);
  }, [past, lists]);

  const redo = useCallback(() => {
    if (future.length === 0) return;
    const next = future[0];
    setPast(p => [...p, lists]);
    setFuture(f => f.slice(1));
    setLists(next);
  }, [future, lists]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'z') {
        if (e.shiftKey) redo(); else undo();
      } else if ((e.ctrlKey || e.metaKey) && e.key === 'y') {
        redo();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [undo, redo]);

  const processItemAsync = async (pItem: ProcessingItem) => {
    try {
      let name = pItem.query;
      let barcode = "";
      let brand = "";
      let imageUrl = "";
      let approxPrice: number | undefined;

      const isBarcode = /^\d{8,14}$/.test(pItem.query);

      if (isBarcode) {
        barcode = pItem.query;
        const upcResult = await lookupBarcode(pItem.query);
        if (upcResult?.product) {
          name = upcResult.product.name;
          brand = upcResult.product.brand || "";
          imageUrl = upcResult.product.imageUrl || "";
        } else {
          const context = await searchItemContext(pItem.query);
          name = context || `Produkt ${pItem.query}`;
        }
      }

      setProcessingItems(prev => prev.map(item => item.id === pItem.id ? { ...item, status: 'pricing' } : item));

      const aiData = await categorizeAndPriceItem(name);
      approxPrice = aiData.approxPrice;

      const finalItem: GroceryItem = {
        id: crypto.randomUUID(),
        name,
        category: aiData.category,
        emoji: aiData.emoji,
        color: aiData.color,
        quantity: 1,
        price: approxPrice,
        barcode: barcode || undefined,
        brand: brand || undefined,
        imageUrl: imageUrl || undefined,
        addedAt: Date.now(),
        completed: false
      };

      updateListsWithHistory(prev => prev.map(l => 
        l.id === activeListId ? { ...l, items: [finalItem, ...l.items] } : l
      ));
    } catch (e) {
      console.error("Processing failed", e);
    } finally {
      setProcessingItems(prev => prev.filter(item => item.id !== pItem.id));
    }
  };

  const handleAddItem = (query: string) => {
    if (!activeListId) return;
    const newProcessingId = crypto.randomUUID();
    const newProcessingItem: ProcessingItem = {
      id: newProcessingId,
      query,
      status: 'categorizing'
    };

    setProcessingItems(prev => [newProcessingItem, ...prev]);
    processItemAsync(newProcessingItem);
  };

  const toggleItem = (itemId: string) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.map(i => i.id === itemId ? { ...i, completed: !i.completed } : i) } 
        : l
    ));
  };

  const updateItem = (itemId: string, updates: Partial<GroceryItem>) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.map(i => i.id === itemId ? { ...i, ...updates } : i) } 
        : l
    ));
  };

  const deleteItem = (itemId: string) => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.filter(i => i.id !== itemId) } 
        : l
    ));
  };

  const clearCompleted = () => {
    updateListsWithHistory(prev => prev.map(l => 
      l.id === activeListId 
        ? { ...l, items: l.items.filter(i => !i.completed) } 
        : l
    ));
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('da-DK', {
      style: 'currency',
      currency: 'DKK',
    }).format(val);
  };

  const handleCreateNewList = () => {
    const id = crypto.randomUUID();
    const newList: ShoppingList = {
      id,
      name: 'Ny Liste',
      items: [],
      createdAt: Date.now()
    };
    updateListsWithHistory(prev => [...prev, newList]);
    setActiveListId(id);
    setIsMenuOpen(false);
    setEditingListNameId(id);
    setTempListName('Ny Liste');
  };

  const handleDeleteList = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (lists.length <= 1) return;
    updateListsWithHistory(prev => {
      const filtered = prev.filter(l => l.id !== id);
      if (activeListId === id) setActiveListId(filtered[0].id);
      return filtered;
    });
  };

  const startRename = (list: ShoppingList, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingListNameId(list.id);
    setTempListName(list.name);
  };

  const saveRename = () => {
    if (editingListNameId && tempListName.trim()) {
