import { GoogleGenAI, Type } from "@google/genai";
import { INITIAL_PROMPT, CATEGORY_STYLES } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function categorizeAndPriceItem(itemName: string, location?: string) {
  try {
    const prompt = `Kategoriser og find en gennemsnitlig butikspris for: "${itemName}". 
    Brug Google Søgning til at finde priser fra de 3 nærmeste eller mest relevante danske detailbutikker (f.eks. Netto, Rema 1000, Føtex). 
    Beregn gennemsnittet af disse priser i DKK.
    Lokalitet: ${location || "Danmark"}.

    Returner prisen som et tal. Hvis du ikke kan finde en troværdig pris, udelad 'approxPrice' feltet.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: INITIAL_PROMPT + " Vigtigt: Find prisen ved at tjekke mindst 3 kilder via søgning.",
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            category: { 
              type: Type.STRING,
              description: "Det præcise kategorinavn fra den tilladte liste."
            },
            emoji: { 
              type: Type.STRING, 
              description: "En enkelt emoji der repræsenterer varen." 
            },
            color: { 
              type: Type.STRING, 
              description: "Hex-farvekoden der svarer præcis til den valgte kategori." 
            },
            approxPrice: {
              type: Type.NUMBER,
              description: "Gennemsnitspris fra 3 kilder i DKK."
            },
            priceSourceCount: {
              type: Type.INTEGER,
              description: "Antallet af kilder fundet (mål er 3)."
            }
          },
          required: ["category", "emoji", "color"]
        }
      }
    });

    const result = JSON.parse(response.text);

    if (!CATEGORY_STYLES[result.category]) {
      result.category = "Andet";
      result.color = CATEGORY_STYLES["Andet"].color;
    }

    return result;
  } catch (error) {
    console.error("Gemini categorization and pricing failed:", error);
    return {
      category: "Andet",
      emoji: "🛒",
      color: "#71717a"
    };
  }
}

export async function getShoppingInsights(items: string[], otherListsContext: string = "", location?: string) {
  if (items.length === 0 && !otherListsContext) return null;

  try {
    const prompt = `Analyser denne nuværende indkøbsliste: [${items.join(", ")}]. 
    Her er context fra andre/tidligere lister: [${otherListsContext}].
    Nuværende brugerplacering: ${location || "Danmark"}.

    Opgaver:
    1. Undersøg priser og giv 1-2 "Smarte Tips" (hints) til besparelser.
    2. Foreslå 2-3 "Glemte varer" (suggestions).

    Returner strengt gyldig JSON.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            hints: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            suggestions: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            estimatedTotal: { type: Type.NUMBER }
          },
          required: ["hints", "suggestions"]
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Failed to fetch insights:", error);
    return null;
  }
}

export async function searchItemContext(query: string) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Søg efter produktinformation for: "${query}". Returner kun produktets almindelige navn på dansk.`,
      config: {
        tools: [{ googleSearch: {} }]
      }
    });

    return response.text;
  } catch (error) {
    return query;
  }
}

import React, { useState } from 'react';
import { GroceryItem } from '../types';
import { CATEGORY_STYLES } from '../constants';
import { 
  CheckCircle2, 
  Circle, 
  Trash2, 
  GripVertical, 
  ShoppingBag, 
  Pencil, 
  Check, 
  X,
  Plus,
  Minus,
  HelpCircle,
  TrendingDown,
  Store
} from 'lucide-react';

interface GroceryListProps {
  items: GroceryItem[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<GroceryItem>) => void;
}

const GroceryList: React.FC<GroceryListProps> = ({ items, onToggle, onDelete, onUpdate }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editCategory, setEditCategory] = useState('');
  const [editPrice, setEditPrice] = useState<string>('');

  const groups: Record<string, GroceryItem[]> = items.reduce((acc, item) => {
    if (!acc[item.category]) acc[item.category] = [];
    acc[item.category].push(item);
    return acc;
  }, {} as Record<string, GroceryItem[]>);

  const sortedCategories = Object.keys(groups).sort();

  const handleQuantity = (item: GroceryItem, delta: number) => {
    const nextQty = Math.max(1, item.quantity + delta);
    onUpdate(item.id, { quantity: nextQty });
  };

  const startEditing = (item: GroceryItem) => {
    if (item.completed) return;
    setEditingId(item.id);
    setEditName(item.name);
    setEditCategory(item.category);
    setEditPrice(item.price?.toString() || '');
  };

  const saveEditing = () => {
    if (editingId) {
      const rawPrice = parseFloat(editPrice);
      const parsedPrice = isNaN(rawPrice) ? undefined : Math.max(0, rawPrice);

      onUpdate(editingId, { 
        name: editName, 
        category: editCategory,
        color: CATEGORY_STYLES[editCategory]?.color || CATEGORY_STYLES['Andet'].color,
