};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { 
  ShoppingCart, 
  Sparkles, 
  Zap, 
  Terminal, 
  Undo2, 
  Redo2, 
  ChevronDown, 
  ListPlus, 
  Trash2, 
  Edit3, 
  Check, 
  DollarSign, 
  Lightbulb,
  X,
  Loader2,
  Navigation,
  Activity,
  ChevronRight,
  Info,
  PlusCircle,
  LogOut,
  User as UserIcon,
  Cloud
} from 'lucide-react';
import { User } from 'firebase/auth';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import Auth from './components/Auth';
import { GroceryItem, ShoppingList } from './types';
import { categorizeAndPriceItem, searchItemContext, getShoppingInsights } from './services/geminiService';
import { lookupBarcode } from './services/upcService';
import { 
  auth, 
  db, 
  logOut, 
  onAuthChange, 
  collection, 
  doc, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  onSnapshot, 
  query, 
  where, 
  orderBy,
  writeBatch
} from './services/firebaseService';

interface ProcessingItem {
  id: string;
  query: string;
  status: 'categorizing' | 'pricing' | 'finalizing';
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [activeListId, setActiveListId] = useState<string>('');
  const [processingItems, setProcessingItems] = useState<ProcessingItem[]>([]);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isHintsOpen, setIsHintsOpen] = useState(false);
  const [editingListNameId, setEditingListNameId] = useState<string | null>(null);
  const [tempListName, setTempListName] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);

  const [hints, setHints] = useState<string[]>([]);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [isHintsLoading, setIsHintsLoading] = useState(false);
  const [locationStr, setLocationStr] = useState<string | undefined>();
  const lastAnalyzedItemsRef = useRef<string>('');

  // Handle Auth Changes
  useEffect(() => {
    return onAuthChange((user) => {
      setCurrentUser(user);
      setAuthLoading(false);
    });
  }, []);

  // Fetch Location
  useEffect(() => {
    if (currentUser && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setLocationStr(`${pos.coords.latitude}, ${pos.coords.longitude}`);
      }, (err) => console.log("Geolocation denied", err));
    }
  }, [currentUser]);

  // Firestore Real-time Sync
  useEffect(() => {
    if (!currentUser) return;

    setIsSyncing(true);
    const q = query(
      collection(db, `users/${currentUser.uid}/lists`),
      orderBy("createdAt", "desc")
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetchedLists: ShoppingList[] = [];
      snapshot.forEach((doc) => {
        fetchedLists.push({ id: doc.id, ...doc.data() } as ShoppingList);
      });

      setLists(fetchedLists);

      // Set initial active list if none selected
      if (fetchedLists.length > 0 && !activeListId) {
        setActiveListId(fetchedLists[0].id);
      } else if (fetchedLists.length === 0) {
        // Create default list if new user
        handleCreateNewList("Min Første Liste");
      }
      setIsSyncing(false);
    });

    return () => unsubscribe();
  }, [currentUser]);

  const activeList = useMemo(() => 
    lists.find(l => l.id === activeListId) || lists[0], 
    [lists, activeListId]
  );

  const grandTotal = useMemo(() => {
    return activeList?.items.reduce((sum, item) => sum + (item.price || 0) * item.quantity, 0) || 0;
  }, [activeList]);

  // AI Insights Effect
  useEffect(() => {
    const itemsToAnalyze = activeList?.items.map(i => i.name).sort().join(',') || '';
    if (itemsToAnalyze && itemsToAnalyze !== lastAnalyzedItemsRef.current) {
      const fetchInsights = async () => {
        setIsHintsLoading(true);
        const otherListsContext = lists
          .filter(l => l.id !== activeListId)
          .map(l => l.items.map(i => i.name).join(', '))
          .join(' | ');

        const res = await getShoppingInsights(activeList?.items.map(i => i.name) || [], otherListsContext, locationStr);
        if (res) {
          setHints(res.hints || []);
          setSuggestions(res.suggestions || []);
        }
        setIsHintsLoading(false);
        lastAnalyzedItemsRef.current = itemsToAnalyze;
      };

      const timer = setTimeout(fetchInsights, 2000);
      return () => clearTimeout(timer);
    } else if (!itemsToAnalyze) {
      setHints([]);
      setSuggestions([]);
    }
  }, [activeList?.items, activeListId, lists, locationStr]);

  // CRUD Operations with Firestore
  const handleAddItem = async (queryStr: string) => {
    if (!activeListId || !currentUser) return;
    const newProcessingId = crypto.randomUUID();
    const newProcessingItem: ProcessingItem = {
      id: newProcessingId,
      query: queryStr,
      status: 'categorizing'
    };

    setProcessingItems(prev => [newProcessingItem, ...prev]);

    try {
      let name = queryStr;
      let barcode = "";
      let brand = "";
      let imageUrl = "";
      let approxPrice: number | undefined;

      const isBarcode = /^\d{8,14}$/.test(queryStr);
      if (isBarcode) {
        const upcResult = await lookupBarcode(queryStr);
        if (upcResult?.product) {
          name = upcResult.product.name;
          brand = upcResult.product.brand || "";
          imageUrl = upcResult.product.imageUrl || "";
          barcode = queryStr;
        } else {
          name = await searchItemContext(queryStr) || `Produkt ${queryStr}`;
        }
      }

      setProcessingItems(prev => prev.map(item => item.id === newProcessingId ? { ...item, status: 'pricing' } : item));
      const aiData = await categorizeAndPriceItem(name, locationStr);
      approxPrice = aiData.approxPrice;

      const newItem: GroceryItem = {
        id: crypto.randomUUID(),
        name,
        category: aiData.category,
        emoji: aiData.emoji,
        color: aiData.color,
        quantity: 1,
        price: approxPrice,
        barcode: barcode || undefined,
        brand: brand || undefined,
        imageUrl: imageUrl || undefined,
        addedAt: Date.now(),
        completed: false
      };

      const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
      const updatedItems = [newItem, ...(activeList?.items || [])];
      await updateDoc(listRef, { items: updatedItems });

    } catch (e) {
      console.error("Add item failed", e);
    } finally {
      setProcessingItems(prev => prev.filter(item => item.id !== newProcessingId));
    }
  };

  const toggleItem = async (itemId: string) => {
    if (!currentUser || !activeList) return;
    const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
    const updatedItems = activeList.items.map(i => 
      i.id === itemId ? { ...i, completed: !i.completed } : i
    );
    await updateDoc(listRef, { items: updatedItems });
  };

  const updateItem = async (itemId: string, updates: Partial<GroceryItem>) => {
    if (!currentUser || !activeList) return;
    const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
    const updatedItems = activeList.items.map(i => 
      i.id === itemId ? { ...i, ...updates } : i
    );
    await updateDoc(listRef, { items: updatedItems });
  };

  const deleteItem = async (itemId: string) => {
    if (!currentUser || !activeList) return;
    const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
    const updatedItems = activeList.items.filter(i => i.id !== itemId);
    await updateDoc(listRef, { items: updatedItems });
  };

  const clearCompleted = async () => {
    if (!currentUser || !activeList) return;
    const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
    const updatedItems = activeList.items.filter(i => !i.completed);
    await updateDoc(listRef, { items: updatedItems });
  };

  const handleCreateNewList = async (customName?: string) => {
    if (!currentUser) return;
    const listId = crypto.randomUUID();
    const name = customName || "Ny Indkøbsliste";
    const newList: Omit<ShoppingList, 'id'> = {
      name,
      items: [],
      createdAt: Date.now()
    };

    await setDoc(doc(db, `users/${currentUser.uid}/lists`, listId), newList);
    setActiveListId(listId);
    setIsMenuOpen(false);
  };

  const handleDeleteList = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!currentUser || lists.length <= 1) return;
    await deleteDoc(doc(db, `users/${currentUser.uid}/lists`, id));
    if (activeListId === id) setActiveListId(lists.find(l => l.id !== id)?.id || '');
  };

  const saveRename = async () => {
    if (currentUser && editingListNameId && tempListName.trim()) {
      await updateDoc(doc(db, `users/${currentUser.uid}/lists`, editingListNameId), {
        name: tempListName.trim()
      });
    }
    setEditingListNameId(null);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('da-DK', {
      style: 'currency',
      currency: 'DKK',
    }).format(val);
  };

  if (authLoading) {
    return (
      <div className="min-h-screen bg-[#09090b] flex items-center justify-center">
        <Loader2 className="w-10 h-10 text-purple-500 animate-spin" />
      </div>
    );
  }

  if (!currentUser) {
    return <Auth />;
  }

  const hasInsights = hints.length > 0 || suggestions.length > 0;

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 selection:bg-purple-500/30 flex flex-col">
      <div className="fixed top-0 left-1/2 -translate-x-1/2 w-full max-w-6xl h-[600px] bg-purple-500/5 blur-[120px] rounded-full pointer-events-none -z-10" />

      {/* Header */}
      <nav className="sticky top-0 z-50 border-b border-zinc-800/50 glass">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-lg shadow-white/5">
                <ShoppingCart className="w-5 h-5 text-zinc-950" />
              </div>
              <span className="text-lg font-bold tracking-tight hidden sm:inline">Groc<span className="text-purple-500">AI</span></span>
            </div>

            <div className="h-6 w-px bg-zinc-800" />

            {/* List Switcher */}
            <div className="relative">
              <button 
                onClick={() => setIsMenuOpen(!isMenuOpen)}
                className="flex items-center gap-2 group hover:bg-zinc-800/50 px-3 py-1.5 rounded-lg transition-colors border border-transparent hover:border-zinc-700/50"
              >
                <div className="flex flex-col items-start leading-tight">
                  <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Aktiv Liste</span>
                  <span className="text-sm font-semibold text-zinc-200 group-hover:text-white transition-colors max-w-[120px] truncate">
                    {activeList?.name || "Henter..."}
                  </span>
                </div>
                <ChevronDown className={`w-4 h-4 text-zinc-500 transition-transform duration-300 ${isMenuOpen ? 'rotate-180' : ''}`} />
              </button>

              {isMenuOpen && (
                <>
                  <div className="fixed inset-0 z-40" onClick={() => setIsMenuOpen(false)} />
                  <div className="absolute top-full left-0 mt-2 w-64 bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl z-50 p-2 animate-in fade-in zoom-in-95 duration-200">
                    <div className="space-y-1 max-h-[300px] overflow-y-auto custom-scrollbar pr-1">
                      {lists.map(list => (
                        <div 
                          key={list.id}
                          onClick={() => { setActiveListId(list.id); setIsMenuOpen(false); }}
                          className={`group flex items-center justify-between p-3 rounded-xl cursor-pointer transition-all ${
                            activeListId === list.id ? 'bg-purple-500/10 text-purple-400 ring-1 ring-purple-500/20' : 'hover:bg-zinc-800 text-zinc-400 hover:text-white'
                          }`}
                        >
                          <div className="flex items-center gap-3 min-w-0">
                            <div className={`w-1.5 h-1.5 rounded-full ${activeListId === list.id ? 'bg-purple-500' : 'bg-zinc-700 opacity-0 group-hover:opacity-100'}`} />
                            {editingListNameId === list.id ? (
                              <input 
                                autoFocus
                                value={tempListName}
                                onClick={e => e.stopPropagation()}
                                onChange={e => setTempListName(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && saveRename()}
                                className="bg-zinc-950 border border-zinc-700 rounded px-2 py-0.5 text-xs text-white outline-none w-32"
                              />
                            ) : (
                              <span className="text-xs font-bold truncate">{list.name}</span>
                            )}
                          </div>
                          <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
                            {editingListNameId === list.id ? (
                              <button onClick={(e) => { e.stopPropagation(); saveRename(); }} className="p-1 hover:text-green-400 transition-colors"><Check className="w-3.5 h-3.5" /></button>
                            ) : (
                              <button onClick={(e) => { e.stopPropagation(); setEditingListNameId(list.id); setTempListName(list.name); }} className="p-1 hover:text-purple-400 transition-colors"><Edit3 className="w-3.5 h-3.5" /></button>
                            )}
                            <button onClick={(e) => handleDeleteList(list.id, e)} className="p-1 hover:text-red-400 transition-colors"><Trash2 className="w-3.5 h-3.5" /></button>
                          </div>
                        </div>
                      ))}
                    </div>
                    <div className="mt-2 pt-2 border-t border-zinc-800">
                      <button 
                        onClick={() => handleCreateNewList()}
