        </div>

        {/* Input */}
        <div className="sticky top-20 z-40 pb-6 pointer-events-none">
          <div className="absolute inset-x-0 -top-8 h-32 bg-gradient-to-b from-[#09090b] via-[#09090b] to-transparent -z-10" />
          <div className="pointer-events-auto space-y-4">
            <SearchInput onAdd={handleAddItem} isLoading={false} />

            {processingItems.length > 0 && (
              <div className="max-w-2xl mx-auto space-y-2">
                {processingItems.map((pItem) => (
                  <div key={pItem.id} className="flex items-center gap-4 p-4 bg-zinc-900/60 border border-purple-500/30 rounded-2xl shadow-xl animate-in slide-in-from-top-2 duration-300">
