                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* List Controls */}
        <div className="flex items-center justify-between mt-10 mb-8 border-b border-zinc-800/80 pb-5">
          <div className="flex gap-4">
            <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-zinc-600 flex items-center gap-2">
              <div className="w-1.5 h-1.5 rounded-full bg-green-500/50 animate-pulse" />
              Kategoriseret Visning
            </div>
          </div>
          <button 
            onClick={clearCompleted}
            disabled={!activeList?.items.some(i => i.completed)}
            className="text-[10px] font-extrabold uppercase tracking-[0.2em] text-zinc-500 hover:text-white transition-all disabled:opacity-0"
          >
            Ryd Færdiggjorte
          </button>
        </div>

        <GroceryList 
          items={activeList?.items || []} 
          onToggle={toggleItem} 
          onDelete={deleteItem} 
          onUpdate={updateItem}
        />

        {/* Grand Total */}
        {activeList && activeList.items.length > 0 && (
          <div className="mt-20 border-t border-zinc-800/80 pt-10 pb-16">
             <div className="flex flex-col items-center">
                <div className="w-full max-w-sm bg-zinc-900/40 border border-zinc-800/50 rounded-3xl p-8 backdrop-blur-sm shadow-2xl">
                   <div className="relative space-y-6">
                      <div className="flex justify-between items-center text-zinc-400">
                        <span className="text-xs font-bold uppercase tracking-widest">Estimering Total</span>
                        <h2 className="text-3xl font-extrabold text-white tracking-tighter">
                          {formatCurrency(grandTotal)}
                        </h2>
                      </div>
                      <div className="flex justify-between items-center pt-2">
                        <div className="flex items-center gap-2 text-[10px] font-bold text-zinc-600 uppercase tracking-widest">
                           <Cloud className="w-3 h-3" />
                           Permanent Gemt
                        </div>
                        <DollarSign className="w-6 h-6 text-purple-500" />
                      </div>
                   </div>
                </div>
             </div>
          </div>
        )}
      </main>

      <footer className="mt-auto border-t border-zinc-800/50 py-12 px-6 bg-zinc-950/20">
        <div className="max-w-4xl mx-auto flex flex-col md:flex-row justify-between items-center gap-8 text-zinc-600">
          <div className="flex items-center gap-2">
            <ShoppingCart className="w-4 h-4 opacity-30" />
            <span className="text-[10px] font-bold uppercase tracking-widest">GrocAI Cloud • v2.1</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

