import { getAuth, GoogleAuthProvider, signInWithPopup, signOut, onAuthStateChanged, User, Auth } from "firebase/auth";
import { 
  getFirestore, 
  doc, 
  collection, 
  onSnapshot, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy, 
  writeBatch, 
  Firestore,
  enableMultiTabIndexedDbPersistence
} from "firebase/firestore";

const projectId = process.env.FIREBASE_PROJECT_ID || "grocai-cloud-app";

const firebaseConfig = {
  apiKey: process.env.API_KEY,
  authDomain: `${projectId}.firebaseapp.com`,
  projectId: projectId,
  storageBucket: `${projectId}.appspot.com`,
  messagingSenderId: "123456789", 
  appId: "1:123456789:web:abcdef" 
};

let app: FirebaseApp;
try {
  app = getApps().length === 0 ? initializeApp(firebaseConfig) : getApp();
} catch (e) {
  app = initializeApp(firebaseConfig);
}

export const auth: Auth = getAuth(app);
export const db: Firestore = getFirestore(app);

// Aktiver offline persistens
enableMultiTabIndexedDbPersistence(db).catch((err) => {
    if (err.code === 'failed-precondition') {
        // Flere faner åbne, persistens kan kun aktiveres i én fane ad gangen.
        console.warn("Firestore persistence failed: Multiple tabs open.");
    } else if (err.code === 'unimplemented') {
        // Browseren understøtter ikke IndexedDB.
        console.warn("Firestore persistence is not supported by this browser.");
    }
});

const googleProvider = new GoogleAuthProvider();

export const signInWithGoogle = () => signInWithPopup(auth, googleProvider);
export const logOut = () => signOut(auth);

export const onAuthChange = (callback: (user: User | null) => void) => {
  return onAuthStateChanged(auth, callback);
};

export { 
  doc, 
  collection, 
  onSnapshot, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy, 
  writeBatch 
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { 
  ShoppingCart, 
  Sparkles, 
  Zap, 
  Terminal, 
  Undo2, 
  Redo2, 
  ChevronDown, 
  ListPlus, 
  Trash2, 
  Edit3, 
  Check, 
  DollarSign, 
  Lightbulb,
  X,
  Loader2,
  Navigation,
  Activity,
  ChevronRight,
  Info,
  PlusCircle,
  LogOut,
  User as UserIcon,
  Cloud,
  WifiOff,
  Wifi
} from 'lucide-react';
import { User } from 'firebase/auth';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import Auth from './components/Auth';
import { GroceryItem, ShoppingList } from './types';
import { categorizeAndPriceItem, searchItemContext, getShoppingInsights } from './services/geminiService';
import { lookupBarcode } from './services/upcService';
import { 
  auth, 
  db, 
  logOut, 
  onAuthChange, 
  collection, 
  doc, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  onSnapshot, 
  query, 
  where, 
  orderBy,
  writeBatch
} from './services/firebaseService';

interface ProcessingItem {
  id: string;
  query: string;
  status: 'categorizing' | 'pricing' | 'finalizing';
}

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [activeListId, setActiveListId] = useState<string>('');
  const [processingItems, setProcessingItems] = useState<ProcessingItem[]>([]);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isHintsOpen, setIsHintsOpen] = useState(false);
  const [editingListNameId, setEditingListNameId] = useState<string | null>(null);
  const [tempListName, setTempListName] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  const [hints, setHints] = useState<string[]>([]);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [isHintsLoading, setIsHintsLoading] = useState(false);
  const [locationStr, setLocationStr] = useState<string | undefined>();
  const lastAnalyzedItemsRef = useRef<string>('');

  // Netværks-overvågning
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Handle Auth Changes
  useEffect(() => {
    return onAuthChange((user) => {
      setCurrentUser(user);
      setAuthLoading(false);
    });
  }, []);

  // Fetch Location
  useEffect(() => {
    if (currentUser && isOnline && "geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((pos) => {
        setLocationStr(`${pos.coords.latitude}, ${pos.coords.longitude}`);
      }, (err) => console.log("Geolocation denied", err));
    }
  }, [currentUser, isOnline]);

  // Firestore Real-time Sync (Virker nu også offline via persistens)
  useEffect(() => {
    if (!currentUser) return;

    setIsSyncing(true);
    const q = query(
      collection(db, `users/${currentUser.uid}/lists`),
      orderBy("createdAt", "desc")
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetchedLists: ShoppingList[] = [];
      snapshot.forEach((doc) => {
        fetchedLists.push({ id: doc.id, ...doc.data() } as ShoppingList);
      });

      setLists(fetchedLists);

      if (fetchedLists.length > 0 && !activeListId) {
        setActiveListId(fetchedLists[0].id);
      } else if (fetchedLists.length === 0 && isOnline) {
        handleCreateNewList("Min Første Liste");
      }
      setIsSyncing(false);
    }, (error) => {
      console.error("Firestore error:", error);
      setIsSyncing(false);
    });

    return () => unsubscribe();
  }, [currentUser]);

  const activeList = useMemo(() => 
    lists.find(l => l.id === activeListId) || lists[0], 
    [lists, activeListId]
  );

  const grandTotal = useMemo(() => {
    return activeList?.items.reduce((sum, item) => sum + (item.price || 0) * item.quantity, 0) || 0;
  }, [activeList]);

  // AI Insights Effect (Deaktiveret hvis offline)
  useEffect(() => {
    if (!isOnline) {
        setHints([]);
        setSuggestions([]);
        return;
    }

    const itemsToAnalyze = activeList?.items.map(i => i.name).sort().join(',') || '';
    if (itemsToAnalyze && itemsToAnalyze !== lastAnalyzedItemsRef.current) {
      const fetchInsights = async () => {
        setIsHintsLoading(true);
        const otherListsContext = lists
          .filter(l => l.id !== activeListId)
          .map(l => l.items.map(i => i.name).join(', '))
          .join(' | ');

        const res = await getShoppingInsights(activeList?.items.map(i => i.name) || [], otherListsContext, locationStr);
        if (res) {
          setHints(res.hints || []);
          setSuggestions(res.suggestions || []);
        }
        setIsHintsLoading(false);
        lastAnalyzedItemsRef.current = itemsToAnalyze;
      };

      const timer = setTimeout(fetchInsights, 2000);
      return () => clearTimeout(timer);
    } else if (!itemsToAnalyze) {
      setHints([]);
      setSuggestions([]);
    }
  }, [activeList?.items, activeListId, lists, locationStr, isOnline]);

  // CRUD Operations with Firestore
  const handleAddItem = async (queryStr: string) => {
    if (!activeListId || !currentUser) return;

    // Hvis vi er offline, tilføj bare varen simpelt uden AI opslag
    if (!isOnline) {
        const newItem: GroceryItem = {
            id: crypto.randomUUID(),
            name: queryStr,
            category: "Andet",
            emoji: "🛒",
            color: "#71717a",
            quantity: 1,
            addedAt: Date.now(),
            completed: false
        };
        const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
        const updatedItems = [newItem, ...(activeList?.items || [])];
        await updateDoc(listRef, { items: updatedItems });
        return;
    }

    const newProcessingId = crypto.randomUUID();
    const newProcessingItem: ProcessingItem = {
      id: newProcessingId,
      query: queryStr,
      status: 'categorizing'
    };

    setProcessingItems(prev => [newProcessingItem, ...prev]);

    try {
      let name = queryStr;
      let barcode = "";
      let brand = "";
      let imageUrl = "";
      let approxPrice: number | undefined;

      const isBarcode = /^\d{8,14}$/.test(queryStr);
      if (isBarcode) {
        const upcResult = await lookupBarcode(queryStr);
        if (upcResult?.product) {
          name = upcResult.product.name;
          brand = upcResult.product.brand || "";
          imageUrl = upcResult.product.imageUrl || "";
          barcode = queryStr;
        } else {
          name = await searchItemContext(queryStr) || `Produkt ${queryStr}`;
        }
      }

      setProcessingItems(prev => prev.map(item => item.id === newProcessingId ? { ...item, status: 'pricing' } : item));
      const aiData = await categorizeAndPriceItem(name, locationStr);
      approxPrice = aiData.approxPrice;

      const newItem: GroceryItem = {
        id: crypto.randomUUID(),
        name,
        category: aiData.category,
        emoji: aiData.emoji,
        color: aiData.color,
        quantity: 1,
        price: approxPrice,
        barcode: barcode || undefined,
        brand: brand || undefined,
        imageUrl: imageUrl || undefined,
        addedAt: Date.now(),
        completed: false
      };

      const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
      const updatedItems = [newItem, ...(activeList?.items || [])];
      await updateDoc(listRef, { items: updatedItems });

    } catch (e) {
      console.error("Add item failed", e);
    } finally {
      setProcessingItems(prev => prev.filter(item => item.id !== newProcessingId));
    }
  };

  const toggleItem = async (itemId: string) => {
    if (!currentUser || !activeList) return;
    const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
    const updatedItems = activeList.items.map(i => 
      i.id === itemId ? { ...i, completed: !i.completed } : i
    );
    await updateDoc(listRef, { items: updatedItems });
  };

  const updateItem = async (itemId: string, updates: Partial<GroceryItem>) => {
    if (!currentUser || !activeList) return;
    const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
    const updatedItems = activeList.items.map(i => 
      i.id === itemId ? { ...i, ...updates } : i
    );
    await updateDoc(listRef, { items: updatedItems });
  };

  const deleteItem = async (itemId: string) => {
    if (!currentUser || !activeList) return;
    const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
    const updatedItems = activeList.items.filter(i => i.id !== itemId);
    await updateDoc(listRef, { items: updatedItems });
  };

  const clearCompleted = async () => {
    if (!currentUser || !activeList) return;
    const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
    const updatedItems = activeList.items.filter(i => !i.completed);
    await updateDoc(listRef, { items: updatedItems });
  };

  const handleCreateNewList = async (customName?: string) => {
    if (!currentUser) return;
    const listId = crypto.randomUUID();
    const name = customName || "Ny Indkøbsliste";
    const newList: Omit<ShoppingList, 'id'> = {
      name,
      items: [],
      createdAt: Date.now()
    };

    await setDoc(doc(db, `users/${currentUser.uid}/lists`, listId), newList);
    setActiveListId(listId);
    setIsMenuOpen(false);
  };

  const handleDeleteList = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!currentUser || lists.length <= 1) return;
    await deleteDoc(doc(db, `users/${currentUser.uid}/lists`, id));
    if (activeListId === id) setActiveListId(lists.find(l => l.id !== id)?.id || '');
  };

  const saveRename = async () => {
    if (currentUser && editingListNameId && tempListName.trim()) {
      await updateDoc(doc(db, `users/${currentUser.uid}/lists`, editingListNameId), {
        name: tempListName.trim()
      });
    }
    setEditingListNameId(null);
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('da-DK', {
      style: 'currency',
      currency: 'DKK',
    }).format(val);
  };

  if (authLoading) {
    return (
      <div className="min-h-screen bg-[#09090b] flex items-center justify-center">
        <Loader2 className="w-10 h-10 text-purple-500 animate-spin" />
      </div>
    );
  }

  if (!currentUser) {
    return <Auth />;
  }

  const hasInsights = hints.length > 0 || suggestions.length > 0;

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 selection:bg-purple-500/30 flex flex-col">
      <div className="fixed top-0 left-1/2 -translate-x-1/2 w-full max-w-6xl h-[600px] bg-purple-500/5 blur-[120px] rounded-full pointer-events-none -z-10" />

      {/* Header */}
      <nav className="sticky top-0 z-50 border-b border-zinc-800/50 glass">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-lg shadow-white/5">
                <ShoppingCart className="w-5 h-5 text-zinc-950" />
              </div>
              <span className="text-lg font-bold tracking-tight hidden sm:inline">Groc<span className="text-purple-500">AI</span></span>
            </div>

            <div className="h-6 w-px bg-zinc-800" />

            <div className="relative">
              <button 
                onClick={() => setIsMenuOpen(!isMenuOpen)}
                className="flex items-center gap-2 group hover:bg-zinc-800/50 px-3 py-1.5 rounded-lg transition-colors border border-transparent hover:border-zinc-700/50"
              >
                <div className="flex flex-col items-start leading-tight">
                  <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-widest">Aktiv Liste</span>
                  <span className="text-sm font-semibold text-zinc-200 group-hover:text-white transition-colors max-w-[120px] truncate">
                    {activeList?.name || "Henter..."}
                  </span>
                </div>
                <ChevronDown className={`w-4 h-4 text-zinc-500 transition-transform duration-300 ${isMenuOpen ? 'rotate-180' : ''}`} />
              </button>

              {isMenuOpen && (
                <>
                  <div className="fixed inset-0 z-40" onClick={() => setIsMenuOpen(false)} />
                  <div className="absolute top-full left-0 mt-2 w-64 bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl z-50 p-2 animate-in fade-in zoom-in-95 duration-200">
                    <div className="space-y-1 max-h-[300px] overflow-y-auto custom-scrollbar pr-1">
                      {lists.map(list => (
                        <div 
                          key={list.id}
                          onClick={() => { setActiveListId(list.id); setIsMenuOpen(false); }}
                          className={`group flex items-center justify-between p-3 rounded-xl cursor-pointer transition-all ${
                            activeListId === list.id ? 'bg-purple-500/10 text-purple-400 ring-1 ring-purple-500/20' : 'hover:bg-zinc-800 text-zinc-400 hover:text-white'
                          }`}
                        >
                          <div className="flex items-center gap-3 min-w-0">
                            <div className={`w-1.5 h-1.5 rounded-full ${activeListId === list.id ? 'bg-purple-500' : 'bg-zinc-700 opacity-0 group-hover:opacity-100'}`} />
                            {editingListNameId === list.id ? (
                              <input 
                                autoFocus
                                value={tempListName}
                                onClick={e => e.stopPropagation()}
                                onChange={e => setTempListName(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && saveRename()}
                                className="bg-zinc-950 border border-zinc-700 rounded px-2 py-0.5 text-xs text-white outline-none w-32"
                              />
                            ) : (
                              <span className="text-xs font-bold truncate">{list.name}</span>
                            )}
                          </div>
                          <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
                            {editingListNameId === list.id ? (
                              <button onClick={(e) => { e.stopPropagation(); saveRename(); }} className="p-1 hover:text-green-400 transition-colors"><Check className="w-3.5 h-3.5" /></button>
                            ) : (
                              <button onClick={(e) => { e.stopPropagation(); setEditingListNameId(list.id); setTempListName(list.name); }} className="p-1 hover:text-purple-400 transition-colors"><Edit3 className="w-3.5 h-3.5" /></button>
                            )}
                            <button onClick={(e) => handleDeleteList(list.id, e)} className="p-1 hover:text-red-400 transition-colors"><Trash2 className="w-3.5 h-3.5" /></button>
                          </div>
                        </div>
                      ))}
                    </div>
                    <div className="mt-2 pt-2 border-t border-zinc-800">
                      <button 
                        onClick={() => handleCreateNewList()}
                        className="w-full flex items-center gap-2 p-2.5 rounded-xl text-zinc-500 hover:text-white hover:bg-zinc-800 transition-all group"
                      >
                        <ListPlus className="w-4 h-4 group-hover:scale-110 transition-transform" />
                        <span className="text-xs font-bold uppercase tracking-wider">Ny Indkøbsliste</span>
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>

          <div className="flex items-center gap-4">
            {/* Status Indikatorer */}
            <div className="flex items-center gap-2">
                {!isOnline ? (
                    <div className="flex items-center gap-2 px-3 py-1.5 bg-amber-500/10 border border-amber-500/20 rounded-lg text-amber-400">
                        <WifiOff className="w-3.5 h-3.5" />
                        <span className="text-[10px] font-bold uppercase tracking-widest hidden md:inline">Offline Tilstand</span>
                    </div>
                ) : isSyncing ? (
                    <div className="flex items-center gap-2 px-3 py-1.5 bg-zinc-900/50 border border-zinc-800 rounded-lg text-blue-400">
                        <Cloud className="w-3.5 h-3.5 animate-pulse" />
                        <span className="text-[10px] font-bold uppercase tracking-widest hidden md:inline">Synkroniserer</span>
                    </div>
                ) : (
                    <div className="flex items-center gap-2 px-3 py-1.5 bg-green-500/5 border border-green-500/10 rounded-lg text-green-500/50">
                        <Wifi className="w-3.5 h-3.5" />
                    </div>
                )}
            </div>

            {/* AI Hints */}
            <div className="relative">
              <button 
                disabled={!isOnline}
                onClick={() => setIsHintsOpen(!isHintsOpen)}
                className={`relative p-2 rounded-xl border transition-all ${
                  !isOnline 
                    ? 'bg-zinc-900/20 border-zinc-800 text-zinc-700 cursor-not-allowed'
                    : hasInsights 
                    ? 'bg-purple-500/10 border-purple-500/30 text-purple-400 animate-pulse ring-4 ring-purple-500/5' 
                    : 'bg-zinc-900/50 border-zinc-800 text-zinc-500'
                } hover:bg-zinc-800 hover:text-white`}
              >
                <Sparkles className="w-4 h-4" />
                {isOnline && hasInsights && (
                  <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-purple-500 rounded-full border-2 border-[#09090b]" />
                )}
              </button>

              {isHintsOpen && isOnline && (
                <>
                  <div className="fixed inset-0 z-40" onClick={() => setIsHintsOpen(false)} />
                  <div className="absolute top-full right-0 mt-3 w-80 bg-zinc-900 border border-zinc-800 rounded-2xl shadow-2xl z-50 p-4 animate-in fade-in zoom-in-95 duration-300 glass max-h-[80vh] overflow-y-auto">
                    <div className="absolute inset-0 bg-gradient-to-br from-purple-500/5 to-transparent pointer-events-none" />
                    <div className="relative">
                      <div className="flex items-center justify-between mb-4">
                        <div className="flex items-center gap-2">
                          <Sparkles className="w-4 h-4 text-purple-400" />
                          <h4 className="text-[10px] font-extrabold text-white tracking-[0.2em] uppercase">Smart Assistent</h4>
                        </div>
                        <button onClick={() => setIsHintsOpen(false)} className="text-zinc-600 hover:text-white">
                          <X className="w-4 h-4" />
                        </button>
                      </div>

                      <div className="space-y-4">
                        {isHintsLoading ? (
                          <div className="flex items-center gap-3 p-3 bg-zinc-950/40 rounded-xl border border-zinc-800">
                            <Loader2 className="w-4 h-4 text-purple-500 animate-spin" />
                            <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Analyserer...</span>
                          </div>
                        ) : hasInsights ? (
                          <>
                            {hints.length > 0 && (
                              <div className="space-y-2">
                                <p className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">Prisindsigt</p>
                                {hints.map((hint, idx) => (
                                  <div key={idx} className="flex items-start gap-3 p-3 bg-zinc-950/40 rounded-xl border border-zinc-800/50">
                                    <Lightbulb className="w-4 h-4 text-yellow-500 shrink-0 mt-0.5" />
                                    <p className="text-[11px] font-medium text-zinc-300 leading-relaxed">{hint}</p>
                                  </div>
                                ))}
                              </div>
                            )}

                            {suggestions.length > 0 && (
                              <div className="space-y-2">
                                <p className="text-[8px] font-black text-zinc-600 uppercase tracking-widest">Glemte varer?</p>
                                {suggestions.map((suggestion, idx) => (
                                  <button 
                                    key={idx} 
                                    onClick={() => handleAddItem(suggestion)}
                                    className="w-full flex items-center justify-between gap-3 p-3 bg-purple-500/5 hover:bg-purple-500/10 rounded-xl border border-purple-500/20 transition-all group"
                                  >
                                    <div className="flex items-center gap-3">
                                      <PlusCircle className="w-4 h-4 text-purple-400 group-hover:scale-110" />
                                      <p className="text-[11px] font-bold text-zinc-200">{suggestion}</p>
                                    </div>
                                    <ChevronRight className="w-3 h-3 text-zinc-700" />
                                  </button>
                                ))}
                              </div>
                            )}
                          </>
                        ) : (
                          <div className="text-center py-6">
                            <Info className="w-8 h-8 text-zinc-800 mx-auto mb-2" />
                            <p className="text-[10px] font-bold text-zinc-600 uppercase tracking-widest">Ingen tips</p>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </>
              )}
            </div>

            {/* User Profile / Logout */}
            <div className="relative group">
              <button className="w-10 h-10 rounded-full border border-zinc-800 bg-zinc-900/50 flex items-center justify-center overflow-hidden hover:border-purple-500/50 transition-all">
                {currentUser.photoURL ? (
                  <img src={currentUser.photoURL} className="w-full h-full object-cover" alt="User" />
                ) : (
                  <UserIcon className="w-5 h-5 text-zinc-500" />
                )}
              </button>
              <div className="absolute top-full right-0 mt-2 opacity-0 pointer-events-none group-hover:opacity-100 group-hover:pointer-events-auto transition-all duration-200">
                <div className="bg-zinc-900 border border-zinc-800 rounded-xl p-2 shadow-2xl min-w-[160px]">
                  <div className="px-3 py-2 border-b border-zinc-800 mb-1">
                    <p className="text-xs font-bold text-white truncate">{currentUser.displayName || "Bruger"}</p>
                    <p className="text-[10px] text-zinc-500 truncate">{currentUser.email}</p>
                  </div>
                  <button 
                    onClick={logOut}
                    className="w-full flex items-center gap-3 p-2.5 rounded-lg text-red-400 hover:bg-red-400/10 transition-all"
                  >
                    <LogOut className="w-4 h-4" />
