import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { 
  ShoppingCart, 
  Sparkles, 
  Zap, 
  Terminal, 
  ListPlus, 
  Trash2, 
  Edit3, 
  Check, 
  DollarSign, 
  Lightbulb,
  X,
  Loader2,
  Activity,
  ChevronRight,
  Info,
  PlusCircle,
  LogOut,
  User as UserIcon,
  Cloud,
  WifiOff,
  Wifi,
  ChevronDown,
  Database
} from 'lucide-react';
import { User } from 'firebase/auth';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import Auth from './components/Auth';
import { GroceryItem, ShoppingList } from './types';
import { categorizeAndPriceItem, searchItemContext, getShoppingInsights } from './services/geminiService';
import { lookupBarcode } from './services/upcService';
import { 
  firebaseEnabled,
  auth, 
  db, 
  logOut, 
  onAuthChange, 
  collection, 
  doc, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  onSnapshot, 
  query, 
  orderBy
} from './services/firebaseService';

const LOCAL_STORAGE_KEY = 'grocai_local_lists';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [activeListId, setActiveListId] = useState<string>('');
  const [processingItems, setProcessingItems] = useState<any[]>([]);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isHintsOpen, setIsHintsOpen] = useState(false);
  const [editingListNameId, setEditingListNameId] = useState<string | null>(null);
  const [tempListName, setTempListName] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  const [hints, setHints] = useState<string[]>([]);
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [isHintsLoading, setIsHintsLoading] = useState(false);
  const lastAnalyzedItemsRef = useRef<string>('');

  // Netværks-overvågning
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Handle Auth
  useEffect(() => {
    return onAuthChange((user) => {
      setCurrentUser(user);
      setAuthLoading(false);

      // Hvis Firebase er deaktiveret, indlæs fra localStorage med det samme
      if (!firebaseEnabled) {
        const localData = localStorage.getItem(LOCAL_STORAGE_KEY);
        if (localData) {
          const parsed = JSON.parse(localData);
          setLists(parsed);
          if (parsed.length > 0) setActiveListId(parsed[0].id);
        } else {
          handleCreateNewList("Min Lokale Liste");
        }
      }
    });
  }, []);

  // Sync Logic
  useEffect(() => {
    if (!firebaseEnabled || !currentUser || !db) return;

    setIsSyncing(true);
    const q = query(collection(db, `users/${currentUser.uid}/lists`), orderBy("createdAt", "desc"));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const fetchedLists: ShoppingList[] = [];
      snapshot.forEach((doc) => {
        fetchedLists.push({ id: doc.id, ...doc.data() } as ShoppingList);
      });
      setLists(fetchedLists);
      if (fetchedLists.length > 0 && !activeListId) setActiveListId(fetchedLists[0].id);
      setIsSyncing(false);
    });

    return () => unsubscribe();
  }, [currentUser]);

  // Save to localStorage if Firebase is disabled
  useEffect(() => {
    if (!firebaseEnabled) {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(lists));
    }
  }, [lists]);

  const activeList = useMemo(() => 
    lists.find(l => l.id === activeListId) || lists[0], 
    [lists, activeListId]
  );

  const grandTotal = useMemo(() => {
    return activeList?.items.reduce((sum, item) => sum + (item.price || 0) * item.quantity, 0) || 0;
  }, [activeList]);

  // AI Insights
  useEffect(() => {
    if (!isOnline) return;
    const itemsToAnalyze = activeList?.items.map(i => i.name).sort().join(',') || '';
    if (itemsToAnalyze && itemsToAnalyze !== lastAnalyzedItemsRef.current) {
      const fetchInsights = async () => {
        setIsHintsLoading(true);
        const res = await getShoppingInsights(activeList?.items.map(i => i.name) || []);
        if (res) {
          setHints(res.hints || []);
          setSuggestions(res.suggestions || []);
        }
        setIsHintsLoading(false);
        lastAnalyzedItemsRef.current = itemsToAnalyze;
      };
      const timer = setTimeout(fetchInsights, 2000);
      return () => clearTimeout(timer);
    }
  }, [activeList?.items, isOnline]);

  const handleAddItem = async (queryStr: string) => {
    if (!activeListId) return;

    const newProcessingId = crypto.randomUUID();
    setProcessingItems(prev => [{ id: newProcessingId, query: queryStr, status: 'categorizing' }, ...prev]);

    try {
      const aiData = await categorizeAndPriceItem(queryStr);
      const newItem: GroceryItem = {
        id: crypto.randomUUID(),
        name: queryStr,
        category: aiData.category,
        emoji: aiData.emoji,
        color: aiData.color,
        quantity: 1,
        price: aiData.approxPrice,
        addedAt: Date.now(),
        completed: false
      };

      if (firebaseEnabled && currentUser && db) {
        const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
        await updateDoc(listRef, { items: [newItem, ...(activeList?.items || [])] });
      } else {
        setLists(prev => prev.map(l => l.id === activeListId ? { ...l, items: [newItem, ...l.items] } : l));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setProcessingItems(prev => prev.filter(p => p.id !== newProcessingId));
    }
  };

  const updateItem = async (itemId: string, updates: Partial<GroceryItem>) => {
    if (firebaseEnabled && currentUser && db && activeListId) {
      const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
      const updatedItems = activeList.items.map(i => i.id === itemId ? { ...i, ...updates } : i);
      await updateDoc(listRef, { items: updatedItems });
    } else {
      setLists(prev => prev.map(l => l.id === activeListId ? { ...l, items: l.items.map(i => i.id === itemId ? { ...i, ...updates } : i) } : l));
    }
  };

  const deleteItem = async (itemId: string) => {
    if (firebaseEnabled && currentUser && db && activeListId) {
      const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
      await updateDoc(listRef, { items: activeList.items.filter(i => i.id !== itemId) });
    } else {
      setLists(prev => prev.map(l => l.id === activeListId ? { ...l, items: l.items.filter(i => i.id !== itemId) } : l));
    }
  };

  const handleCreateNewList = async (name = "Ny Liste") => {
    const id = crypto.randomUUID();
    const newList: ShoppingList = { id, name, items: [], createdAt: Date.now() };

    if (firebaseEnabled && currentUser && db) {
      await setDoc(doc(db, `users/${currentUser.uid}/lists`, id), { name, items: [], createdAt: Date.now() });
    } else {
      setLists(prev => [newList, ...prev]);
    }
    setActiveListId(id);
    setIsMenuOpen(false);
  };

  if (authLoading) return (
    <div className="min-h-screen bg-[#09090b] flex items-center justify-center">
      <Loader2 className="w-10 h-10 text-purple-500 animate-spin" />
    </div>
  );

  if (!currentUser && firebaseEnabled) return <Auth />;

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 flex flex-col">
      <nav className="sticky top-0 z-50 border-b border-zinc-800/50 glass">
        <div className="max-w-4xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-8 h-8 bg-white rounded-lg flex items-center justify-center">
              <ShoppingCart className="w-4 h-4 text-zinc-950" />
            </div>
            <div className="relative">
              <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="flex items-center gap-2 px-3 py-1.5 rounded-lg hover:bg-zinc-800 transition-colors">
                <span className="text-sm font-bold truncate max-w-[120px]">{activeList?.name || "Ingen lister"}</span>
                <ChevronDown className="w-4 h-4 text-zinc-500" />
              </button>
              {isMenuOpen && (
                <div className="absolute top-full left-0 mt-2 w-64 bg-zinc-900 border border-zinc-800 rounded-xl shadow-2xl p-2 z-50">
                  {lists.map(l => (
                    <button key={l.id} onClick={() => { setActiveListId(l.id); setIsMenuOpen(false); }} className={`w-full text-left p-2 rounded-lg text-xs font-bold ${activeListId === l.id ? 'bg-purple-500/10 text-purple-400' : 'text-zinc-500 hover:bg-zinc-800 hover:text-white'}`}>
                      {l.name}
                    </button>
                  ))}
                  <button onClick={() => handleCreateNewList()} className="w-full mt-2 p-2 rounded-lg border border-dashed border-zinc-800 text-zinc-500 text-[10px] font-bold uppercase tracking-widest hover:border-zinc-600">
                    + Ny Liste
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border ${firebaseEnabled ? 'bg-green-500/5 border-green-500/20 text-green-500' : 'bg-amber-500/5 border-amber-500/20 text-amber-500'}`}>
              {firebaseEnabled ? <Cloud className="w-3.5 h-3.5" /> : <Database className="w-3.5 h-3.5" />}
              <span className="text-[10px] font-bold uppercase tracking-widest hidden md:inline">
                {firebaseEnabled ? 'Sky Synkroniseret' : 'Lokal Tilstand'}
              </span>
            </div>
            {currentUser && (
              <button onClick={logOut} className="p-2 text-zinc-500 hover:text-white transition-colors">
                <LogOut className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>
      </nav>

      <main className="flex-1 max-w-4xl mx-auto w-full px-6 py-12">
        <div className="mb-12 space-y-4">
          <h1 className="text-4xl md:text-6xl font-black tracking-tighter">{activeList?.name}</h1>
          <SearchInput onAdd={handleAddItem} isLoading={false} />
          {processingItems.map(p => (
            <div key={p.id} className="flex items-center gap-3 p-4 bg-zinc-900/50 border border-purple-500/30 rounded-2xl animate-pulse">
              <Loader2 className="w-4 h-4 text-purple-500 animate-spin" />
              <span className="text-xs font-bold text-zinc-400 uppercase tracking-widest">Kategoriserer {p.query}...</span>
            </div>
          ))}
        </div>

        <GroceryList 
          items={activeList?.items || []} 
          onToggle={(id) => updateItem(id, { completed: !activeList?.items.find(i => i.id === id)?.completed })} 
          onDelete={deleteItem} 
          onUpdate={updateItem}
        />

        {activeList?.items.length > 0 && (
          <div className="mt-12 p-8 glass rounded-[2rem] border-zinc-800/50 flex justify-between items-center">
            <div>
              <p className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em] mb-1">Samlet Estimering</p>
              <h2 className="text-3xl font-black text-white">{new Intl.NumberFormat('da-DK', { style: 'currency', currency: 'DKK' }).format(grandTotal)}</h2>
            </div>
            <Zap className="w-8 h-8 text-purple-500 opacity-20" />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import { initializeApp, getApps, FirebaseApp } from "firebase/app";
import { getAuth, GoogleAuthProvider, signInWithPopup, signOut, onAuthStateChanged, User, Auth } from "firebase/auth";
