} from "firebase/firestore";

// Hent miljøvariabler
const apiKey = process.env.API_KEY;
const projectId = process.env.FIREBASE_PROJECT_ID;

// Vi aktiverer kun Firebase hvis både projekt-id og api-nøgle er til stede.
// Dette forhindrer auth/api-key-not-valid fejlen hvis man kun har en Gemini-nøgle.
const firebaseEnabled = !!projectId && !!apiKey && apiKey !== 'undefined';

const firebaseConfig = {
  apiKey: apiKey,
  authDomain: `${projectId}.firebaseapp.com`,
  projectId: projectId,
  storageBucket: `${projectId}.appspot.com`,
  messagingSenderId: "123456789", 
  appId: "1:123456789:web:abcdef" 
};

let app: FirebaseApp | null = null;
let auth: Auth | null = null;
let db: Firestore | null = null;

if (firebaseEnabled) {
  try {
    if (!getApps().length) {
      app = initializeApp(firebaseConfig);
    } else {
      app = getApps()[0];
    }
    auth = getAuth(app);
    db = getFirestore(app);

    if (typeof window !== "undefined" && db) {
      enableMultiTabIndexedDbPersistence(db).catch((err) => {
        console.warn("Firestore persistence disabled:", err.code);
      });
    }
  } catch (e) {
    console.error("Firebase failed to initialize:", e);
    // Vi sætter firebaseEnabled til false her hvis init fejler (f.eks. pga. ugyldig konfiguration)
    // Men i TS kan vi ikke re-assigne en export const direkte nemt, så vi bruger en intern status
  }
}

const googleProvider = new GoogleAuthProvider();

export const signInWithGoogle = () => {
  if (!auth) return Promise.reject("Cloud-tjenester er ikke konfigureret.");
  return signInWithPopup(auth, googleProvider);
};

export const logOut = () => {
  if (!auth) return Promise.resolve();
  return signOut(auth);
};

export const onAuthChange = (callback: (user: User | null) => void) => {
  if (!auth) {
    callback(null);
    return () => {};
  }
  return onAuthStateChanged(auth, callback);
};

