  firebaseEnabled,
  auth,
  db,
  doc, 
  collection, 
  onSnapshot, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy, 
  writeBatch,
  getDocs
};

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { 
  ShoppingCart, 
  Zap, 
  LogOut, 
  Cloud, 
  ChevronDown, 
  Database,
  Loader2,
  CheckCircle2,
  Trash2,
  PlusCircle,
  HelpCircle,
  LayoutGrid,
  Star,
  Pencil,
  X,
  Check,
  MoreVertical,
  AlertTriangle,
  RefreshCw
} from 'lucide-react';
import { User } from 'firebase/auth';
import SearchInput from './components/SearchInput';
import GroceryList from './components/GroceryList';
import FavoritesBar from './components/FavoritesBar';
import Auth from './components/Auth';
import { GroceryItem, ShoppingList, FavoriteItem } from './types';
import { categorizeAndPriceItem, getShoppingInsights } from './services/geminiService';
import { 
  firebaseEnabled,
  logOut, 
  onAuthChange, 
  collection, 
  doc, 
  setDoc, 
  updateDoc, 
  onSnapshot, 
  query, 
  orderBy,
  db,
  deleteDoc,
  getDocs,
  writeBatch
} from './services/firebaseService';

const LOCAL_STORAGE_KEY = 'grocai_local_lists';
const LOCAL_STORAGE_FAVS = 'grocai_local_favorites';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [lists, setLists] = useState<ShoppingList[]>([]);
  const [favorites, setFavorites] = useState<FavoriteItem[]>([]);
  const [activeListId, setActiveListId] = useState<string>('');
  const [processingItems, setProcessingItems] = useState<any[]>([]);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSyncing, setIsSyncing] = useState(false);

  // Renaming state
  const [editingListNameId, setEditingListNameId] = useState<string | null>(null);
  const [newListName, setNewListName] = useState('');

  // Deleting state
  const [deletingListId, setDeletingListId] = useState<string | null>(null);

  // Netværks-overvågning
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Håndter indlæsning af data og migrering
  useEffect(() => {
    const unsubscribe = onAuthChange(async (user) => {
      setCurrentUser(user);

      if (!firebaseEnabled || !user) {
        // Indlæs lokale data
        const localLists = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
        const localFavs = JSON.parse(localStorage.getItem(LOCAL_STORAGE_FAVS) || '[]');

        setLists(localLists);
        setFavorites(localFavs);

        if (localLists.length > 0) {
          setActiveListId(localLists[0].id);
        } else {
          handleCreateNewList("Min Indkøbsliste");
        }
        setAuthLoading(false);
      } else {
        // Ved login: Tjek om der er lokale data der skal migreres
        await migrateLocalDataToCloud(user);
        setAuthLoading(false);
      }
    });
    return () => unsubscribe();
  }, []);

  // Migreringslogik: Flyt lokal data til Firestore ved login
  const migrateLocalDataToCloud = async (user: User) => {
    if (!db) return;
    setIsSyncing(true);

    try {
      const localLists = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || '[]');
      const localFavs = JSON.parse(localStorage.getItem(LOCAL_STORAGE_FAVS) || '[]');

      if (localLists.length > 0 || localFavs.length > 0) {
        const batch = writeBatch(db);

        // Migrer lister
        for (const list of localLists) {
          const listRef = doc(db, `users/${user.uid}/lists`, list.id);
          batch.set(listRef, list);
        }

        // Migrer favoritter
        for (const fav of localFavs) {
          const favRef = doc(db, `users/${user.uid}/favorites`, fav.id);
          batch.set(favRef, fav);
        }

        await batch.commit();

        // Ryd lokal storage efter succesfuld migrering
        localStorage.removeItem(LOCAL_STORAGE_KEY);
        localStorage.removeItem(LOCAL_STORAGE_FAVS);
      }
    } catch (e) {
      console.error("Migration failed:", e);
    } finally {
      setIsSyncing(false);
    }
  };

  // Sky Synkronisering (Realtid)
  useEffect(() => {
    if (!firebaseEnabled || !currentUser || !db) return;

    const qLists = query(collection(db, `users/${currentUser.uid}/lists`), orderBy("createdAt", "desc"));
    const unsubLists = onSnapshot(qLists, (snapshot) => {
      const fetchedLists: ShoppingList[] = [];
      snapshot.forEach((doc) => {
        fetchedLists.push({ id: doc.id, ...doc.data() } as ShoppingList);
      });
      setLists(fetchedLists);
      if (fetchedLists.length > 0 && !activeListId) {
        setActiveListId(fetchedLists[0].id);
      }
    });

    const qFavs = query(collection(db, `users/${currentUser.uid}/favorites`), orderBy("addedAt", "desc"));
    const unsubFavs = onSnapshot(qFavs, (snapshot) => {
      const fetchedFavs: FavoriteItem[] = [];
      snapshot.forEach((doc) => {
        fetchedFavs.push({ id: doc.id, ...doc.data() } as FavoriteItem);
      });
      setFavorites(fetchedFavs);
    });

    return () => {
      unsubLists();
      unsubFavs();
    };
  }, [currentUser, activeListId]);

  // Gem til localStorage (Fallback)
  useEffect(() => {
    if (!firebaseEnabled || !currentUser) {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(lists));
      localStorage.setItem(LOCAL_STORAGE_FAVS, JSON.stringify(favorites));
    }
  }, [lists, favorites, currentUser]);

  const activeList = useMemo(() => 
    lists.find(l => l.id === activeListId) || lists[0], 
    [lists, activeListId]
  );

  const grandTotal = useMemo(() => {
    return activeList?.items.reduce((sum, item) => sum + (item.price || 0) * item.quantity, 0) || 0;
  }, [activeList]);

  const handleAddItem = async (queryStr: string) => {
    let currentId = activeListId || (lists.length > 0 ? lists[0].id : null);

    if (!currentId) {
        currentId = crypto.randomUUID();
        await handleCreateNewList("Min Indkøbsliste");
    }

    const newProcessingId = crypto.randomUUID();
    setProcessingItems(prev => [{ id: newProcessingId, query: queryStr }, ...prev]);

    try {
      const aiData = await categorizeAndPriceItem(queryStr);
      const isFav = favorites.some(f => f.name.toLowerCase() === queryStr.toLowerCase());

      const newItem: GroceryItem = {
        id: crypto.randomUUID(),
        name: queryStr,
        category: aiData.category,
        emoji: aiData.emoji,
        color: aiData.color,
        quantity: 1,
        price: aiData.approxPrice,
        priceSources: aiData.priceSources,
        addedAt: Date.now(),
        completed: false,
        isFavorite: isFav
      };

      if (firebaseEnabled && currentUser && db && currentId) {
        const listRef = doc(db, `users/${currentUser.uid}/lists`, currentId);
        const currentList = lists.find(l => l.id === currentId);
        const currentItems = currentList?.items || [];
        await updateDoc(listRef, { items: [newItem, ...currentItems] });
      } else {
        setLists(prev => prev.map(l => l.id === currentId ? { ...l, items: [newItem, ...l.items] } : l));
      }
    } catch (e) {
      console.error("Add item failed:", e);
    } finally {
      setProcessingItems(prev => prev.filter(p => p.id !== newProcessingId));
    }
  };

  const handleRenameList = async (id: string, name: string) => {
    if (!name.trim()) return;
    if (firebaseEnabled && currentUser && db) {
      const listRef = doc(db, `users/${currentUser.uid}/lists`, id);
      await updateDoc(listRef, { name: name.trim() });
    } else {
      setLists(prev => prev.map(l => l.id === id ? { ...l, name: name.trim() } : l));
    }
    setEditingListNameId(null);
  };

  const handleDeleteList = async (id: string) => {
    if (lists.length <= 1) return;

    if (firebaseEnabled && currentUser && db) {
      await deleteDoc(doc(db, `users/${currentUser.uid}/lists`, id));
    } else {
      setLists(prev => prev.filter(l => l.id !== id));
    }

    if (activeListId === id) {
      const remainingLists = lists.filter(l => l.id !== id);
      setActiveListId(remainingLists[0]?.id || '');
    }
    setDeletingListId(null);
  };

  const handleAddFavoriteToList = async (fav: FavoriteItem) => {
    let currentId = activeListId || (lists.length > 0 ? lists[0].id : null);
    if (!currentId) return;

    const newItem: GroceryItem = {
      id: crypto.randomUUID(),
      name: fav.name,
      category: fav.category,
      emoji: fav.emoji,
      color: fav.color,
      quantity: 1,
      price: fav.price,
      addedAt: Date.now(),
      completed: false,
      isFavorite: true
    };

    if (firebaseEnabled && currentUser && db) {
      const listRef = doc(db, `users/${currentUser.uid}/lists`, currentId);
      const currentItems = lists.find(l => l.id === currentId)?.items || [];
      await updateDoc(listRef, { items: [newItem, ...currentItems] });
    } else {
      setLists(prev => prev.map(l => l.id === currentId ? { ...l, items: [newItem, ...l.items] } : l));
    }
  };

  const toggleFavorite = async (item: GroceryItem) => {
    const isCurrentlyFav = favorites.some(f => f.name.toLowerCase() === item.name.toLowerCase());

    if (isCurrentlyFav) {
      const favToRemove = favorites.find(f => f.name.toLowerCase() === item.name.toLowerCase());
      if (favToRemove) {
        if (firebaseEnabled && currentUser && db) {
          await deleteDoc(doc(db, `users/${currentUser.uid}/favorites`, favToRemove.id));
        } else {
          setFavorites(prev => prev.filter(f => f.id !== favToRemove.id));
        }
      }
    } else {
      const newFav: FavoriteItem = {
        id: crypto.randomUUID(),
        name: item.name,
        category: item.category,
        emoji: item.emoji,
        color: item.color,
        price: item.price,
        addedAt: Date.now()
      };

      if (firebaseEnabled && currentUser && db) {
        await setDoc(doc(db, `users/${currentUser.uid}/favorites`, newFav.id), newFav);
      } else {
        setFavorites(prev => [newFav, ...prev]);
      }
    }

    const updateFavStatus = (items: GroceryItem[]) => 
      items.map(i => i.name.toLowerCase() === item.name.toLowerCase() ? { ...i, isFavorite: !isCurrentlyFav } : i);

    if (firebaseEnabled && currentUser && db && activeListId) {
       const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
       await updateDoc(listRef, { items: updateFavStatus(activeList.items) });
    } else {
      setLists(prev => prev.map(l => ({ ...l, items: updateFavStatus(l.items) })));
    }
  };

  const updateItem = async (itemId: string, updates: Partial<GroceryItem>) => {
    if (firebaseEnabled && currentUser && db && activeListId) {
      const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
      const updatedItems = activeList.items.map(i => i.id === itemId ? { ...i, ...updates } : i);
      await updateDoc(listRef, { items: updatedItems });
    } else {
      setLists(prev => prev.map(l => l.id === activeListId ? { ...l, items: l.items.map(i => i.id === itemId ? { ...i, ...updates } : i) } : l));
    }
  };

  const deleteItem = async (itemId: string) => {
    if (firebaseEnabled && currentUser && db && activeListId) {
      const listRef = doc(db, `users/${currentUser.uid}/lists`, activeListId);
      await updateDoc(listRef, { items: activeList.items.filter(i => i.id !== itemId) });
    } else {
      setLists(prev => prev.map(l => l.id === activeListId ? { ...l, items: l.items.filter(i => i.id !== itemId) } : l));
    }
  };

  const handleCreateNewList = async (name = "Ny Liste") => {
    const id = crypto.randomUUID();
    const newList: ShoppingList = { id, name, items: [], createdAt: Date.now() };

    if (firebaseEnabled && currentUser && db) {
      await setDoc(doc(db, `users/${currentUser.uid}/lists`, id), newList);
    } else {
      setLists(prev => [newList, ...prev]);
    }
    setActiveListId(id);
    setIsMenuOpen(false);
  };

  if (authLoading) return (
    <div className="min-h-screen bg-[#09090b] flex items-center justify-center">
      <div className="relative">
        <div className="absolute inset-0 bg-purple-500/20 blur-2xl rounded-full animate-pulse" />
        <Loader2 className="w-12 h-12 text-purple-500 animate-spin relative z-10" />
      </div>
    </div>
  );

  if (firebaseEnabled && !currentUser) return <Auth />;

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-100 flex flex-col">
      {/* Sync Overlay */}
      {isSyncing && (
        <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-black/80 backdrop-blur-xl">
          <RefreshCw className="w-12 h-12 text-purple-500 animate-spin mb-6" />
          <h2 className="text-2xl font-black text-white tracking-tight">Synkroniserer dine data...</h2>
          <p className="text-zinc-500 text-sm mt-2">Vi flytter dine lokale lister til skyen.</p>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deletingListId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 glass backdrop-blur-md">
          <div className="w-full max-w-sm bg-zinc-900 border border-white/10 rounded-[2rem] p-8 shadow-2xl animate-in fade-in zoom-in-95 duration-200">
            <div className="w-16 h-16 bg-red-500/10 rounded-2xl flex items-center justify-center mx-auto mb-6">
              <AlertTriangle className="w-8 h-8 text-red-500" />
            </div>
            <h3 className="text-xl font-black text-center mb-2">Slet liste?</h3>
            <p className="text-zinc-400 text-sm text-center mb-8">Er du sikker på at du vil slette "{lists.find(l => l.id === deletingListId)?.name}"? Denne handling kan ikke fortrydes.</p>
            <div className="flex gap-3">
              <button onClick={() => setDeletingListId(null)} className="flex-1 py-3 px-4 bg-zinc-800 hover:bg-zinc-700 text-white font-bold rounded-xl transition-all">Annuller</button>
              <button onClick={() => handleDeleteList(deletingListId)} className="flex-1 py-3 px-4 bg-red-500 hover:bg-red-600 text-white font-bold rounded-xl transition-all">Slet</button>
            </div>
          </div>
        </div>
      )}

      <nav className="sticky top-0 z-50 border-b border-white/5 glass">
        <div className="max-w-4xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="relative group cursor-pointer" onClick={() => window.location.reload()}>
              <div className="absolute inset-0 bg-white/10 blur-lg rounded-xl opacity-0 group-hover:opacity-100 transition-opacity" />
              <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center relative shadow-2xl">
                <ShoppingCart className="w-5 h-5 text-zinc-950" />
              </div>
            </div>
            <div className="relative">
              <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="flex items-center gap-3 px-4 py-2 rounded-xl bg-white/5 hover:bg-white/10 border border-white/5 transition-all group">
                <LayoutGrid className="w-4 h-4 text-zinc-500 group-hover:text-purple-400 transition-colors" />
                <span className="text-sm font-black tracking-tight truncate max-w-[140px]">{activeList?.name || "Vælg liste"}</span>
                <ChevronDown className={`w-4 h-4 text-zinc-600 transition-transform duration-300 ${isMenuOpen ? 'rotate-180' : ''}`} />
              </button>
              {isMenuOpen && (
                <>
                  <div className="fixed inset-0 z-40" onClick={() => setIsMenuOpen(false)} />
                  <div className="absolute top-full left-0 mt-3 w-72 bg-[#0c0c0e] border border-white/10 rounded-2xl shadow-2xl p-3 z-50 animate-in fade-in zoom-in-95 duration-200">
                    <p className="px-3 py-2 text-[10px] font-black text-zinc-600 uppercase tracking-[0.2em] mb-1">Dine Lister</p>
                    <div className="space-y-1 max-h-64 overflow-y-auto pr-1">
                      {lists.map(l => (
                        <div key={l.id} className="flex items-center gap-1 group/item">
                          <button onClick={() => { setActiveListId(l.id); setIsMenuOpen(false); }} className={`flex-1 text-left px-3 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-between ${activeListId === l.id ? 'bg-purple-500/10 text-purple-400 border border-purple-500/20' : 'text-zinc-400 hover:bg-white/5 hover:text-white border border-transparent'}`}>
                            <span className="truncate">{l.name}</span>
                            <span className="text-[10px] font-medium opacity-40 group-hover/item:opacity-100">{l.items.length}</span>
                          </button>
                          <button onClick={(e) => { e.stopPropagation(); setDeletingListId(l.id); }} className={`w-10 h-10 flex items-center justify-center rounded-xl text-zinc-600 hover:text-red-400 hover:bg-red-400/10 transition-all opacity-0 group-hover/item:opacity-100 ${lists.length <= 1 ? 'hidden' : ''}`}>
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      ))}
                    </div>
                    <div className="h-px bg-white/5 my-3" />
                    <button onClick={() => handleCreateNewList()} className="w-full p-2.5 rounded-xl border border-dashed border-white/10 text-zinc-500 text-[10px] font-black uppercase tracking-widest hover:border-purple-500/30 hover:text-purple-400 transition-all flex items-center justify-center gap-2">
                      <PlusCircle className="w-3 h-3" />
                      Ny Liste
                    </button>
                  </div>
                </>
              )}
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className={`flex items-center gap-2 px-3 py-2 rounded-xl border transition-colors ${currentUser ? 'bg-green-500/5 border-green-500/20 text-green-500' : 'bg-amber-500/5 border-amber-500/20 text-amber-500'}`}>
              {currentUser ? <Cloud className="w-3.5 h-3.5" /> : <Database className="w-3.5 h-3.5" />}
              <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">{currentUser ? 'Sky' : 'Lokal'}</span>
            </div>
            {currentUser && (
              <button onClick={logOut} className="w-10 h-10 flex items-center justify-center rounded-xl bg-white/5 border border-white/5 text-zinc-500 hover:text-white hover:bg-red-500/10 hover:border-red-500/20 transition-all">
                <LogOut className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>
      </nav>

      <main className="flex-1 max-w-4xl mx-auto w-full px-6 py-12">
        <div className="mb-12 space-y-8">
          <div className="space-y-4">
            <p className="text-[10px] font-black text-purple-500 uppercase tracking-[0.4em]">Indkøbsoversigt</p>
            {editingListNameId === activeListId ? (
              <div className="flex items-center gap-3 animate-in fade-in slide-in-from-left-4 duration-300">
                <input autoFocus value={newListName} onChange={(e) => setNewListName(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleRenameList(activeListId, newListName)} className="text-4xl md:text-6xl font-black tracking-tighter text-white bg-transparent border-b-2 border-purple-500 outline-none w-full max-w-xl pb-1" />
                <div className="flex gap-2">
                  <button onClick={() => handleRenameList(activeListId, newListName)} className="p-3 bg-purple-500 text-white rounded-2xl hover:bg-purple-600 transition-all"><Check className="w-6 h-6" /></button>
                  <button onClick={() => setEditingListNameId(null)} className="p-3 bg-zinc-800 text-zinc-400 rounded-2xl hover:bg-zinc-700 transition-all"><X className="w-6 h-6" /></button>
                </div>
              </div>
            ) : (
              <div className="flex items-center gap-4 group">
                <h1 className="text-5xl md:text-7xl font-black tracking-tighter text-white truncate max-w-2xl">{activeList?.name || "Din Liste"}</h1>
                <button onClick={() => { setEditingListNameId(activeListId); setNewListName(activeList?.name || ''); }} className="p-3 rounded-2xl bg-white/5 border border-white/5 text-zinc-500 opacity-0 group-hover:opacity-100 hover:text-white hover:bg-white/10 transition-all"><Pencil className="w-5 h-5" /></button>
              </div>
            )}
          </div>
          <SearchInput onAdd={handleAddItem} isLoading={false} />
          <FavoritesBar favorites={favorites} onAdd={handleAddFavoriteToList} onRemove={() => {}} />
          <div className="space-y-3">
            {processingItems.map(p => (
              <div key={p.id} className="flex items-center gap-4 p-5 bg-purple-500/5 border border-purple-500/20 rounded-[1.5rem] animate-pulse">
                <div className="w-10 h-10 bg-purple-500/10 rounded-xl flex items-center justify-center"><Loader2 className="w-5 h-5 text-purple-500 animate-spin" /></div>
                <div className="space-y-1">
                  <span className="text-xs font-black text-white uppercase tracking-widest">AI Analyse...</span>
                  <p className="text-[10px] text-zinc-500 font-medium">Kategoriserer og estimerer pris på {p.query}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
        <GroceryList items={activeList?.items || []} onToggle={(id) => updateItem(id, { completed: !activeList?.items.find(i => i.id === id)?.completed })} onDelete={deleteItem} onUpdate={updateItem} onToggleFavorite={toggleFavorite} />
        {activeList?.items && activeList.items.length > 0 && (
          <div className="mt-16 p-10 glass rounded-[3rem] border-white/5 flex flex-col sm:flex-row justify-between items-center gap-6 relative overflow-hidden group">
            <div className="absolute inset-0 bg-gradient-to-br from-purple-500/5 via-transparent to-blue-500/5 opacity-0 group-hover:opacity-100 transition-opacity duration-700" />
            <div className="relative z-10">
              <p className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.3em] mb-2">Estimeret Totalbeløb</p>
              <h2 className="text-5xl font-black text-white tracking-tighter tabular-nums">{new Intl.NumberFormat('da-DK', { style: 'currency', currency: 'DKK' }).format(grandTotal)}</h2>
            </div>
            <div className="relative z-10 p-5 bg-white/5 rounded-3xl border border-white/5"><Zap className="w-10 h-10 text-purple-400" /></div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GroceryItem } from '../types';
import { CATEGORY_STYLES } from '../constants';
import { 
  CheckCircle2, 
  Circle, 
  Trash2, 
  GripVertical, 
  ShoppingBag, 
  Pencil, 
  Check, 
  X,
  Plus,
  Minus,
  HelpCircle,
  TrendingDown,
  Store,
  Star,
  Info,
  ChevronDown,
  ChevronUp
} from 'lucide-react';

interface GroceryListProps {
  items: GroceryItem[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<GroceryItem>) => void;
  onToggleFavorite?: (item: GroceryItem) => void;
}

const GroceryList: React.FC<GroceryListProps> = ({ items, onToggle, onDelete, onUpdate, onToggleFavorite }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showSourcesId, setShowSourcesId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editCategory, setEditCategory] = useState('');
  const [editPrice, setEditPrice] = useState<string>('');

  const groups: Record<string, GroceryItem[]> = items.reduce((acc, item) => {
    if (!acc[item.category]) acc[item.category] = [];
    acc[item.category].push(item);
    return acc;
  }, {} as Record<string, GroceryItem[]>);

  const sortedCategories = Object.keys(groups).sort();

  const handleQuantity = (item: GroceryItem, delta: number) => {
    const nextQty = Math.max(1, item.quantity + delta);
    onUpdate(item.id, { quantity: nextQty });
  };

  const startEditing = (item: GroceryItem) => {
    if (item.completed) return;
    setEditingId(item.id);
    setEditName(item.name);
    setEditCategory(item.category);
    setEditPrice(item.price?.toString() || '');
  };

  const saveEditing = () => {
    if (editingId) {
      const rawPrice = parseFloat(editPrice);
      const parsedPrice = isNaN(rawPrice) ? undefined : Math.max(0, rawPrice);

      onUpdate(editingId, { 
        name: editName, 
        category: editCategory,
        color: CATEGORY_STYLES[editCategory]?.color || CATEGORY_STYLES['Andet'].color,
        price: parsedPrice
      });
      setEditingId(null);
    }
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('da-DK', {
      style: 'currency',
      currency: 'DKK',
    }).format(val);
  };

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-32 text-zinc-500 animate-in fade-in duration-1000">
        <div className="w-20 h-20 bg-zinc-900/50 rounded-3xl flex items-center justify-center mb-6 ring-1 ring-zinc-800/50 shadow-2xl">
          <ShoppingBag className="w-10 h-10 opacity-10" />
        </div>
        <p className="text-xl font-semibold text-zinc-400 tracking-tight">Listen er tom</p>
        <p className="text-sm text-zinc-600 mt-2 font-medium">Hvad skal vi have i dag?</p>
      </div>
    );
  }

  return (
    <div className="space-y-16 mt-12 pb-12">
      {sortedCategories.map((cat) => {
        const categoryItems = groups[cat];

        return (
          <div key={cat} className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="flex items-end gap-4 mb-8 group/cat">
              <div 
                className="w-14 h-14 rounded-[1.25rem] flex items-center justify-center text-white shadow-2xl transition-transform duration-500 group-hover/cat:scale-105"
                style={{ 
                  backgroundColor: CATEGORY_STYLES[cat]?.color || '#71717a',
                  boxShadow: `0 10px 30px -10px ${CATEGORY_STYLES[cat]?.color}44`
                }}
              >
                {CATEGORY_STYLES[cat]?.icon || CATEGORY_STYLES['Andet'].icon}
              </div>
              <div className="pb-1">
                <h3 className="font-black text-2xl text-zinc-100 tracking-tighter leading-none">{cat}</h3>
                <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-[0.25em] mt-2 flex items-center gap-2">
                  <span className="w-1 h-1 rounded-full bg-zinc-800" />
                  {categoryItems.length} {categoryItems.length === 1 ? 'genstand' : 'genstande'}
                </p>
              </div>
              <div className="flex-1 h-px bg-zinc-800/50 mb-3 ml-2" />
            </div>

            <div className="grid grid-cols-1 gap-4">
              {categoryItems.map((item) => {
                const isEditing = editingId === item.id;
                const isSourcesOpen = showSourcesId === item.id;

                return (
                  <div 
                    key={item.id}
                    className={`group relative flex flex-col bg-[#121214]/60 hover:bg-[#18181b]/80 rounded-[1.5rem] border border-zinc-800/40 transition-all duration-300 ${item.completed ? 'opacity-40 grayscale-[0.8]' : ''} ${isEditing ? 'ring-2 ring-purple-500/50 bg-[#18181b] border-purple-500/20 shadow-[0_0_40px_-10px_rgba(168,85,247,0.15)]' : 'hover:shadow-[0_20px_40px_-15px_rgba(0,0,0,0.5)] hover:-translate-y-0.5'}`}
                  >
                    <div className="flex items-center gap-5 p-5">
                      {!isEditing && (
                        <button 
                          onClick={() => onToggle(item.id)}
                          className="shrink-0 group/check"
                        >
                          <div className={`w-7 h-7 rounded-full flex items-center justify-center transition-all duration-300 ${item.completed ? 'bg-purple-500 text-white scale-100' : 'bg-zinc-800/50 text-transparent border border-zinc-700/50 group-hover/check:border-purple-500/50 group-hover/check:bg-purple-500/10'}`}>
                            {item.completed ? (
                              <Check className="w-4 h-4" strokeWidth={3} />
                            ) : (
                              <div className="w-1.5 h-1.5 rounded-full bg-purple-500 opacity-0 group-hover/check:opacity-100 transition-opacity" />
                            )}
                          </div>
                        </button>
                      )}

                      <div className="w-16 h-16 shrink-0 rounded-2xl bg-zinc-900/80 flex items-center justify-center overflow-hidden border border-zinc-800/50 shadow-inner group-hover:scale-105 transition-transform duration-500">
                        {item.imageUrl ? (
                          <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                        ) : (
                          <span className="text-3xl filter drop-shadow-lg">{item.emoji}</span>
                        )}
                      </div>

                      <div className="flex-1 min-w-0">
                        {isEditing ? (
                          <div className="grid grid-cols-1 gap-3">
                            <input
                              autoFocus
                              value={editName}
                              onChange={(e) => setEditName(e.target.value)}
                              className="w-full bg-zinc-950/50 border border-zinc-800 rounded-xl px-4 py-2.5 text-sm text-white focus:ring-2 focus:ring-purple-500/50 focus:border-purple-500/50 outline-none transition-all"
                              placeholder="Varenavn"
                            />
                            <div className="flex gap-2">
                              <select
                                value={editCategory}
                                onChange={(e) => setEditCategory(e.target.value)}
                                className="flex-1 bg-zinc-950/50 border border-zinc-800 rounded-xl px-3 py-2 text-[10px] text-zinc-300 font-bold uppercase tracking-widest outline-none focus:ring-2 focus:ring-purple-500/50"
                              >
                                {Object.keys(CATEGORY_STYLES).map(c => (
                                  <option key={c} value={c}>{c}</option>
                                ))}
                              </select>
                              <div className="relative w-32">
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500 text-[10px] font-bold">kr.</div>
                                <input
                                  type="number"
                                  min="0"
                                  step="0.01"
                                  value={editPrice}
                                  onChange={(e) => setEditPrice(e.target.value)}
                                  className="w-full bg-zinc-950/50 border border-zinc-800 rounded-xl pl-8 pr-3 py-2 text-xs text-white outline-none focus:ring-2 focus:ring-purple-500/50"
                                  placeholder="0,00"
                                />
                              </div>
                            </div>
                          </div>
                        ) : (
                          <div className="flex flex-col">
                            <div className="flex items-center gap-2 mb-1">
                              <h4 className={`text-lg font-bold text-zinc-100 tracking-tight leading-snug truncate ${item.completed ? 'line-through text-zinc-600 decoration-purple-500/30' : ''}`}>
                                {item.name}
                              </h4>
                              {item.brand && (
                                <span className="shrink-0 px-2 py-0.5 rounded-md bg-zinc-800/50 border border-zinc-700/30 text-[9px] font-black text-zinc-500 uppercase tracking-widest">
                                  {item.brand}
                                </span>
                              )}
                            </div>

                            <div className="flex items-center gap-3">
                              <div className="flex items-center gap-1 px-2 py-0.5 rounded-lg bg-purple-500/5 border border-purple-500/10">
                                <span className="text-[10px] font-black text-purple-400 uppercase tracking-tighter">{item.quantity} stk</span>
                              </div>

                              <div className="h-3 w-px bg-zinc-800/50" />

                              {item.price !== undefined ? (
                                <div className="flex items-center gap-2">
                                  <span className="text-[10px] font-bold text-zinc-400 tabular-nums">
                                    {formatCurrency(item.price)}
                                  </span>
                                  {item.priceSources && item.priceSources.length > 0 && (
                                    <button 
                                      onClick={() => setShowSourcesId(isSourcesOpen ? null : item.id)}
                                      className={`flex items-center gap-1 px-1.5 py-0.5 rounded-md border transition-all ${isSourcesOpen ? 'bg-purple-500 text-white border-purple-400' : 'bg-zinc-800/80 border-zinc-700/50 text-zinc-500 hover:text-zinc-300'}`}
                                    >
                                      <Store className="w-2.5 h-2.5" />
                                      <span className="text-[8px] font-bold uppercase tracking-tighter">Priskilder</span>
                                      {isSourcesOpen ? <ChevronDown className="w-2 h-2 ml-0.5" /> : <ChevronRight className="w-2 h-2 ml-0.5" />}
                                    </button>
                                  )}
                                </div>
                              ) : (
                                <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-zinc-900/50 border border-dashed border-zinc-800">
                                  <HelpCircle className="w-3 h-3 text-zinc-700" />
                                  <span className="text-[9px] font-bold text-zinc-700 uppercase tracking-widest">Ingen pris fundet</span>
                                </div>
                              )}
                            </div>
                          </div>
                        )}
                      </div>

                      {!isEditing && !item.completed && (
                        <div className="flex items-center gap-3">
                          <button 
                            onClick={() => onToggleFavorite?.(item)}
                            className={`flex items-center gap-2 px-3 py-2 rounded-xl border transition-all duration-300 group/fav ${item.isFavorite ? 'text-purple-400 bg-purple-500/10 border-purple-500/20' : 'text-zinc-600 bg-zinc-900/30 border-zinc-800/50 hover:text-purple-400 hover:border-purple-500/30 opacity-0 group-hover:opacity-100'}`}
                            title={item.isFavorite ? "Fjern fra favoritter" : "Gem som favorit"}
                          >
                            <Star className={`w-3.5 h-3.5 ${item.isFavorite ? 'fill-purple-500' : ''}`} />
                            <span className="text-[9px] font-black uppercase tracking-widest hidden md:inline">
                              {item.isFavorite ? 'Favorit' : 'Gem favorit'}
                            </span>
                          </button>

                          <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-x-2 group-hover:translate-x-0">
                            <div className="flex items-center bg-zinc-900/80 border border-zinc-800 rounded-xl p-1 shadow-2xl">
                              <button onClick={() => handleQuantity(item, -1)} className="p-1.5 text-zinc-500 hover:text-white hover:bg-zinc-800 rounded-lg transition-colors">
                                <Minus className="w-3.5 h-3.5" />
                              </button>
                              <div className="w-px h-3 bg-zinc-800 mx-0.5" />
                              <button onClick={() => handleQuantity(item, 1)} className="p-1.5 text-zinc-500 hover:text-white hover:bg-zinc-800 rounded-lg transition-colors">
                                <Plus className="w-3.5 h-3.5" />
                              </button>
                            </div>

                            <div className="flex items-center bg-zinc-900/80 border border-zinc-800 rounded-xl p-1 shadow-2xl">
                              <button onClick={() => startEditing(item)} className="p-1.5 text-zinc-500 hover:text-purple-400 hover:bg-purple-400/10 rounded-lg transition-all">
                                <Pencil className="w-3.5 h-3.5" />
                              </button>
                              <button onClick={() => onDelete(item.id)} className="p-1.5 text-zinc-500 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all">
                                <Trash2 className="w-3.5 h-3.5" />
                              </button>
                            </div>
                          </div>
                        </div>
                      )}

                      {isEditing && (
                        <div className="flex flex-col gap-2 shrink-0 animate-in fade-in zoom-in-95 duration-200">
                          <button onClick={saveEditing} className="w-10 h-10 bg-green-500/10 text-green-400 hover:bg-green-500 hover:text-white rounded-xl transition-all flex items-center justify-center border border-green-500/20">
                            <Check className="w-5 h-5" strokeWidth={3} />
                          </button>
                          <button onClick={() => setEditingId(null)} className="w-10 h-10 bg-zinc-800/50 text-zinc-500 hover:bg-zinc-800 hover:text-white rounded-xl transition-all flex items-center justify-center border border-zinc-700/30">
                            <X className="w-5 h-5" />
                          </button>
                        </div>
                      )}
                    </div>

                    {/* Inline Expandable Price Sources Section */}
                    {isSourcesOpen && item.priceSources && (
                      <div className="mx-5 mb-5 p-4 bg-zinc-900/60 rounded-2xl border border-white/5 animate-in slide-in-from-top-2 duration-300">
                        <div className="flex items-center justify-between mb-3 px-1">
                          <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Markedspriser (AI)</p>
                          <span className="text-[10px] text-zinc-600 font-bold">Danmark</span>
                        </div>
                        <div className="space-y-2.5">
                          {item.priceSources.map((source, idx) => (
                            <div key={idx} className="flex items-center justify-between">
                              <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-lg bg-white/5 border border-white/5 flex items-center justify-center">
                                  <Store className="w-3.5 h-3.5 text-purple-400" />
                                </div>
                                <span className="text-xs font-bold text-zinc-200">{source.store}</span>
                              </div>
                              <span className="text-xs font-black text-zinc-100 tabular-nums">
                                {formatCurrency(source.price)}
                              </span>
                            </div>
                          ))}
                        </div>
                        <div className="mt-4 pt-3 border-t border-white/5 flex items-center gap-2">
                          <Info className="w-3 h-3 text-zinc-600" />
                          <p className="text-[9px] text-zinc-600 font-medium italic leading-none">
                            Priserne er indhentet via AI og kan variere lokalt.
                          </p>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default GroceryList;

import React, { useState } from 'react';
import { GroceryItem } from '../types';
import { CATEGORY_STYLES } from '../constants';
import { 
  CheckCircle2, 
  Circle, 
  Trash2, 
  GripVertical, 
  ShoppingBag, 
  Pencil, 
  Check, 
  X,
  Plus,
  Minus,
  HelpCircle,
  TrendingDown,
  Store,
  Star,
  Info,
  ChevronDown,
  ChevronUp,
  ChevronRight
} from 'lucide-react';

interface GroceryListProps {
  items: GroceryItem[];
  onToggle: (id: string) => void;
  onDelete: (id: string) => void;
  onUpdate: (id: string, updates: Partial<GroceryItem>) => void;
  onToggleFavorite?: (item: GroceryItem) => void;
}

const GroceryList: React.FC<GroceryListProps> = ({ items, onToggle, onDelete, onUpdate, onToggleFavorite }) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showSourcesId, setShowSourcesId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editCategory, setEditCategory] = useState('');
  const [editPrice, setEditPrice] = useState<string>('');

  const groups: Record<string, GroceryItem[]> = items.reduce((acc, item) => {
    if (!acc[item.category]) acc[item.category] = [];
    acc[item.category].push(item);
    return acc;
  }, {} as Record<string, GroceryItem[]>);

  const sortedCategories = Object.keys(groups).sort();

  const handleQuantity = (item: GroceryItem, delta: number) => {
    const nextQty = Math.max(1, item.quantity + delta);
    onUpdate(item.id, { quantity: nextQty });
  };

  const startEditing = (item: GroceryItem) => {
    if (item.completed) return;
    setEditingId(item.id);
    setEditName(item.name);
    setEditCategory(item.category);
    setEditPrice(item.price?.toString() || '');
  };

  const saveEditing = () => {
    if (editingId) {
      const rawPrice = parseFloat(editPrice);
      const parsedPrice = isNaN(rawPrice) ? undefined : Math.max(0, rawPrice);

      onUpdate(editingId, { 
        name: editName, 
        category: editCategory,
        color: CATEGORY_STYLES[editCategory]?.color || CATEGORY_STYLES['Andet'].color,
        price: parsedPrice
      });
      setEditingId(null);
    }
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('da-DK', {
      style: 'currency',
      currency: 'DKK',
    }).format(val);
  };

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-32 text-zinc-500 animate-in fade-in duration-1000">
        <div className="w-20 h-20 bg-zinc-900/50 rounded-3xl flex items-center justify-center mb-6 ring-1 ring-zinc-800/50 shadow-2xl">
          <ShoppingBag className="w-10 h-10 opacity-10" />
        </div>
        <p className="text-xl font-semibold text-zinc-400 tracking-tight">Listen er tom</p>
        <p className="text-sm text-zinc-600 mt-2 font-medium">Hvad skal vi have i dag?</p>
      </div>
    );
  }

  return (
    <div className="space-y-16 mt-12 pb-12">
      {sortedCategories.map((cat) => {
        const categoryItems = groups[cat];

        return (
          <div key={cat} className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="flex items-end gap-4 mb-8 group/cat">
              <div 
                className="w-14 h-14 rounded-[1.25rem] flex items-center justify-center text-white shadow-2xl transition-transform duration-500 group-hover/cat:scale-105"
                style={{ 
                  backgroundColor: CATEGORY_STYLES[cat]?.color || '#71717a',
                  boxShadow: `0 10px 30px -10px ${CATEGORY_STYLES[cat]?.color}44`
                }}
              >
                {CATEGORY_STYLES[cat]?.icon || CATEGORY_STYLES['Andet'].icon}
              </div>
              <div className="pb-1">
                <h3 className="font-black text-2xl text-zinc-100 tracking-tighter leading-none">{cat}</h3>
                <p className="text-[10px] text-zinc-500 font-bold uppercase tracking-[0.25em] mt-2 flex items-center gap-2">
                  <span className="w-1 h-1 rounded-full bg-zinc-800" />
                  {categoryItems.length} {categoryItems.length === 1 ? 'genstand' : 'genstande'}
                </p>
              </div>
              <div className="flex-1 h-px bg-zinc-800/50 mb-3 ml-2" />
            </div>

            <div className="grid grid-cols-1 gap-4">
              {categoryItems.map((item) => {
                const isEditing = editingId === item.id;
                const isSourcesOpen = showSourcesId === item.id;

                return (
                  <div 
                    key={item.id}
                    className={`group relative flex flex-col bg-[#121214]/60 hover:bg-[#18181b]/80 rounded-[1.5rem] border border-zinc-800/40 transition-all duration-300 ${item.completed ? 'opacity-40 grayscale-[0.8]' : ''} ${isEditing ? 'ring-2 ring-purple-500/50 bg-[#18181b] border-purple-500/20 shadow-[0_0_40px_-10px_rgba(168,85,247,0.15)]' : 'hover:shadow-[0_20px_40px_-15px_rgba(0,0,0,0.5)] hover:-translate-y-0.5'}`}
                  >
                    <div className="flex items-center gap-5 p-5">
                      {!isEditing && (
                        <button 
                          onClick={() => onToggle(item.id)}
                          className="shrink-0 group/check"
                        >
                          <div className={`w-7 h-7 rounded-full flex items-center justify-center transition-all duration-300 ${item.completed ? 'bg-purple-500 text-white scale-100' : 'bg-zinc-800/50 text-transparent border border-zinc-700/50 group-hover/check:border-purple-500/50 group-hover/check:bg-purple-500/10'}`}>
                            {item.completed ? (
                              <Check className="w-4 h-4" strokeWidth={3} />
                            ) : (
                              <div className="w-1.5 h-1.5 rounded-full bg-purple-500 opacity-0 group-hover/check:opacity-100 transition-opacity" />
                            )}
                          </div>
                        </button>
                      )}

                      <div className="w-16 h-16 shrink-0 rounded-2xl bg-zinc-900/80 flex items-center justify-center overflow-hidden border border-zinc-800/50 shadow-inner group-hover:scale-105 transition-transform duration-500">
                        {item.imageUrl ? (
                          <img src={item.imageUrl} alt={item.name} className="w-full h-full object-cover" />
                        ) : (
                          <span className="text-3xl filter drop-shadow-lg">{item.emoji}</span>
                        )}
                      </div>

                      <div className="flex-1 min-w-0">
                        {isEditing ? (
                          <div className="grid grid-cols-1 gap-3">
                            <input
                              autoFocus
                              value={editName}
                              onChange={(e) => setEditName(e.target.value)}
                              className="w-full bg-zinc-950/50 border border-zinc-800 rounded-xl px-4 py-2.5 text-sm text-white focus:ring-2 focus:ring-purple-500/50 focus:border-purple-500/50 outline-none transition-all"
                              placeholder="Varenavn"
                            />
                            <div className="flex gap-2">
                              <select
                                value={editCategory}
                                onChange={(e) => setEditCategory(e.target.value)}
                                className="flex-1 bg-zinc-950/50 border border-zinc-800 rounded-xl px-3 py-2 text-[10px] text-zinc-300 font-bold uppercase tracking-widest outline-none focus:ring-2 focus:ring-purple-500/50"
                              >
                                {Object.keys(CATEGORY_STYLES).map(c => (
                                  <option key={c} value={c}>{c}</option>
                                ))}
                              </select>
                              <div className="relative w-32">
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500 text-[10px] font-bold">kr.</div>
                                <input
                                  type="number"
                                  min="0"
                                  step="0.01"
                                  value={editPrice}
                                  onChange={(e) => setEditPrice(e.target.value)}
                                  className="w-full bg-zinc-950/50 border border-zinc-800 rounded-xl pl-8 pr-3 py-2 text-xs text-white outline-none focus:ring-2 focus:ring-purple-500/50"
                                  placeholder="0,00"
                                />
                              </div>
                            </div>
                          </div>
                        ) : (
                          <div className="flex flex-col">
                            <div className="flex items-center gap-2 mb-1">
                              <h4 className={`text-lg font-bold text-zinc-100 tracking-tight leading-snug truncate ${item.completed ? 'line-through text-zinc-600 decoration-purple-500/30' : ''}`}>
                                {item.name}
                              </h4>
                              {item.brand && (
                                <span className="shrink-0 px-2 py-0.5 rounded-md bg-zinc-800/50 border border-zinc-700/30 text-[9px] font-black text-zinc-500 uppercase tracking-widest">
                                  {item.brand}
                                </span>
                              )}
                            </div>

                            <div className="flex items-center gap-3">
                              <div className="flex items-center gap-1 px-2 py-0.5 rounded-lg bg-purple-500/5 border border-purple-500/10">
                                <span className="text-[10px] font-black text-purple-400 uppercase tracking-tighter">{item.quantity} stk</span>
                              </div>

                              <div className="h-3 w-px bg-zinc-800/50" />

                              {item.price !== undefined ? (
                                <div className="flex items-center gap-2">
                                  <span className="text-[10px] font-bold text-zinc-400 tabular-nums">
                                    {formatCurrency(item.price)}
                                  </span>
                                  {item.priceSources && item.priceSources.length > 0 && (
                                    <button 
                                      onClick={() => setShowSourcesId(isSourcesOpen ? null : item.id)}
                                      className={`flex items-center gap-1 px-1.5 py-0.5 rounded-md border transition-all ${isSourcesOpen ? 'bg-purple-500 text-white border-purple-400' : 'bg-zinc-800/80 border-zinc-700/50 text-zinc-500 hover:text-zinc-300'}`}
                                    >
                                      <Store className="w-2.5 h-2.5" />
                                      <span className="text-[8px] font-bold uppercase tracking-tighter">Priskilder</span>
                                      {isSourcesOpen ? <ChevronDown className="w-2 h-2 ml-0.5" /> : <ChevronRight className="w-2 h-2 ml-0.5" />}
                                    </button>
                                  )}
                                </div>
                              ) : (
                                <div className="flex items-center gap-1.5 px-2 py-1 rounded-md bg-zinc-900/50 border border-dashed border-zinc-800">
                                  <HelpCircle className="w-3 h-3 text-zinc-700" />
                                  <span className="text-[9px] font-bold text-zinc-700 uppercase tracking-widest">Ingen pris fundet</span>
                                </div>
                              )}
                            </div>
                          </div>
                        )}
                      </div>

                      {!isEditing && !item.completed && (
                        <div className="flex items-center gap-3">
                          <button 
                            onClick={() => onToggleFavorite?.(item)}
                            className={`flex items-center gap-2 px-3 py-2 rounded-xl border transition-all duration-300 group/fav ${item.isFavorite ? 'text-purple-400 bg-purple-500/10 border-purple-500/20' : 'text-zinc-600 bg-zinc-900/30 border-zinc-800/50 hover:text-purple-400 hover:border-purple-500/30 opacity-0 group-hover:opacity-100'}`}
                            title={item.isFavorite ? "Fjern fra favoritter" : "Gem som favorit"}
                          >
                            <Star className={`w-3.5 h-3.5 ${item.isFavorite ? 'fill-purple-500' : ''}`} />
                            <span className="text-[9px] font-black uppercase tracking-widest hidden md:inline">
                              {item.isFavorite ? 'Favorit' : 'Gem favorit'}
                            </span>
                          </button>

                          <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-x-2 group-hover:translate-x-0">
                            <div className="flex items-center bg-zinc-900/80 border border-zinc-800 rounded-xl p-1 shadow-2xl">
                              <button onClick={() => handleQuantity(item, -1)} className="p-1.5 text-zinc-500 hover:text-white hover:bg-zinc-800 rounded-lg transition-colors">
                                <Minus className="w-3.5 h-3.5" />
                              </button>
                              <div className="w-px h-3 bg-zinc-800 mx-0.5" />
                              <button onClick={() => handleQuantity(item, 1)} className="p-1.5 text-zinc-500 hover:text-white hover:bg-zinc-800 rounded-lg transition-colors">
                                <Plus className="w-3.5 h-3.5" />
                              </button>
                            </div>

                            <div className="flex items-center bg-zinc-900/80 border border-zinc-800 rounded-xl p-1 shadow-2xl">
                              <button onClick={() => startEditing(item)} className="p-1.5 text-zinc-500 hover:text-purple-400 hover:bg-purple-400/10 rounded-lg transition-all">
                                <Pencil className="w-3.5 h-3.5" />
                              </button>
                              <button onClick={() => onDelete(item.id)} className="p-1.5 text-zinc-500 hover:text-red-400 hover:bg-red-400/10 rounded-lg transition-all">
                                <Trash2 className="w-3.5 h-3.5" />
                              </button>
                            </div>
                          </div>
                        </div>
                      )}

                      {isEditing && (
                        <div className="flex flex-col gap-2 shrink-0 animate-in fade-in zoom-in-95 duration-200">
                          <button onClick={saveEditing} className="w-10 h-10 bg-green-500/10 text-green-400 hover:bg-green-500 hover:text-white rounded-xl transition-all flex items-center justify-center border border-green-500/20">
                            <Check className="w-5 h-5" strokeWidth={3} />
                          </button>
                          <button onClick={() => setEditingId(null)} className="w-10 h-10 bg-zinc-800/50 text-zinc-500 hover:bg-zinc-800 hover:text-white rounded-xl transition-all flex items-center justify-center border border-zinc-700/30">
                            <X className="w-5 h-5" />
                          </button>
                        </div>
                      )}
                    </div>

                    {/* Inline Expandable Price Sources Section */}
                    {isSourcesOpen && item.priceSources && (
                      <div className="mx-5 mb-5 p-4 bg-zinc-900/60 rounded-2xl border border-white/5 animate-in slide-in-from-top-2 duration-300">
                        <div className="flex items-center justify-between mb-3 px-1">
                          <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Markedspriser (AI)</p>
                          <span className="text-[10px] text-zinc-600 font-bold">Danmark</span>
                        </div>
                        <div className="space-y-2.5">
                          {item.priceSources.map((source, idx) => (
                            <div key={idx} className="flex items-center justify-between">
                              <div className="flex items-center gap-3">
                                <div className="w-8 h-8 rounded-lg bg-white/5 border border-white/5 flex items-center justify-center">
                                  <Store className="w-3.5 h-3.5 text-purple-400" />
                                </div>
                                <span className="text-xs font-bold text-zinc-200">{source.store}</span>
                              </div>
                              <span className="text-xs font-black text-zinc-100 tabular-nums">
                                {formatCurrency(source.price)}
                              </span>
                            </div>
                          ))}
                        </div>
                        <div className="mt-4 pt-3 border-t border-white/5 flex items-center gap-2">
                          <Info className="w-3 h-3 text-zinc-600" />
                          <p className="text-[9px] text-zinc-600 font-medium italic leading-none">
                            Priserne er indhentet via AI og kan variere lokalt.
                          </p>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default GroceryList;
